/**
 * ★通话邀请消息在气泡里的样子（对齐飞书）。
 *
 * <h2>★为什么状态只能来自内存</h2>
 *
 * <p>服务端的 {@code voip} 消息只带邀请本身（{@code callId}/{@code mediaType}/{@code roomName}），
 * <b>不持久化</b>"接通了多久 / 被拒了 / 没人接"。这些结果只存在于
 * {@code store/call} 的 {@code records} 里，刷新页面就没了 —— 所以：
 * <ul>
 *   <li>有记录（本次会话里打过）⇒ 显示真实结果与通话时长；</li>
 *   <li>没有记录（别人发的、或刷新后）⇒ 显示"点击回拨"，<b>不编造</b>"未接听"。</li>
 * </ul>
 * 这一条与 DEV-251 的"分母没到手时画空环"是同一条纪律：不知道就说不出来。
 *
 * <h2>★回拨为什么查会话列表而不是用 msg.convId 直接造一个</h2>
 *
 * <p>{@code startCall} 需要 {@link ConversationSummaryDto}（标题/头像/单聊判据都从它来）。
 * 拿 {@code convId} 拼一个假对象会让顶栏标题变成一串数字，也会让"是不是单聊"判错；
 * 会话列表里找不到（已被移出）时干脆不给回拨入口。
 */
import type { MessageDto } from '../api/types';
import { parseVoipInvite, voipMediaLabel } from '../lib/voip';
import { useCallStore } from '../store/call';
import { useChatStore } from '../store/chat';
import { IconPhone, IconVideo } from './icons';

interface Props {
  message: MessageDto;
}

const STATUS_TEXT: Record<string, string> = {
  called: '已接通',
  completed: '通话已结束',
  canceled: '已取消',
  declined: '已拒绝',
  missed: '未接听',
  failed: '呼叫失败',
};

export default function VoipCallCard({ message }: Props) {
  const invite = parseVoipInvite(message.body);
  const msgId = message.msgId == null ? undefined : String(message.msgId);
  /** ★按 msgId 取这一通的本地结果；没有就是"未知"（见文件头的纪律）。 */
  const record = useCallStore((s) => (msgId ? s.records[msgId] : undefined));
  const phase = useCallStore((s) => s.phase);
  const currentCall = useCallStore((s) => s.call);
  const conv = useChatStore((s) => s.convs.find((c) => String(c.convId) === String(message.convId)));

  const mediaType = invite?.mediaType ?? record?.mediaType ?? 'audio';
  const label = voipMediaLabel(mediaType);
  const busy = phase === 'incoming' || phase === 'outgoing' || phase === 'connecting' || phase === 'active';
  /**
   * ★这条邀请是不是**正在进行中的那一通**。
   * 没有它的话，自己发起、正在响铃时气泡会写"点击回拨"（而按钮恰恰是禁用的）——
   * 一句话自相矛盾。通话进行中要显示的是"正在呼叫… / 通话中"。
   */
  const isCurrent = !!invite && !!currentCall && currentCall.callId === invite.callId;

  let sub: string;
  if (isCurrent) {
    sub = phase === 'active' ? '通话中' : phase === 'incoming' ? '来电中' : '正在呼叫…';
  } else if (record) {
    if (record.status === 'completed') {
      sub = record.durationSec > 0
        ? `通话时长 ${formatDuration(record.durationSec)}`
        : record.detail || '通话已结束';
    } else {
      sub = record.detail || STATUS_TEXT[record.status] || '通话已结束';
    }
  } else {
    sub = invite ? '点击回拨' : '邀请信息不完整';
  }

  const canCallBack = !!invite && !!conv && !busy;

  return (
    <button
      type="button"
      className={`voip-card${canCallBack ? ' clickable' : ''}`}
      title={canCallBack ? `回拨${label}` : undefined}
      disabled={!canCallBack}
      onClick={
        canCallBack
          ? () => {
            // ★TS 不会把 `canCallBack` 的窄化带进闭包，这里显式再判一次
            if (!conv) return;
            void useCallStore.getState().startCall(conv, mediaType);
          }
          : undefined
      }
    >
      <span className={`voip-card-icon${mediaType === 'video' ? ' is-video' : ''}`}>
        {mediaType === 'video' ? <IconVideo size={18} /> : <IconPhone size={18} />}
      </span>
      <span className="voip-card-text">
        <span className="voip-card-title">{label}</span>
        <span className="voip-card-sub">{sub}</span>
      </span>
    </button>
  );
}

/** 与 lib/voip 的 formatCallDuration 同口径，但这里只要 mm:ss（不显示小时）。 */
function formatDuration(sec: number): string {
  const s = Math.max(0, Math.floor(sec));
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
}
