import { useEffect, useState } from 'react';
import { Alert, App as AntApp, Button, Input, Modal, Typography } from 'antd';
import type { Id } from '../api/types';
import {
  JOIN_REMARK_MAX_CHARS,
  checkJoinRemark,
  charCount,
  joinOutcomeOf,
  looksLikeGroupNo,
  normalizeGroupNo,
  type JoinOutcome,
} from '../lib/joinGroup';
import { isImeConfirm } from '../lib/ime';
import { useChatStore } from '../store/chat';

/**
 * 「按群号加入群聊」弹窗（DEV-197-b）。
 *
 * <h2>★为什么是"输入群号"而不是"搜群名"</h2>
 *
 * <p>服务端<b>刻意不提供群目录</b>（见 {@code lib/joinGroup.ts} 的文件头）：
 * 群号是 19 位雪花号，构成公开，能逐个试探就能把全库群号枚举出来 ——
 * 所以唯一的入口是"我知道群号"，而不是"我搜一下"。
 * ★本弹窗里<b>没有</b>任何"这个群叫什么"的预览：那需要在客户端维护一份群目录，
 * 与上面那条设计正好相反。
 *
 * <h2>★★两个入口共用这一个组件</h2>
 *
 * <p>搜索弹框的「群组」Tab 与智联录「我的群组」入口行旁的按钮都开它 ——
 * 两条路径的校验、四种结果处置、以及"申请被拒时显示理由"必须逐字一致，
 * 所以只有一个实现。
 *
 * <h2>★四种结果里三种会直接把人送进会话</h2>
 *
 * <p>处置全在 {@code lib/joinGroup.ts} 的 {@link joinOutcomeOf}（纯函数、有单测）：
 * {@code member} / {@code approved} 要<b>进会话</b>，{@code pending} / {@code rejected}
 * 留在原地并把话说清楚（{@code rejected} 必须显示审核理由 —— 不显示的话用户只知道
 * "进不去"，只会一直重试到冷却期结束）。
 */
export default function JoinGroupModal({
  open,
  onClose,
  onJoined,
  initialGroupNo,
  hint,
}: {
  open: boolean;
  onClose: () => void;
  /**
   * ★进会话的回调。★由父组件传进来而不是本组件自己调 {@code selectConv}：
   * 两个入口的"进会话之后还要做的事不一样"（搜索弹框要先把搜索关掉再进），
   * 而把 {@code selectConv} 写两遍就会出现"其中一条路径忘了关搜索框"。
   */
  onJoined: (convId: Id) => void;
  /**
   * ★★DEV-356：打开时**预填**的群号（来源是邀请链接里的 {@code ?invite=}）。
   *
   * <p>★不传 = 空框（既有三个入口的行为<b>逐字未变</b>）。
   * ★★<b>不锁</b>这个输入框：锁上之后用户想换成别处的群号就只能关掉重开，
   * 而"同一个人手上有好几个群号"是常事。预填只是省他一次粘贴。
   *
   * <p>★值是<b>字符串</b>（雪花群号，见 {@code lib/joinGroup.ts} 的
   * {@code normalizeGroupNo}）；调用方保证它已经规范化过。
   */
  initialGroupNo?: string;
  /**
   * ★★DEV-356：替换顶部那句说明的文案（邀请链接进来时说清"群号是哪来的"）。
   *
   * <p>★不传 = 原来那句（"群号是一串数字，在「设置」页里可以复制。"）。
   * ★为什么必须可替换：用户点了一条链接，屏幕上冒出的却是「<b>按群号加入群聊</b>」
   * 而框里已经填好了一串数字 —— 不说来源的话，第一反应是"这号码谁填的？"
   */
  hint?: string;
}) {
  const applyJoinByGroupNo = useChatStore((s) => s.applyJoinByGroupNo);
  const { message: toast } = AntApp.useApp();

  const [groupNo, setGroupNo] = useState('');
  const [remark, setRemark] = useState('');
  const [busy, setBusy] = useState(false);
  /** 本地校验错误（群号不合法 / 附言超长）。★与下面 {@link outcome} 分开：一个是"没发出去"，一个是"发出去了的结果"。 */
  const [inputError, setInputError] = useState<string | null>(null);
  /** 服务端结果里"不进会话"的那两种（pending / rejected / unknown）。 */
  const [outcome, setOutcome] = useState<JoinOutcome | null>(null);

  const reset = () => {
    setGroupNo('');
    setRemark('');
    setInputError(null);
    setOutcome(null);
    setBusy(false);
  };

  const close = () => {
    // ★关掉时清空：留着上一次的群号与失败原因，下次打开会让人以为"刚才那次还在"。
    reset();
    onClose();
  };

  /**
   * ★★DEV-356：**打开的那一刻**把邀请链接里的群号填进去。
   *
   * <p>★★时机是判据的一部分，不能挪：{@link reset} 在关闭（{@code close} 与
   * {@code afterClose}）时把群号清空 —— 预填要是发生在"渲染期间"或
   * "父组件传值的那一刻"，它会被紧随其后的那次 {@code reset()} 抹掉，
   * 症状是"弹窗打开了，但群号是空的"（而链接里的号明明是好的）。
   *
   * <p>★依赖里放 {@code initialGroupNo} 不会造成"用户改完又被改回去"：
   * 值没变时 effect 根本不跑（React 按 {@code Object.is} 比依赖），
   * 而值变了只可能是父组件换了一个邀请（那时确实该重填）。
   *
   * <p>★预填<b>不</b>触发任何校验/请求：用户看到框里有个号，点「申请加入」才提交
   * （拍板 {@code confirm}）。
   */
  useEffect(() => {
    if (!open) return;
    setGroupNo(initialGroupNo ?? '');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, initialGroupNo]);

  const remarkCheck = checkJoinRemark(remark);

  const submit = async () => {
    // ---- ① 本地校验（对应服务端的 IM_90001：我连一个候选群号都没得到）
    //   ★本地拦的价值：不白跑一次网络往返，且提示能说人话。
    //   ★第二类失败（群号合法但指不到群，IM_10404）**不在本地判**：
    //     那需要一份群目录，而"不提供群目录"正是服务端反枚举设计的核心。
    const no = normalizeGroupNo(groupNo);
    if (!no) {
      // ★★DEV-323 ②（用户原话「群号位数说明与实现不一致：『加入群组』弹窗提示
      //   『群号是 19 位数字』，去掉 19 位这种具体数值」）：提示里**不再报位数**。
      //   ★理由：实现收的是"1～19 位"，而文案说"19 位"是在把一个<b>上界</b>说成
      //     用户必须满足的<b>长度</b> —— 手里拿着一个短号的人会以为自己抄错了。
      //   ★判据（到底几位算合法）仍然只有 {@code normalizeGroupNo} 一处，
      //     这里只负责把"不合法"这件事说清楚。
      setInputError('群号应为数字（可直接粘贴，空格与短横线会被忽略）');
      setOutcome(null);
      return;
    }
    // ---- ② 附言超长（本地拦，因为下面那个 TextArea **刻意没有 maxLength**）
    //   ★★不设 maxLength 的理由<b>不是</b>计数单位不同（两边都是 UTF-16 码元，
    //     见 lib/joinGroup.ts 的文件头），而是**静默截断**这件事本身：
    //     粘贴一段超长文本时，maxLength 会把它砍到 64 个单元且**不留任何痕迹** ——
    //     用户看到的是"我贴进去了"，发出去的却是半截话；若第 64 个单元恰好落在
    //     一个 emoji 的代理对中间，还会留下半个字符（服务端收到 64 个单元、**照样通过**）。
    //   ★所以拦截点放在提交这一步：让计数行变红、并把话说清楚（配合下面那行实时计数），
    //     而不是在输入路径上替用户做决定。
    if (remarkCheck.error) {
      setInputError(remarkCheck.error);
      setOutcome(null);
      return;
    }
    setInputError(null);
    setOutcome(null);
    setBusy(true);
    try {
      // ★群号按【字符串】传（雪花号，转 number 会被静默改末位，见 normalizeGroupNo）。
      const dto = await applyJoinByGroupNo(no, remarkCheck.value);
      const r = joinOutcomeOf(dto);
      if (r.enterConv && dto?.convId != null) {
        toast.success(r.text);
        // ★先 reset 再回调：onJoined 里父组件可能卸载/切换视图，
        //   此时再 setState 会打到已卸载的组件上。
        reset();
        onJoined(dto.convId);
        return;
      }
      // ★member / approved 但**服务端没给 convId**（不该发生，但契约里 convId 是可空的）：
      //   这时不能"假装进会话"，退化成一句提示 —— 否则会跳到一个 undefined 的会话上。
      setOutcome(
        r.enterConv
          ? { ...r, enterConv: false, level: 'warning', text: `${r.text}（请到「我的群组」里打开它）` }
          : r,
      );
    } catch (e) {
      // ★原样展示服务端文案：IM_10404（群号指不到可加入的群）就是要让用户看见
      //   "这个号不对"，而不该被我们说成"网络错误"。
      setInputError((e as Error).message || '申请失败，请稍后重试');
    } finally {
      setBusy(false);
    }
  };

  return (
    <Modal
      title="按群号加入群聊"
      open={open}
      onCancel={close}
      // ★footer 自己给：默认的「确定」按钮文字在这里说不清要干什么（"确定加入"会让人
      //   以为点了就进去了，而实际可能只是提交申请）。
      footer={(
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
          <Button onClick={close}>关闭</Button>
          <Button type="primary" loading={busy} onClick={() => submit().catch(() => undefined)}>
            申请加入
          </Button>
        </div>
      )}
      afterClose={reset}
      width={420}
    >
      <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
        {/* ★★DEV-323 ②：不再写死位数（原来这里逐字是「群号是 19 位数字，在『设置』页里
            可以复制。」）—— 详见上面 submit 里那段注释。
            ★★DEV-356：默认那句可以被 `hint` 替换（邀请链接进来的场景要说清群号来源）。 */}
        {hint ?? '群号是一串数字，在「设置」页里可以复制。'}
      </Typography.Paragraph>

      <Input
        placeholder="输入群号"
        value={groupNo}
        onChange={(e) => {
          setGroupNo(e.target.value);
          // ★边打字边清掉上一次的错误：不清的话用户改对了，红字还挂着。
          setInputError(null);
          setOutcome(null);
        }}
        /* ★★DEV-254 需求①：输入法还在选字时按回车**不是**提交（见 lib/ime.ts）。 */
        onPressEnter={(e) => {
          if (isImeConfirm(e)) return;
          submit().catch(() => undefined);
        }}
        // ★inputMode=numeric 只影响移动端键盘，**不能**用来限制输入：
        //   桌面端照样能贴进字母，而真正的判据是 normalizeGroupNo。
        inputMode="numeric"
        // ★不设 maxLength：粘贴一串带空格的群号会被截断成"看起来对但少了两位"，
        //   而 strip 掉空白后本来可能是合法的。超长交给 normalizeGroupNo 的正则判。
        prefix={
          // ★灰字实时提示"看起来对/不对"（looksLikeGroupNo），但**不拦提交**：
          //   提交那一步仍走 normalizeGroupNo，两处用的是同一个判据函数。
          <Typography.Text type={groupNo && !looksLikeGroupNo(groupNo) ? 'danger' : 'secondary'} style={{ fontSize: 12 }}>
            群号
          </Typography.Text>
        }
      />

      <Input.TextArea
        style={{ marginTop: 12 }}
        rows={2}
        placeholder={`申请附言（选填，最多 ${JOIN_REMARK_MAX_CHARS} 字）`}
        value={remark}
        onChange={(e) => {
          setRemark(e.target.value);
          setOutcome(null);
        }}
        // ★★刻意**不设** `maxLength`（理由见 submit 里第 ② 条：静默截断 + 可能劈开代理对）。
        // ★也刻意**不开** antd 的 showCount —— 不是因为单位不同（两边都是 UTF-16 码元，
        //   与后端 String.length() 一致），而是因为它会在**框内右下角**再放一个计数器，
        //   与下面那行"当前 N 字"并排出现两个同样的数字：看着像两套口径，
        //   而用户会开始怀疑该信哪一个。⇒ 下面那一行是**唯一**的计数来源。
      />
      {/* ★计数用 charCount（UTF-16 码元，与后端同一个单位，见 lib/joinGroup.ts 文件头）
          而不是在这里写 `remark.length`：写成裸的 `.length` 看起来像随手写的，
          下一个人很容易"顺手改成 Array.from(...).length 更准" —— 那一改本地就比服务端松。
          ★超限时这一行**自己变红**（不另外弹提示）：用户是在打字的过程中超的，
          提示要出现在他正看着的那个数字上；等到点提交才红，他会以为是提交坏了。 */}
      <Typography.Text type={remarkCheck.error ? 'danger' : 'secondary'} style={{ fontSize: 12 }}>
        {charCount(remark)} / {JOIN_REMARK_MAX_CHARS} 字
      </Typography.Text>

      {inputError && (
        <Alert type="error" showIcon style={{ marginTop: 12 }} message={inputError} />
      )}
      {outcome && (
        <Alert
          type={outcome.level === 'error' ? 'error' : 'warning'}
          showIcon
          style={{ marginTop: 12 }}
          // ★rejected 时 message 里已经带了服务端的审核理由（见 joinOutcomeOf），
          //   所以这里不再补一句自己的话 —— 那会把理由挤到次要位置。
          message={outcome.text}
          description={
            outcome.status === 'pending'
              ? '管理员通过后你会在「我的群组」里看到这个群。'
              : undefined
          }
        />
      )}
    </Modal>
  );
}
