import { useEffect, useState } from 'react';
import { App as AntApp, InputNumber, Modal, Radio } from 'antd';
import { convApi } from '../api';
import type { ConversationMemberDto, Id } from '../api/types';
import { MUTE_DURATION_PRESETS, MUTE_MAX_DURATION_SEC, customMuteSeconds, muteDurationLabel } from '../lib/mute';
import { memberDisplayName } from '../lib/memberList';
import { remarkOf } from '../lib/contact';
import { useChatStore } from '../store/chat';

/**
 * ★★DEV-313 需求5：<b>禁言时长</b>选择弹窗（用户原话：
 * 「预设 10 分钟 / 1 小时 / 12 小时 / 1 天，**另给「自定义」输入**」）。
 *
 * <h2>★为什么是弹窗而不是一个下拉菜单</h2>
 *
 * <p>五选一（四个预设 + 自定义）在 antd 里两种都做得到，但这里的取舍点是
 * <b>「自定义」需要一个输入框</b>：塞进下拉的 {@code Dropdown} 里，输入框会随菜单
 * 一起被"点外面就关"的逻辑收掉（点进输入框本身可能被当成点外面），
 * 而这是个<b>不可逆的治理动作</b>（禁错了要再点一次解除），
 * 值得一个会停在那里等你确认的界面。★{@code Modal.confirm} 也不行 ——
 * 它的内容区在确认框里是静态的，放不进受控输入框。
 *
 * <h2>★★三个刻意的行为</h2>
 * <ol>
 *   <li><b>默认选中第一个预设</b>（10 分钟）：用户点「禁言」按钮的本意已经确定，
 *       弹窗只问"多久"。默认选中最短那一档 —— 禁错了的代价最小，而"解除"
 *       随时可以点（一次点击，见成员行那个按钮）。</li>
 *   <li><b>自定义非法时「确定」禁用 + 一句说明</b>（不是夹取，见
 *       {@code lib/mute.customMuteSeconds}）。★说明里必须写出上限（30 天），
 *       否则用户只知道"填了不行"。</li>
 *   <li><b>提交中禁用重复点击</b>：{@code mute} 是写库动作，双击会发两次请求
 *       （服务端幂等，第二次 {@code affected=0} 不发系统消息 —— 不会造成脏数据，
 *       但第一次的 toast 会被第二次的"已禁言"再叠一遍）。</li>
 * </ol>
 *
 * <p>★提交成功后由外层负责刷新（与 {@code MemberPanelBody.onRemove} 同一套样板：
 * toast → {@code loadMembers} → {@code loadConversations}），本组件不碰 store 的写法，
 * ★<b>但成员显示名要读 store</b>（备注优先，见 {@code lib/contact.remarkOf}）——
 * 弹窗标题里必须写清"禁言谁"，而群里那个名字和我通讯录里的备注可能不一样，
 * 写错名字等于让用户在禁言另一个人时以为是这个人。
 */
export default function MuteDurationModal({
  open,
  convId,
  member,
  onClose,
  onDone,
}: {
  open: boolean;
  convId: Id | null;
  /** 要禁言的那个成员；{@code null} ⇒ 弹窗虽然 open 也没有目标（不渲染内容）。 */
  member: ConversationMemberDto | null;
  onClose: () => void;
  /** ★提交**成功**后回调（由外层刷新名单与会话列表）。 */
  onDone: (seconds: number) => void;
}) {
  /** 选中的预设秒数；{@code null} = 选了「自定义」。 */
  const [preset, setPreset] = useState<number | null>(MUTE_DURATION_PRESETS[0]);
  /** 自定义的**分钟**数（受控）。 */
  const [customMinutes, setCustomMinutes] = useState<number | null>(30);
  const [busy, setBusy] = useState(false);
  const { message: toast } = AntApp.useApp();
  const contacts = useChatStore((s) => s.contacts);

  // ★每次打开都回到初始态：上一次给"张三"选的 12 小时会留给"李四"，
  //   而用户点开时看到的是一个已经选好的档位 —— 他会直接点确定。
  //   这类"上一次的选择"在确认型弹窗里是纯风险，没有任何"记住我的偏好"的价值。
  useEffect(() => {
    if (open) {
      setPreset(MUTE_DURATION_PRESETS[0]);
      setCustomMinutes(30);
      setBusy(false);
    }
  }, [open]);

  const customSec = customMuteSeconds(customMinutes);
  /** ★最终要提交的秒数：{@code null} ⇒ 非法，禁用确定。 */
  const seconds = preset ?? customSec;
  const ok = seconds != null && convId != null && member != null && !busy;

  const onOk = async () => {
    if (convId == null || member == null || seconds == null) return;
    setBusy(true);
    try {
      await convApi.mute(convId, { userIds: [member.userId], durationSec: seconds });
      toast.success(`已禁言 ${muteDurationLabel(seconds)}`);
      onDone(seconds);
      onClose();
    } catch (e) {
      // ★服务端才是权限与合法性的权威（IM_30001 越权 / IM_90001 durationSec 超限 /
      //   IM_20104 不在群）。前端判据只决定"给不给按钮"，被拒时把服务端的话原样说出来。
      toast.error((e as Error).message);
    } finally {
      // ★finally 而不是 catch 后：成功路径上组件已经被关闭了，
      //   但 setState 一个已卸载组件在 React 18 里不再是警告 —— 这里其实是为了
      //   "失败了还能再点一次确定"（不清 busy 的话按钮永远转圈）。
      setBusy(false);
    }
  };

  const rk = member ? remarkOf(contacts, member.userId) : null;

  return (
    <Modal
      /* ★第 4 条拍板：禁言只在群里发生 ⇒ 名字走**群内**链（群名片 → 备注名 → 昵称）。 */
      title={member ? `禁言「${memberDisplayName(member, rk, 'group')}」` : '禁言'}
      open={open}
      onCancel={onClose}
      onOk={() => onOk().catch(() => undefined)}
      okText="确定"
      cancelText="取消"
      okButtonProps={{ disabled: !ok, loading: busy }}
      destroyOnClose
      width={400}
    >
      <Radio.Group
        className="mute-duration-group"
        value={preset ?? 'custom'}
        onChange={(e) => setPreset(e.target.value === 'custom' ? null : Number(e.target.value))}
      >
        {MUTE_DURATION_PRESETS.map((sec) => (
          <Radio key={sec} value={sec} className="mute-duration-item">
            {muteDurationLabel(sec)}
          </Radio>
        ))}
        <Radio value="custom" className="mute-duration-item">
          自定义
        </Radio>
      </Radio.Group>

      {/* ★自定义输入框**恒渲染**（选没选自定义都在），只是未选中时禁用：
          条件渲染会让"自定义"这个选项在未选中时看起来像一个纯文字标签，
          用户点它之后整块内容会跳一下（行高变化）。 */}
      <div className="mute-custom-row">
        <InputNumber
          size="small"
          min={1}
          max={MUTE_MAX_DURATION_SEC / 60}
          precision={0}
          disabled={preset != null}
          value={customMinutes}
          onChange={(v) => setCustomMinutes(typeof v === 'number' ? v : null)}
          onPressEnter={() => {
            if (ok) void onOk();
          }}
          addonAfter="分钟"
          style={{ width: 140 }}
        />
        {preset == null && (
          <span className={customSec == null ? 'mute-custom-hint error' : 'mute-custom-hint'}>
            {customSec == null ? `请填 1 ~ ${MUTE_MAX_DURATION_SEC / 60} 之间的整数分钟（最多 30 天）` : `= ${muteDurationLabel(customSec)}`}
          </span>
        )}
      </div>

      <div className="mute-duration-note">
        被禁言的成员在到期前无法在群里发言，到期自动解除；也可以随时点「解除禁言」提前解除。
      </div>
    </Modal>
  );
}
