export type CallPhase = 'idle' | 'incoming' | 'outgoing' | 'connecting' | 'active' | 'ended';

export interface CallInfo {
  callId: string;
  /** ★邀请消息的 msgId：挂断/超时要带它调 /calls/ended。主叫发完邀请后才有。 */
  msgId?: string;
  convId: string;
  convTitle: string;
  /**
   * ★★这一场是「跟某个人通话」还是「一个会议房间」（「会议」Tab 的发起/加入）。
   *
   * <p>两者的界面几乎是同一个浮层，但**结束条件完全不同** —— 这是本字段存在的唯一理由：
   * <ul>
   *   <li>{@code 'call'}（默认）：1v1 通话。<b>对面走了就是结束</b>
   *       （{@link handlersFor} 的 {@code onRemoteLeft} 直接收场）；</li>
   *   <li>{@code 'room'}：多人会议。<b>别人走不是我的会结束</b> —— 有人在房间里等我、
   *       或者我刚进来还没人 —— 都要一直开着，直到我自己离开或断线。
   *       所以它不受"远端数为 0"和"60 秒没人接"这两条规则约束。</li>
   * </ul>
   * <p>★漏了这个判断的症状很典型：多人会议里第一个离开的人会让所有人都被挂断。
   */
  mode: 'call' | 'room';
  /** 会议标题（仅 {@code room}）：开会记录标题、会中顶栏文案都用它。 */
  title?: string;
  /**
   * ★我自己的 LiveKit identity（{@code tenant:userId:platform}），来自入会令牌。
   *
   * <p>用于在参会人列表里认出"我"：服务端返回的是<b>席位</b>，
   * 同一个人多端会出现多条，聚合时要靠 userId 或 identity 标出自己。
   */
  selfIdentity?: string;
  /**
   * ★★服务端认定的角色（仅 {@code room}）：{@code true}=主持人，{@code false}=参会人，未知为 undefined。
   *
   * <p>来自入会令牌的 {@code role}（{@code MeetingTokenView.role === 'HOST'}），
   * 与后端 {@code isHost()} 同源 —— 房主记在房间 metadata 上，所以
   * <b>主持人断线后重新「加入」也仍然是主持人</b>，而 {@code direction} 那时已经变成
   * {@code 'in'} 了。决定"要不要弹结束/退出确认、能不能结束会议"必须看它，
   * 不能只看 {@code direction}（见 {@code lib/meetingLeave}）。
   */
  isHost?: boolean;
  /**
   * ★本场会议是否允许免登录的游客加入（来自入会令牌，即房间元数据）。
   *
   * <p>房主关掉后，「邀请链接」就不该再发出去 —— 发出去对方也只会看到
   * "该会议未开放游客加入"。{@code undefined} 表示未知（老服务端），按允许处理。
   */
  allowGuest?: boolean;
  /**
   * ★会议时长上限（秒）与会议在服务端的开始时刻（epoch 毫秒），仅 {@code room} 会议。
   *
   * <p>两个值必须成对使用：剩余时长 = 上限 −（now − 开始时刻）。
   * 到点由服务端自动结束，前端只负责展示与最后提醒。
   */
  plannedDurationSec?: number;
  meetingStartedAt?: number;
  peerName?: string;
  peerAvatar?: string;
  /**
   * ★对方用户 id（私聊才有）。
   *
   * <p>开启录音时随 {@code startRecording} 一起上报，服务端把这通电话落成
   * 一条会议记录、<b>双方</b>都写进参会人表 —— 少这一项，对方在自己的
   * 会议列表里就看不到这通电话，录音成了单方面的。
   */
  peerUserId?: string;
  mediaType: VoipMediaType;
  direction: 'out' | 'in';
  roomName: string;
  startedAt: number;
  /** 接通时刻（双方都在房间后才有）。计时器从这里算。 */
  connectedAt?: number;
}

export type CallRecordStatus = 'completed' | 'canceled' | 'declined' | 'missed' | 'failed';

/** 气泡上显示的通话结果。★只存在于内存：服务端没有持久化通话状态。 */
export interface CallRecord {
  status: CallRecordStatus;
  mediaType: VoipMediaType;
  durationSec: number;
  at: number;
  /** 给人看的补充（"已在其他设备接听"等）。 */
  detail?: string;
}

export interface CallEndInfo {
  title: string;
  detail: string;
  at: number;
}

interface CallState {
  phase: CallPhase;
  call: CallInfo | null;
  ended: CallEndInfo | null;
  /** key = msgId。用于让消息气泡显示"已取消 / 通话时长 00:12"。 */
  records: Record<string, CallRecord>;

  micOn: boolean;
  cameraOn: boolean;
  screenOn: boolean;
  /**
   * ★远端正在共享屏幕。
   *
   * <p>★★不能拿 {@code remoteCount > 0} 代替：语音通话里浮层本来不挂 {@code <video>}，
   * 远端共享上来的屏幕轨道就没有元素可挂（"我共享了，对方看不到"）。
   * 有了这个信号，浮层才在**语音通话**里也把画面容器挂出来。
   */
  remoteScreenOn: boolean;
  /** ★远端开着摄像头（语音通话里对方随时可能开，见 livekitRoom 的同名注释）。 */
  remoteCameraOn: boolean;
  audioBlocked: boolean;
  remoteCount: number;
  minimized: boolean;
  /**
   * ★★会中面板是否在**独立窗口**里（{@code components/MeetingPopout.tsx}）。
   *
   * <p>★这个开关不是"界面上某个按钮的状态"，而是<b>同一份状态的两处渲染</b>的选择：
   * 为 {@code true} 时，本页的 {@code CallOverlay} 只留一枚"收回本页"的胶囊，
   * 完整会中面板由独立窗口里那棵 React 树渲染 —— 两边读的是<b>同一个 store</b>，
   * 所以静音/录音/成员列表天然同步，不需要跨窗口消息。
   */
  popout: boolean;
  /**
   * ★主舞台给谁：{@code remote}（默认，看对方）/ {@code local}（看自己）。
   * 1v1 通话里由用户手动切换，对方共享屏幕时不自动抢占主屏。
   */
  mainView: 'remote' | 'local';
  /**
   * ★服务端录制（LiveKit RoomCompositeEgress → S3）。
   *
   * <p>录制发生在 LiveKit 服务端，浏览器不参与编码；{@code files[].downloadUrl}
   * 就是平台取文件用的链接（见 {@link meetingApi.getRecording}）。
   */
  recording: boolean;
  recordingStartedAt: number | null;
  /** 本次录制任务 id（未录制为 null）。轮询/停止都用它。 */
  recordingEgressId: string | null;
  /** LiveKit 返回的原始状态：EGRESS_STARTING / ACTIVE / ENDING / COMPLETE / FAILED / ABORTED。 */
  recordingStatus: string | null;
  /** 正在发起/停止录制请求。 */
  recordingBusy: boolean;
  /** 录制完成后的产物（服务端停止后异步生成，需要轮询才拿得到）。 */
  recordingFile: { url?: string; filename?: string; location?: string } | null;
  /** 媒体/连接错误提示（不中断通话）。 */
  notice: string | null;
  /**
   * ★会中在线成员（原始<b>席位</b>列表，服务端口径）。
   *
   * <p>★不要在组件里直接摊平渲染：同一用户多端会有多条记录，
   * 用 {@code lib/meetingParticipants} 的 {@code aggregateParticipants} 聚合成"人"。
   * 会中每 5 秒刷新一次（见 {@link loadParticipants}）。
   */
  participants: MeetingParticipantView[];

  /** 拉一次在线成员（入会自动拉、轮询也会调；失败静默，不打断会议）。 */
  refreshParticipants: () => Promise<void>;
  /** ★踢出某个用户（仅主持人；服务端扇出到他的全部平台席位）。 */
  kickParticipant: (userId: string) => Promise<void>;
  /** ★静音/取消静音某个用户（仅主持人；轨道级，对方可以自己重新开麦）。 */
  muteParticipant: (userId: string, muted?: boolean) => Promise<void>;
  /** ★全员静音：对"还在说话的人"逐个扇出，<b>不含自己</b>。 */
  muteAll: () => Promise<void>;
  /**
   * ★会中开关（仅主持人）：全员禁言 / 弹幕。
   *
   * <p>服务端把开关写进<b>房间 metadata</b>，LiveKit 立刻推 {@code RoomMetadataChanged}
   * 给房内所有人 —— 界面不需要等 5 秒一次的成员轮询。
   */
  updateRoomSettings: (patch: { muteAll?: boolean; danmaku?: boolean }) => Promise<void>;
  /**
   * ★主持人单独放行 / 收回某个人的发言权。
   *
   * <p>★和 {@link CallState.muteParticipant} 不是一回事：那个只是把对方当前音轨
   * muted（对方能自己点回来）；这里是改<b>发布权限</b>，是全员禁言期间"点开某人的麦"
   * 唯一有效的手段。
   */
  setParticipantMicAllowed: (userId: string, allowed: boolean) => Promise<void>;

  /** 订阅 WS 邀请与 3007 事件。幂等，App 级调用一次。 */
  init: () => void;

  startCall: (conv: ConversationSummaryDto, mediaType: VoipMediaType) => Promise<void>;
  /**
   * ★「会议」栏 → 发起：建一个会议房间（会议号即房间名）并<b>直接进入</b>。
   *
   * @param roomName 指定会议号（预约到点开始时用）；不传则现场生成一个
   * @param title    会议标题（进会议记录时用）
   */
  /**
   * ★从「会议」栏发起一场房间会议（{@code create=true}）。
   *
   * @param allowGuest 是否允许免登录的游客凭邀请链接加入，<b>缺省 false</b>。
   *                   房主在建房弹窗里关掉后，服务端会把开关写进房间元数据，
   *                   匿名访客从此签不到令牌。
   */
  startRoomMeeting: (
    mediaType: VoipMediaType,
    roomName?: string,
    title?: string,
    allowGuest?: boolean,
    /**
     * ★★发起弹窗里预生成的分享 slug（见 `lib/meetingLink.makeShareSlug`）。
     *
     * <p>为什么由调用方给：弹窗在<b>建房之前</b>就允许「复制邀请」，
     * 那时链接必须已经是最终形态（带 slug 而不是 9 位数字）。
     * 服务端校验格式后沿用；不传则自己生成。
     */
    shareSlug?: string,
    /**
     * ★★从哪个会话发起的（群通话用）。传给服务端后会写进
     * {@code im_meeting.conv_id}：会议结束时那条「录制已保存」等系统消息
     * 才能回到群里，会议记录的来源会话也不会丢。
     *
     * <p>★从「会议」栏发起的普通会议不传（与会话无关）。
     */
    convId?: string,
  ) => Promise<void>;
  /**
   * ★「会议」栏 → 加入：凭会议号进入<b>已经存在</b>的房间。
   *
   * <p>★刻意**不**像 {@link startRoomMeeting} 那样先建房：那样任何一串数字都能
   * "加入"出一个空房间，用户会以为自己进对了会场，其实房间里一个人都没有。
   */
  joinRoomMeeting: (roomName: string, mediaType: VoipMediaType, convId?: string) => Promise<void>;
  accept: () => Promise<void>;
  decline: () => void;
  /**
   * 离开（1v1 通话 = 挂断；会议 = 离开）。
   *
   * @param opts.keepRoom ★主持人选了「仅退出」时传 {@code true}：会还开着，
   *                      即使自己是最后一个人也不删房。默认按"最后一个人退出
   *                      ⇒ 会议自动结束"处理（见 {@code lib/meetingLeave}）。
   */
  hangup: (opts?: { keepRoom?: boolean }) => Promise<void>;
  /**
   * ★主持人结束会议：先停云端录制，再删房（房内所有人被踢出），本端收场。
   *
   * <p>★删房成功与否以服务端为准：失败（非 404）只提示、**不**收场 ——
   * "以为散了会，其实别人还在里面开会"比"没散成"更糟。
   */
  endRoomMeeting: () => Promise<void>;

  toggleMic: () => Promise<void>;
  toggleCamera: () => Promise<void>;
  toggleScreenShare: () => Promise<void>;
  toggleRecording: () => Promise<void>;
  retryAudio: () => Promise<void>;

  /** 切换主舞台：自己 / 对方（1v1 通话）。 */
  toggleMainView: () => void;
  setMinimized: (minimized: boolean) => void;
  /** 把会中面板交给独立窗口（{@code true}）或收回本页（{@code false}）。 */
  setPopout: (popout: boolean) => void;
  /**
   * 清掉当前这条提示。
   *
   * <p>★{@code notice} 现在渲染成会中 toast（几秒自动消失），计时器挂在界面层；
   * 界面卸载/换一条提示时由调用方负责清空，避免"上一次的控制台提示"在下次入会时
   * 又冒出来。
   */
  clearNotice: () => void;
  clearEnded: () => void;
}

// ==================================================================== 模块级

let initialized = false;
let timeoutTimer: ReturnType<typeof setTimeout> | null = null;
let soloTimer: ReturnType<typeof setTimeout> | null = null;
let endTimer: ReturnType<typeof setTimeout> | null = null;
/** ★防止 leaveLiveKit 触发的 Disconnected 回调把已经结束的通话再结束一次。 */
let closing = false;

/**
 * ★服务端录制轮询定时器。
 *
 * <p>★必须是模块级：停止录制后 egress 还要把文件传完 S3 才到 COMPLETE，
 * 这段时间通话可能已经结束、store 也已切到 ended/idle —— 定时器不能跟着组件走。
 */
let recPollTimer: ReturnType<typeof setTimeout> | null = null;

/**
 * ★会中成员轮询定时器（仅房间会议）。
 *
 * <p>★成员列表没有推送：LiveKit 的 ParticipantConnected/Disconnected 只在本端收到，
 * 而"谁在会里"要包含<b>我没有直接事件</b>的其他成员变化（别人进出、被静音）。
 * 所以必须轮询 —— 5 秒一次，人少、请求轻。
 */
let partPollTimer: ReturnType<typeof setInterval> | null = null;

/**
 * ★★已经处理过的邀请 callId（只用于"响不响铃"）。
 *
 * <p>只靠 {@code call?.callId} 判重不够：{@code clearEnded()} 之后 call 被清空，
 * 而 WS 重连补投 / 多端消息同步**可能把同一帧再送一次** —— 那会重新进入
 * {@code incoming} 并<b>重新响铃</b>，用户看到的就是"刚挂断又嘟嘟嘟"。
 * 同一 callId 只允许进入响铃流程一次。
 */
const heardCallIds = new Set<string>();

/** 返回 true 表示第一次见到；重复帧返回 false。 */
function firstHeard(callId: string): boolean {
  if (heardCallIds.has(callId)) return false;
  heardCallIds.add(callId);
  // ★只保留最近一段，避免长期挂着无限增长
  if (heardCallIds.size > 200) {
    let drop = heardCallIds.size - 100;
    for (const id of heardCallIds) {
      if (drop-- <= 0) break;
      heardCallIds.delete(id);
    }
  }
  return true;
}

function clearRecPoll(): void {
  if (recPollTimer != null) clearTimeout(recPollTimer);
  recPollTimer = null;
}

function clearParticipantPoll(): void {
  if (partPollTimer != null) clearInterval(partPollTimer);
  partPollTimer = null;
}

function rand(): string {
  return Math.random().toString(36).slice(2, 8);
}

function clearTimer(t: ReturnType<typeof setTimeout> | null): null {
  if (t != null) clearTimeout(t);
  return null;
}

function clearCallTimers(): void {
  timeoutTimer = clearTimer(timeoutTimer);
  soloTimer = clearTimer(soloTimer);
  endTimer = clearTimer(endTimer);
}

function convTitleOf(conv: ConversationSummaryDto | undefined): string {
  if (!conv) return '会话';
  return conv.name || conv.peerName || String(conv.convId);
}

function errText(e: unknown): string {
  if (e instanceof Error && e.message) return e.message;
  return typeof e === 'string' ? e : '网络异常';
}

/**
 * ★服务端 404 要给一句人话，而不是把 HTTP 状态甩给用户。
 *
 * @param notFound 404 时说什么。★"进不去某个房间"和"服务整体没开"是两件事：
 *                 凭会议号加入时，404 的绝大多数原因是<b>号码不对/会议已散</b>，
 *                 说成"音视频服务未开启"会让用户去重启服务。
 */
function humanError(e: unknown, notFound = '音视频服务未开启（会议模块未启用）'): string {
  const msg = errText(e);
  if (/404|not found/i.test(msg)) return notFound;
  /**
   * ★非安全上下文（局域网 http）下 {@code navigator.mediaDevices} 根本不存在，
   * LiveKit 内部直接抛 {@code Cannot read properties of undefined (reading 'getUserMedia')}。
   * 这句话对用户毫无意义，还会让人以为是设备坏了 —— 换成"换个地址打开"的指引。
   */
  if (/getUserMedia/i.test(msg) && /undefined|null/i.test(msg)) {
    return '当前地址无法使用摄像头/麦克风，请用 https 或 localhost 打开';
  }
  if (/permission|NotAllowed|denied/i.test(msg)) return '没有麦克风/摄像头权限';
  return msg;
}

function myDisplayName(): string {
  return useChatStore.getState().userName || '我';
}

/**
 * ★我的头像地址：随入会令牌带进 LiveKit 的 participant attributes。
 *
 * <p>为空就传空串 —— 会中界面据此回落到名字首字，而不是去猜一个默认头像。
 */
function myAvatar(): string {
  return (useChatStore.getState().avatar || '').trim();
}

function deviceId(): string {
  try {
    return currentDeviceId();
  } catch {
    return 'web-unknown';
  }
}

const EMPTY_CALL_MEDIA = {
  micOn: true,
  cameraOn: false,
  screenOn: false,
  remoteScreenOn: false,
  remoteCameraOn: false,
  audioBlocked: false,
  remoteCount: 0,
  minimized: false,
  // ★每场会重新决定"要不要弹独立窗口"：上一场用户关掉了那个窗口，不该影响下一场
  popout: false,
  mainView: 'remote' as 'remote' | 'local',
  recording: false,
  recordingStartedAt: null as number | null,
  recordingEgressId: null as string | null,
  recordingStatus: null as string | null,
  recordingBusy: false,
  recordingFile: null as { url?: string; filename?: string; location?: string } | null,
  notice: null as string | null,
  participants: [] as MeetingParticipantView[],
};

export const useCallStore = create<CallState>((set, get) => {
  /** 把一次通话写进气泡记录；★同一 msgId 只写第一次（避免挂断 + 断线双写）。 */
  function record(call: CallInfo | null, status: CallRecordStatus, detail?: string): void {
    if (!call?.msgId) return;
    const key = String(call.msgId);
    if (get().records[key]) return;
    const durationSec = call.connectedAt
      ? Math.max(0, Math.floor((Date.now() - call.connectedAt) / 1000))
      : 0;
    set((s) => ({
      records: {
        ...s.records,
        [key]: { status, mediaType: call.mediaType, durationSec, at: Date.now(), detail },
      },
    }));
  }

  /**
   * ★把一次 egress 快照落进 store。
   *
   * <p>{@code files[].downloadUrl} 是 LiveKit 回报的可下载链接（S3 侧签名），
   * {@code location} 是对象 key —— 平台取文件的两种方式都在这里。
   */
  function applyRecordingView(view: MeetingRecordingView, egressId: string): void {
    const failed = view.status === 'EGRESS_FAILED' || view.status === 'EGRESS_ABORTED';
    const complete = view.status === 'EGRESS_COMPLETE';
    const live = !complete && !failed;
    const file = view.files?.find((f) => f.downloadUrl || f.location);
    // ★计时从"真正开始录"算起：EGRESS_STARTING 期间 egress 还没产出任何内容，
    //   把这 5~10 秒算进录音时长会让用户对不上文件长度。
    const justActive = view.status === 'EGRESS_ACTIVE' && get().recordingStatus !== 'EGRESS_ACTIVE';
    set({
      recordingStatus: view.status,
      recording: live,
      recordingStartedAt: live
        ? (justActive ? Date.now() : get().recordingStartedAt ?? Date.now())
        : null,
      recordingEgressId: live ? egressId : null,
      recordingBusy: false,
      recordingFile: complete && file
        ? { url: file.downloadUrl, filename: file.filename, location: file.location }
        : get().recordingFile,
      notice: failed
        ? `录制失败：${view.error || view.status}`
        : complete
          ? file
            ? '云端录制已生成'
            : '云端录制已生成，但暂时拿不到下载链接，请稍后到「录制」列表查看'
          : get().notice,
    });
  }

  /** ★轮询录制状态直到终态（停止是异步的，egress 传完 S3 才 COMPLETE）。 */
  function pollRecording(room: string, egressId: string): void {
    clearRecPoll();
    let tries = 0;
    const tick = (): void => {
      recPollTimer = setTimeout(() => {
        if (get().recordingEgressId !== egressId) return;
        void (async () => {
          tries += 1;
          try {
            const view = await meetingApi.getRecording(room, egressId);
            if (get().recordingEgressId !== egressId) return;
            applyRecordingView(view, egressId);
            if (view.status !== 'EGRESS_COMPLETE'
              && view.status !== 'EGRESS_FAILED'
              && view.status !== 'EGRESS_ABORTED') {
              if (tries < 60) tick();
              else set({ recordingBusy: false });
            }
          } catch {
            // ★网络抖动/临时 5xx 不算失败：重试到上限
            if (tries < 60) tick();
            else set({ recordingBusy: false, notice: '查询录制状态失败，请稍后在录制列表查看' });
          }
        })();
      }, 1500);
    };
    tick();
  }

  /** ★发起服务端录制（仅房主 = 主叫；接口由服务端校验）。 */
  async function startServerRecording(call: CallInfo): Promise<void> {
    set({ recordingBusy: true, notice: '正在启动云端录制…' });
    try {
      // ★★开会录音 = 把这通电话转成常规会议：下面这些上下文让服务端
      //    落一条 im_meeting（origin=通话）+ 双方的参会人记录，
      //    录音 key 也会挂到会议下，之后双方都能在会议列表里重新签名下载。
      const view = await meetingApi.startRecording(call.roomName, {
        layout: 'grid',
        // ★★房间会议没有会话：必须传 undefined 而不是空串 ——
        //   空串会被服务端当数字解析失败，整条会议记录就落不下去。
        convId: call.convId ? call.convId : undefined,
        // ★房间会议用用户起的名字；1v1 通话留空，由服务端按参会人拼「张三与李四的通话」
        title: call.mode === 'room' ? call.title || call.convTitle : undefined,
        // ★来源：1=会议 2=通话（口径同 im_meeting.origin）。老服务端会忽略这个字段。
        origin: call.mode === 'room' ? 1 : 2,
        // 1=语音会议 2=视频通话 3=含屏幕共享（口径同 im_meeting.meeting_type）
        meetingType: get().screenOn ? 3 : call.mediaType === 'audio' ? 1 : 2,
        selfDisplayName: myDisplayName(),
        peerDisplayName: call.peerName,
        peerUserId: call.peerUserId,
      });
      clearRecPoll();
      set({
        recordingEgressId: view.egressId,
        recordingStatus: view.status,
        recording: true,
        recordingStartedAt: Date.now(),
        recordingBusy: false,
        recordingFile: null,
        notice: '云端录制已开始',
      });
      pollRecording(call.roomName, view.egressId);
    } catch (e) {
      set({ recordingBusy: false, notice: `启动录制失败：${humanError(e)}` });
    }
  }

  /** ★停止服务端录制；返回时通常仍是 ACTIVE，必须继续轮询到 COMPLETE。 */
  async function stopServerRecording(room: string, egressId: string): Promise<void> {
    set({ recordingBusy: true, notice: '正在结束录制…' });
    try {
      const view = await meetingApi.stopRecording(room, egressId);
      set({
        recording: false,
        recordingStartedAt: null,
        recordingBusy: false,
        recordingStatus: view.status,
        notice: '录制已停止，正在生成录制文件…',
      });
      pollRecording(room, egressId);
    } catch (e) {
      set({ recordingBusy: false, notice: `停止录制失败：${humanError(e)}` });
      throw e;
    }
  }

  /**
   * 静默删房（「最后一个人退出 ⇒ 会议自动结束」）。
   *
   * <p>★★必须<b>在退会之后</b>调：服务端只在房内没人时允许非主持人删房，
   * 调用方自己还挂着的话会被判成"参会人想散会"，直接 NO_PERMISSION。
   *
   * <p>★失败要重试：退会后 LiveKit 侧可能还残留半个心跳。
   * 房间散不掉的后果很隐蔽 —— 后来的人凭会议号能"成功"进到一个空房间，
   * 而所有人都以为这场会早就结束了。
   */
  async function endRoomQuietly(roomName: string): Promise<void> {
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        await meetingApi.deleteRoom(roomName);
        return;
      } catch {
        // ★房间已经不在了（别人先散了 / 空房被回收）也算结束，不必再试
        await new Promise((resolve) => setTimeout(resolve, 700));
      }
    }
  }

  /**
   * ★结束：先落状态、再断连接 —— 顺序反了会被 Disconnected 回调重入。
   *
   * @param opts.endRoomAfterLeave ★最后一个人离开：退会后把房间删掉（会议自动结束）。
   * @param opts.recordingAlreadyStopped ★调用方在收场前已经发过"停止录制"（结束会议那条路径）：
   *        这里不再发第二次，只接着轮询到 COMPLETE —— 否则第二次 stop 会撞上正在 ENDING 的
   *        egress、抛错后被清掉 {@code recordingEgressId}，结束卡片上的录音链接就再也出不来。
   */
  function finish(
    status: CallRecordStatus,
    detail: string,
    opts: { endRoomAfterLeave?: boolean; recordingAlreadyStopped?: boolean } = {},
  ): void {
    const st = get();
    if (st.phase === 'ended' || st.phase === 'idle') {
      // ★已收场不等于铃声一定停了（重复挂断、迟到事件都走这条早退），顺手兜一下
      stopRingtone();
      return;
    }
    const call = st.call;
    /** ★录制是服务端的：通话结束必须让 egress 也停掉，否则它会一直录到空房间超时。 */
    const egressId = st.recordingEgressId;
    const roomName = call?.roomName;
    stopRingtone();
    clearCallTimers();
    // ★成员列表没必要再刷新了（房间已经要断了）；留着定时器会对着已结束的会议发请求
    clearParticipantPoll();
    record(call, status, detail);
    closing = true;
    set({
      phase: 'ended',
      ended: { title: call?.convTitle ?? '通话', detail, at: Date.now() },
      audioBlocked: false,
      minimized: false,
      remoteCount: 0,
      participants: [],
      remoteScreenOn: false,
      remoteCameraOn: false,
      recording: false,
      recordingStartedAt: null,
      // ★recordingEgressId 保持到轮询结束：结束卡片要显示"录音正在生成"
    });
    void (async () => {
      try {
        if (egressId && roomName) {
          if (opts.recordingAlreadyStopped) {
            // ★已经停过了：只接着等文件落地（S3 收尾是异步的）
            pollRecording(roomName, egressId);
          } else {
            try {
              await meetingApi.stopRecording(roomName, egressId);
              pollRecording(roomName, egressId);
            } catch {
              set({ recordingEgressId: null, recordingBusy: false });
            }
          }
        }
      } finally {
        await leaveLiveKit();
        closing = false;
        // ★退会流程全部走完再删房（理由见 endRoomQuietly 的头注释）
        if (opts.endRoomAfterLeave && roomName) void endRoomQuietly(roomName);
      }
    })();
    /**
     * ★"已结束"停留 2.5 秒再自动消失；用户点关闭可提前。
     * ★若录制仍在收尾（egress 传 S3），先把卡片留住 —— 链接只在这里出现，
     *   关早了用户就再也看不到这次录音的下载地址。最多等 60 秒。
     */
    const hardStopAt = Date.now() + 60_000;
    const scheduleClear = (): void => {
      endTimer = setTimeout(() => {
        if (get().phase !== 'ended') return;
        if (get().recordingEgressId != null && Date.now() < hardStopAt) {
          scheduleClear();
          return;
        }
        get().clearEnded();
      }, 2500);
    };
    scheduleClear();
  }

  /**
   * ★这通电话是否**还在进行中**（不只是"callId 还对得上"）。
   *
   * <p>★★为什么不能只比 callId：{@code finish()} 只把 phase 改成 ended，
   * <b>不会清空 call</b>（结束卡片还要用它的标题）。于是"用户在建房间/入会途中点了挂断"
   * 之后，{@code get().call?.callId === callId} 仍然成立 —— 异步流程会继续跑下去，
   * 把**已取消的邀请**发给对方，对方白响 60 秒且主叫再也没法取消。
   * 所以每一个 await 之后都必须用这个判据。
   */
  function isLiveCall(callId: string): boolean {
    const st = get();
    return st.call?.callId === callId
      && (st.phase === 'outgoing' || st.phase === 'connecting' || st.phase === 'active');
  }

  /**
   * ★拉一次在线成员。
   *
   * <p>★失败<b>静默</b>：这是后台轮询，会议本身一切正常；
   * 弹一个"参与者列表加载失败"只会让用户以为会要断了。
   * 唯一的例外是主持人主动操作后的刷新（{@link CallState.refreshParticipants}），
   * 那里会把错误写进 notice。
   */
  async function loadParticipants(callId: string, opts: { silent?: boolean } = {}): Promise<void> {
    const st = get();
    if (!st.call || st.call.callId !== callId) return;
    if (st.phase !== 'active' || st.call.mode !== 'room') return;
    try {
      const list = await meetingApi.listParticipants(st.call.roomName);
      if (!isLiveCall(callId)) return;
      set({ participants: Array.isArray(list) ? list : [] });
    } catch (e) {
      // ★静默：后台轮询失败不改 UI，下一次 tick 会再试
      if (opts.silent === false && isLiveCall(callId)) {
        set({ notice: `参会人列表刷新失败：${humanError(e)}` });
      }
    }
  }

  /** 会中每 5 秒刷新成员（房间会议才需要）。 */
  function startParticipantPoll(callId: string): void {
    clearParticipantPoll();
    void loadParticipants(callId);
    partPollTimer = setInterval(() => {
      void loadParticipants(callId);
    }, 5_000);
  }

  function activate(callId: string): void {
    const st = get();
    if (!st.call || st.call.callId !== callId) return;
    if (st.phase !== 'outgoing' && st.phase !== 'connecting' && st.phase !== 'active') return;
    stopRingtone();
    timeoutTimer = clearTimer(timeoutTimer);
    soloTimer = clearTimer(soloTimer);
    set((s) => ({
      phase: 'active',
      // ★**不要**在这里清 audioBlocked：自动播放被拦是连接层的事实，
      //   与"接通"无关。这里清掉会让"点击开启声音"那条提示在远端一入会就消失，
      //   而声音仍然没开 —— 用户彻底失去修复入口。只有 resumeAudio 成功才清。
      call: s.call ? { ...s.call, connectedAt: s.call.connectedAt ?? Date.now() } : s.call,
    }));
  }

  /** 被叫接听后对方一直没出现（主叫已超时/断线）：给 10 秒宽限再收场。 */
  function scheduleSoloTimeout(callId: string): void {
    soloTimer = clearTimer(soloTimer);
    soloTimer = setTimeout(() => {
      const st = get();
      if (!st.call || st.call.callId !== callId) return;
      if (st.phase !== 'active' || st.remoteCount > 0) return;
      finish('missed', '对方已挂断');
    }, 10_000);
  }

  function scheduleOutgoingTimeout(callId: string): void {
    timeoutTimer = clearTimer(timeoutTimer);
    timeoutTimer = setTimeout(() => {
      const st = get();
      if (!st.call || st.call.callId !== callId) return;
      if (st.phase !== 'outgoing' && st.phase !== 'connecting') return;
      // ★只有主叫能发 ended（服务端校验 senderId）；失败了也照样本地收场
      if (st.call.msgId) {
        void callApi
          .ended({ convId: st.call.convId, msgId: st.call.msgId, reason: 'timeout' })
          .catch(() => undefined);
      }
      finish('missed', '无人接听');
    }, VOIP_RING_TTL_SEC * 1000);
  }

  /** LiveKit 回调 —— 每个回调都先核对 callId，防止上一通电话的迟到事件影响这一通。 */
  function handlersFor(callId: string) {
    return {
      onRemoteCount: (n: number) => {
        if (get().call?.callId !== callId) return;
        set({ remoteCount: n });
        const st = get();
        if (n > 0) {
          soloTimer = clearTimer(soloTimer);
          if (st.phase === 'outgoing' || st.phase === 'connecting') activate(callId);
        } else if (st.phase === 'active' && st.call?.mode !== 'room') {
          // ★★房间会议不排这个"10 秒后收场"：房间里本来就可能暂时没人（我先到），
          //   排了就等于"开会前先等 10 秒，没人来就自动挂断"。
          scheduleSoloTimeout(callId);
        }
      },
      onRemoteJoined: () => activate(callId),
      onRemoteLeft: () => {
        const st = get();
        if (st.call?.callId !== callId) return;
        // ★★多人会议：别人离开只是"房间里少了一个人"，**不是我的会结束**。
        //   1v1 通话才是"对面走了 = 这通电话结束了"。
        if (st.call?.mode === 'room') return;
        if (st.phase === 'active') finish('completed', '对方已挂断');
      },
      /**
       * ★★断开原因决定文案：这三种"被动离开"必须说清楚，否则用户只会看到
       * 一句"连接已断开"，然后怀疑是自己的网络出了问题。
       *
       * <p>原因码来自 LiveKit 的 {@code DisconnectReason}：
       * {@code 5}=ROOM_DELETED（主持人结束会议 / 最后一人走后自动散会）、
       * {@code 4}=PARTICIPANT_REMOVED（被主持人移出）、
       * {@code 2}=DUPLICATE_IDENTITY（同一账号同一平台在别处入会，顶掉本端）。
       */
      onDisconnected: (reason?: string) => {
        if (closing) return;
        const st = get();
        if (st.call?.callId !== callId) return;
        if (st.phase === 'ended' || st.phase === 'idle') return;
        const isRoom = st.call.mode === 'room';
        if (reason === '5') {
          finish('completed', isRoom ? '会议已结束' : '通话已结束');
          return;
        }
        if (reason === '4' && isRoom) {
          finish('completed', '已被主持人移出会议');
          return;
        }
        if (reason === '2') {
          finish('failed', isRoom ? '已在其他设备进入会议，本端已退出' : '已在其他设备接通，本端已退出');
          return;
        }
        finish('failed', '连接已断开');
      },
      onAudioBlocked: () => set({ audioBlocked: true }),
      onMediaError: (kind: 'mic' | 'camera' | 'screen', message: string) => {
        const label = kind === 'mic' ? '麦克风' : kind === 'camera' ? '摄像头' : '屏幕共享';
        set({ notice: `${label}不可用：${humanError(message)}` });
      },
      onMicChanged: (v: boolean) => set({ micOn: v }),
      onCameraChanged: (v: boolean) => set({ cameraOn: v }),
      onScreenShareChanged: (v: boolean) => set({ screenOn: v }),
      onRemoteScreenShareChanged: (v: boolean) => {
        if (get().call?.callId !== callId) return;
        set({ remoteScreenOn: v });
      },
      onRemoteCameraChanged: (v: boolean) => {
        if (get().call?.callId !== callId) return;
        set({ remoteCameraOn: v });
      },
    };
  }

  /**
   * ★处理 3007 事件。
   *
   * <p>四种事件的语义与"该不该理它"：
   * <ul>
   *   <li>{@code voip:answered} —— 发给被叫自己的设备。本端还在 incoming ⇒
   *       <b>别的设备接听了</b>，停铃并收场；本端已经 active ⇒ 是本端刚才那句
   *       answered 的回声，忽略。</li>
   *   <li>{@code voip:cancel} —— 主叫取消。被叫停铃；主叫的其它标签页也据此收场。</li>
   *   <li>{@code voip:timeout} —— 无人接听。同上，但文案不同。</li>
   *   <li>{@code voip:decline} —— 被叫明确拒绝。★主叫必须<b>立刻</b>停止等待
   *       （以前没有这个事件，主叫只能白等 60 秒再看"无人接听"）；被叫的其它端
   *       同时停铃收队。</li>
   * </ul>
   */
  function handleVoipEvent(ev: VoipEvent): void {
    const st = get();
    if (!st.call || st.call.callId !== ev.callId) return;

    if (ev.kind === 'answered') {
      if (st.phase === 'incoming') {
        stopRingtone();
        finish('completed', '已在其他设备接听');
      } else if (st.phase === 'outgoing' || st.phase === 'connecting') {
        /**
         * ★★主叫的"对方已接听"以 LiveKit 的 ParticipantConnected 为准（answered
         * 帧按服务端契约只发给被叫自己）。但那条事件**可能晚到或丢**：晚到一秒，
         * 主叫就多听一秒"嘟嘟嘟"；丢一次，就一直响到超时。
         * 只要收到 answered，说明对端确实点了接听 —— 立刻进通话态并停回铃。
         */
        activate(ev.callId);
      }
      return;
    }

    if (ev.kind === 'decline') {
      /**
       * ★★被叫拒绝。两条腿各走各的：
       * <ul>
       *   <li><b>主叫</b>（outgoing/connecting）：立刻收场，文案「对方已拒绝」。
       *       以前这里没有分支，主叫会一直响到 60 秒超时并显示"无人接听"。</li>
       *   <li><b>被叫的其它端</b>（incoming）：停铃收队。用事件里的 {@code userId}
       *       区分"我自己在别的设备上拒的"与"对方拒的"，只是文案不同。</li>
       * </ul>
       * 本端已经不在响铃/等待态时（例如本端就是那个点了拒绝的设备），静默忽略。
       */
      const me = useChatStore.getState().userId;
      const selfDeclined = ev.userId != null && me != null && ev.userId === String(me);
      if (st.phase === 'incoming') {
        stopRingtone();
        finish('declined', selfDeclined ? '已在其他设备拒绝' : '对方已拒绝');
      } else if (st.phase === 'outgoing' || st.phase === 'connecting') {
        stopRingtone();
        finish('declined', '对方已拒绝');
      }
      return;
    }

    if (st.phase === 'incoming') {
      finish('missed', ev.kind === 'timeout' ? '无人接听' : '对方已取消');
      return;
    }
    // ★主叫的其它标签页：这通电话已经在别处结束了
    if (st.phase === 'outgoing' || st.phase === 'connecting') {
      finish('canceled', ev.kind === 'timeout' ? '无人接听' : '已取消');
    }
  }

  /** 收到一条 voip 邀请（由 store/chat 的 WS 接收路径转发）。 */
  function receiveInvite(msg: MessageDto): void {
    const invite = parseVoipInvite(msg.body);
    if (!invite) return;
    // ★同一通电话的邀请只处理一次：重连补投/多端同步的重复帧绝不能再响一遍铃
    if (!firstHeard(invite.callId)) return;

    /**
     * ★★不能用 {@code senderId === 我} 一刀切掉邀请 —— 那会把自己打给自己的那通电话静默吞掉。
     *
     * <p>同账号多端是**常态**：用户在 A 端发起、在 B 端等来电（也是自测一通电话时唯一的办法，
     * 因为测试账号往往只有一个）。服务端扇出本来就按 {@code deviceId} 排除了<b>来源端</b>
     * （{@code sourceDeviceId}），所以"发起的那一端"根本收不到这一帧；
     * 此时再按 userId 过滤，挡掉的恰恰是<b>该响铃的其它端</b> ——
     * 表现就是「拨了语音，对方（另一个窗口）一声不响」。
     *
     * <p>真正需要丢弃的是<b>同一通电话的回声</b>：重连补投、多端同步都可能把
     * "我正在进行中的这一通"再送回来一次。用 {@code callId} 判它才准确 ——
     * 它天然区分了"我这一通"（同一 callId）与"我另一台设备刚发起的新一通"（不同 callId）。
     */
    if (get().call?.callId === invite.callId) return;
    // ★实时帧几乎总是新鲜的；这条判据是为"断线重连后补投的旧帧"兜底
    if (!isWithinRingWindow(msg.sendTime, Date.now())) return;

    const chat = useChatStore.getState();

    const chat0 = get();
    const busy =
      chat0.call != null &&
      (chat0.phase === 'incoming' || chat0.phase === 'outgoing' || chat0.phase === 'connecting' || chat0.phase === 'active');
    if (busy) {
      // ★通话中收到第二通：不弹浮层，但在气泡上记"未接"，用户回头能看见
      if (msg.msgId != null && !get().records[String(msg.msgId)]) {
        set((s) => ({
          records: {
            ...s.records,
            [String(msg.msgId)]: {
              status: 'missed',
              mediaType: invite.mediaType,
              durationSec: 0,
              at: Date.now(),
              detail: '忙线未接',
            },
          },
        }));
      }
      return;
    }

    const conv = chat.convs.find((c) => String(c.convId) === String(msg.convId));
    const call: CallInfo = {
      callId: invite.callId,
      msgId: msg.msgId == null ? undefined : String(msg.msgId),
      convId: String(msg.convId),
      convTitle: convTitleOf(conv),
      peerName: conv?.peerName,
      /**
       * ★★真实头像优先（2026-11-08）：会话表里 {@code peerAvatar} 是常态来源，
       * 但"第一次单聊就打电话"时会话可能还只是 WS 收到首帧时插的那条<b>最小条目</b>
       * （只有 convId/unreadCount，见 {@code store/chat} 的 onMsgRecv），没有头像 ——
       * 此时退回本帧消息上的 {@code senderAvatar}，否则来电浮层只能画首字。
       * 1v1 邀请里发送者就是对端，两者同义。
       */
      peerAvatar: conv?.peerAvatar || msg.senderAvatar,
      peerUserId: conv?.peerUserId == null ? undefined : String(conv.peerUserId),
      mediaType: invite.mediaType,
      direction: 'in',
      roomName: invite.roomName,
      startedAt: Date.now(),
      // ★被叫收到的永远是 1v1 通话邀请（房间会议的邀请方式是把会议号发给别人，
      //   走的是「加入」，不经过 voip 消息）
      mode: 'call',
    };

    clearCallTimers();
    closing = false;
    set({
      phase: 'incoming',
      call,
      ended: null,
      ...EMPTY_CALL_MEDIA,
    });
    startRingtone('incoming');
    // ★主叫 60 秒会发 timeout；这里的 65 秒是"主叫已不在线"时的兜底
    timeoutTimer = setTimeout(() => {
      if (get().call?.callId !== call.callId || get().phase !== 'incoming') return;
      finish('missed', '未接听');
    }, (VOIP_RING_TTL_SEC + 5) * 1000);
  }

  /**
   * ★★进入一个**会议房间**（「会议」栏的「发起」与「加入」共用同一条路）。
   *
   * <h2>与 {@link startCall} 的三点不同</h2>
   * <ul>
   *   <li><b>不响铃、不发 voip 邀请</b>：房间会议没有"我正在呼叫某个人"这件事，
   *       别人进来靠的是把<b>会议号</b>发给他、他点「加入」。所以没有
   *       {@code outgoing} 这一档，也没有 60 秒无人接听超时；</li>
   *   <li><b>入会即通话态</b>：进来就 {@code active}，房间里没人也只是"等待对方加入…"；</li>
   *   <li><b>房主由"谁建的房"决定</b>：{@code create=true} 的人是房主（可开云端录音），
   *       凭号加入的是普通参会人 —— 这与服务端 {@code requireHost} 的判定一致。</li>
   * </ul>
   *
   * <p>★{@code create=false} 时<b>不会</b>顺手建房：那样任何一串数字都能"加入"出一个空房间，
   * 用户会以为自己进对了会场（而里面一个人都没有），比直接报错更糟。
   *
   * @param opts.create 是否先 {@code createRoom}（幂等：同名房间直接复用）
   */
  async function enterRoom(opts: {
    roomName: string;
    mediaType: VoipMediaType;
    create: boolean;
    title?: string;
    allowGuest?: boolean;
    /** ★建会时带上的分享 slug（见 {@link startRoomMeeting}）。 */
    shareSlug?: string;
    /** ★发起/加入的群会话（群通话）：写进会议记录，结束时系统消息也回到这里。 */
    convId?: string;
  }): Promise<void> {
    const phase = get().phase;
    if (phase === 'incoming' || phase === 'outgoing' || phase === 'connecting' || phase === 'active') {
      return; // ★一次只允许一场
    }
    const me = useChatStore.getState().userId;
    if (me == null) return;

    const now = Date.now();
    const title = (opts.title ?? '').trim();
    const callId = makeCallId(now, rand());
    const call: CallInfo = {
      callId,
      // ★房间会议默认没有会话（从「会议」栏发起）；群通话传 {@code opts.convId}。
      //   空串是"没有"的显式表达（发录制请求时会被滤掉，见 startServerRecording）。
      convId: opts.convId ?? '',
      convTitle: title || defaultMeetingTitle(opts.roomName),
      mediaType: opts.mediaType,
      // ★只有建房的人是"发起方"（= 服务端的 host，唯一能开云端录音的人）
      direction: opts.create ? 'out' : 'in',
      roomName: opts.roomName,
      startedAt: now,
      mode: 'room',
      title: title || undefined,
      // ★初始值先按"发起时的勾选"；以服务端令牌回传的为准（加入者也一样）
      allowGuest: opts.create ? opts.allowGuest === true : undefined,
    };

    clearCallTimers();
    closing = false;
    set({
      phase: 'connecting',
      call,
      ended: null,
      ...EMPTY_CALL_MEDIA,
      notice: opts.create ? '正在创建会议…' : '正在加入会议…',
    });

    try {
      if (opts.create) {
        await meetingApi.createRoom({
          name: opts.roomName,
          platform: 'web',
          deviceId: deviceId(),
          // 会议不是 1v1：给一个够小团队用的上限（服务端还会按配置 clamp）
          maxParticipants: 20,
          // ★★origin=1 让服务端<b>建房时就落一条会议记录</b>（im_meeting，status=进行中）。
          //   不传的时候老行为不变：1v1 通话房间不落库，只有开录音才转成会议。
          //   没有这一步，会议不录音 ⇒ 会议结束后会议记录里什么都没有。
          origin: 1,
          title: title || undefined,
          meetingType: opts.mediaType === 'video' ? 2 : 1,
          // ★房主在「发起会议」里的勾选：写进房间元数据，匿名访客签令牌时按它拦。
          //   ★缺省（undefined）按 false 处理：会议默认不对外开放游客。
          //   房主要给外部人开链接，必须在发起弹窗里显式打开。
          allowGuest: opts.allowGuest === true,
          // ★★分享 slug 随建房一起带给服务端：它要同时写进 room metadata 和
          //   im_meeting.share_slug，必须与弹窗里「复制邀请」用的是<b>同一个</b>值，
          //   否则用户在弹窗里复制走的链接指向一个查不到的会议。
          shareSlug: opts.shareSlug,
          // ★★群通话：会议记录关联到群会话（im_meeting.conv_id）。
          //   会议结束后的「录制已保存」等系统消息会回到这个会话，
          //   房间会议（从「会议」栏发起）不传，行为与以前完全一致。
          //   ★★必须原样传<b>字符串</b>：convId 是 64-bit 雪花 ID（当前值 226310887680507904
          //   已经超过 Number.MAX_SAFE_INTEGER），转成 JS number 会被舍成 ...7900，
          //   会议记录就挂到一个不存在的会话上，散会通知也发不出去。
          //   服务端 DTO 是 {@code Long}，Jackson 默认允许 string→long 强制转换
          //   （2026-11-08 在 101 实测：传字符串落库、读回都是完整精度）。
          //   ★非数字 id 一律不带（宁可少关联，也不要建会失败）。
          ...(opts.convId && /^\d+$/.test(opts.convId) ? { convId: opts.convId } : {}),
          // ★★会议房间空房保留 **1 小时**（原来 300 秒）。
          //   会议是"约好几点开、大家陆续进"的东西：发起人建完房先退出去等，
          //   或者中途网络断了 1 分钟，5 分钟的空房超时会让房间直接消失，
          //   后来的人拿到一个正确的会议号也只会看到「会议不存在或已结束」
          //   —— 看起来就像"加入功能没做"。★通话链路不受影响（那边仍是短超时）。
          // ★现在的"散会"是显式的（主持人结束会议 / 最后一人离开后自动删房），
          //   这个超时只是<b>兜底</b>：进程崩溃、浏览器被杀这类没人能发请求的场合，
          //   房间最多存活 1 小时。所以它不需要再缩短。
          emptyTimeoutSeconds: 3600,
        });
        if (!isLiveCall(callId)) return;
      }

      const token = await meetingApi.issueToken(opts.roomName, {
        platform: 'web',
        deviceId: deviceId(),
        displayName: myDisplayName(),
      });
      if (!isLiveCall(callId)) return;
      // ★★角色以<b>服务端令牌</b>为准：主持人断线后重新「加入」时 direction 是 'in'，
      //   但房主记在房间 metadata 上，服务端仍认为他是主持人。
      //   "谁能结束会议"必须与服务端 requireHost 同源，否则会出现
      //   "界面上没有结束入口，服务端却说你说了算"。
      const isHost = token.role ? token.role === 'HOST' : opts.create;
      await joinLiveKit(
        {
          url: token.wsUrl,
          token: token.token,
          video: opts.mediaType === 'video',
          avatar: myAvatar(),
        },
        handlersFor(callId),
      );
      if (!isLiveCall(callId)) {
        await leaveLiveKit();
        return;
      }

      // ★直接进通话态：房间里可能已经有人在等，也可能我在等别人 —— 两种都不是"呼出中"。
      set((s) => ({
        phase: 'active',
        call: s.call
          ? {
            ...s.call,
            connectedAt: Date.now(),
            isHost,
            selfIdentity: token.identity,
            // ★以服务端为准：房间元数据才是"能不能让游客进"的唯一真源。
            //   老服务端不回这个字段时退回本地勾选（或按不允许处理）。
            allowGuest: token.guestAllowed ?? s.call.allowGuest ?? false,
            // ★只有房间会议才有时长上限；1v1 通话即使记录里有默认值也不能显示
            plannedDurationSec:
              s.call.mode === 'room' && token.plannedDurationSec != null
                && token.plannedDurationSec > 0
                ? token.plannedDurationSec
                : undefined,
            meetingStartedAt:
              s.call.mode === 'room' && token.meetingStartedAt != null
                ? token.meetingStartedAt
                : undefined,
          }
          : s.call,
        notice: null,
        // ★按本地房间的真实人数起算，别等事件：入会时可能已经有人在了
        remoteCount: remoteCount(),
      }));
      // ★会中成员面板的数据源（拉一次 + 每 5 秒刷新）
      startParticipantPoll(callId);
    } catch (e) {
      if (!isLiveCall(callId)) return;
      // ★"进不去这个房间"与"服务没开"是两回事，别让用户去重启服务。
      // ★★把**实际输入的会议号**写进提示：线上真实发生过"发起方是 063575412、
      //   加入方输成 063575421"，一句"会议不存在"看不出是自己抄错了哪一位，
      //   带上号码，两个屏幕上的一对就能立刻发现。
      const detail = humanError(
        e,
        opts.create
          ? `${defaultMeetingTitle(opts.roomName)} 创建失败，请稍后重试`
          : `${defaultMeetingTitle(opts.roomName)} 不存在或已结束，请核对会议号`,
      );
      // ★服务端自己回的 IM_50001 文案里**不带房间名**，这里补上（只补"号不对"这一类，
      //   麦克风权限之类的错误跟会议号无关，别往里塞）。
      const isNotFound = !opts.create && /不存在|已结束|not found|404/i.test(detail);
      finish('failed', isNotFound && !detail.includes(opts.roomName)
        ? `${detail}（你输入的是 ${opts.roomName}）`
        : detail);
    }
  }

  return {
    phase: 'idle',
    call: null,
    ended: null,
    records: {},
    ...EMPTY_CALL_MEDIA,

    init: () => {
      if (initialized) return;
      initialized = true;
      onIncomingCallMessage(receiveInvite);
      onCustomEvent((event) => {
        const ev = parseVoipEvent(event.eventType, event.payload);
        if (ev) handleVoipEvent(ev);
      });
    },

    startCall: async (conv, mediaType) => {
      const phase = get().phase;
      if (phase === 'incoming' || phase === 'outgoing' || phase === 'connecting' || phase === 'active') {
        return; // ★一次只允许一通
      }
      const me = useChatStore.getState().userId;
      if (me == null) return;

      const now = Date.now();
      const callId = makeCallId(now, rand());
      const roomName = makeRoomName(String(conv.convId), now, rand());
      const call: CallInfo = {
        callId,
        convId: String(conv.convId),
        convTitle: convTitleOf(conv),
        peerName: conv.peerName,
        peerAvatar: conv.peerAvatar,
        peerUserId: conv.peerUserId == null ? undefined : String(conv.peerUserId),
        mediaType,
        direction: 'out',
        roomName,
        startedAt: now,
        mode: 'call',
      };

      clearCallTimers();
      closing = false;
      set({
        phase: 'outgoing',
        call,
        ended: null,
        ...EMPTY_CALL_MEDIA,
        // ★拍摄像头状态交给 LiveKit 的 LocalTrackPublished / onMediaError 驱动，
        //   不在这里乐观置 true：权限被拒时会留下一个"开着但没有画面"的黑框。
      });
      startRingtone('outgoing');

      try {
        // ① 建房间（房间名由前端生成：要在邀请消息里带出去）
        await meetingApi.createRoom({
          name: roomName,
          platform: 'web',
          deviceId: deviceId(),
          // ★两人通话：人数上限收窄，避免第三人凭邀请消息入会
          maxParticipants: 2,
          emptyTimeoutSeconds: 120,
        });
        if (!isLiveCall(callId)) return;

        // ② 自己先入会 —— 这样对端点接听时，ParticipantConnected 一定能被我们收到
        const token = await meetingApi.issueToken(roomName, {
          platform: 'web',
          deviceId: deviceId(),
          displayName: myDisplayName(),
        });
        if (!isLiveCall(callId)) return;
        await joinLiveKit(
          {
            url: token.wsUrl,
            token: token.token,
            video: mediaType === 'video',
            avatar: myAvatar(),
          },
          handlersFor(callId),
        );
        if (!isLiveCall(callId)) {
          await leaveLiveKit();
          return;
        }

        // ③ 最后才发邀请：房间已就绪，被叫一点接听就能进
        const sent = await useChatStore.getState().sendVoipInvite(call.convId, {
          callId,
          mediaType,
          roomName,
        });
        if (!sent) {
          finish('failed', '邀请发送失败');
          return;
        }
        // ★发送途中用户挂断 ⇒ 邀请已经落到服务端了，撤不回来 —— 但**可以补发 ended**
        //   让对端立刻停铃（否则它会白响满 60 秒）。这是 hangup 拿不到 msgId 的唯一空档，
        //   到这里 msgId 才出现，所以在这一处补。
        if (!isLiveCall(callId)) {
          void callApi
            .ended({ convId: call.convId, msgId: sent.msgId, reason: 'cancel' })
            .catch(() => undefined);
          return;
        }
        set((s) => ({
          call: s.call ? { ...s.call, msgId: String(sent.msgId) } : s.call,
        }));
        scheduleOutgoingTimeout(callId);
      } catch (e) {
        if (!isLiveCall(callId)) return;
        finish('failed', humanError(e));
      }
    },

    startRoomMeeting: async (mediaType, roomName, title, allowGuest, shareSlug, convId) => {
      const wanted = roomName == null ? null : normalizeMeetingNo(roomName);
      // ★给了号但不合法 ⇒ 什么都不做。界面上已经先校验过一遍，这里是最后一道：
      //   兜底生成一个新号会让用户"发起成了一个别人进不来的会"，比不动更糟。
      if (roomName != null && wanted == null) return;
      // ★没给号就现场生成：发起会议不需要用户先想好一个数字
      const room = wanted ?? makeMeetingNo(Math.floor(Math.random() * 10 ** 9));
      await enterRoom({
        roomName: room,
        mediaType,
        create: true,
        title,
        allowGuest,
        shareSlug,
        convId,
      });
    },

    joinRoomMeeting: async (roomName, mediaType, convId) => {
      const room = normalizeMeetingNo(roomName);
      if (!room) return;
      // ★凭号入会**不建房**：见 enterRoom 的注释（否则任何数字都能"加入"出一个空房间）
      await enterRoom({ roomName: room, mediaType, create: false, convId });
    },

    accept: async () => {
      const st = get();
      const call = st.call;
      if (!call || st.phase !== 'incoming') return;
      stopRingtone();
      timeoutTimer = clearTimer(timeoutTimer);
      set({ phase: 'connecting', notice: null, minimized: false, audioBlocked: false });

      try {
        const token = await meetingApi.issueToken(call.roomName, {
          platform: 'web',
          deviceId: deviceId(),
          displayName: myDisplayName(),
        });
        if (!isLiveCall(call.callId)) return;
        await joinLiveKit(
          {
            url: token.wsUrl,
            token: token.token,
            video: call.mediaType === 'video',
            avatar: myAvatar(),
          },
          handlersFor(call.callId),
        );
        if (!isLiveCall(call.callId)) {
          await leaveLiveKit();
          return;
        }

        // ★入会之后才上报"已接听"：事件与实际状态一致。失败不影响通话。
        if (call.msgId) {
          void callApi
            .answered({
              convId: call.convId,
              msgId: call.msgId,
              callId: call.callId,
              roomName: call.roomName,
            })
            .catch(() => undefined);
        }

        if (remoteCount() > 0) {
          activate(call.callId);
        } else {
          // 主叫可能还在入会 / 已经离开：先进入通话态，10 秒内等不到人再收场
          set((s) => ({
            phase: 'active',
            call: s.call ? { ...s.call, connectedAt: Date.now() } : s.call,
          }));
          scheduleSoloTimeout(call.callId);
        }
      } catch (e) {
        // ★用户已经挂断/拒绝时不要再覆盖状态：错误只能属于"还在进行中"的那通电话
        if (!isLiveCall(call.callId)) return;
        finish('failed', humanError(e));
      }
    },

    decline: () => {
      const st = get();
      const call = st.call;
      if (!call || st.phase !== 'incoming') return;
      /**
       * ★★先上报再收场：{@code /calls/declined} 让服务端向会话广播
       * {@code voip:decline} —— 主叫立刻停止等待、其它设备停铃。
       *
       * <p>以前这里只能本端 {@code finish()}（服务端只许主叫调 {@code /ended}），
       * 结果就是"B 拒绝了，A 还在响，最后显示无人接听"。
       *
       * <p>fire-and-forget：网络失败不能把本地停铃也拖住 —— 用户点了拒绝就必须
       * 立刻安静下来；最坏情况只是回到旧行为（主叫等超时）。
       */
      if (call.msgId) {
        void callApi
          .declined({
            convId: call.convId,
            msgId: call.msgId,
            callId: call.callId,
            roomName: call.roomName,
          })
          .catch(() => undefined);
      }
      finish('declined', '已拒绝');
    },

    hangup: async (opts) => {
      const st = get();
      const call = st.call;
      if (!call) return;
      const ringing = st.phase === 'outgoing' || st.phase === 'connecting' || st.phase === 'incoming';
      // ★只有主叫、且还没接通时才发 ended：接通后对端靠 ParticipantDisconnected 感知
      if (call.direction === 'out' && ringing && call.msgId) {
        void callApi
          .ended({ convId: call.convId, msgId: call.msgId, reason: 'cancel' })
          .catch(() => undefined);
      }
      // ★房间会议没有"取消邀请"这回事：{@code msgId} 永远是 undefined，
      //   这里那段 ended 补发自然走不到；参数、状态与 1v1 通话共用同一套。
      const status: CallRecordStatus =
        st.phase === 'active' ? 'completed' : call.direction === 'out' ? 'canceled' : 'declined';
      /**
       * ★★最后一个人退出 ⇒ 会议自动结束（`lib/meetingLeave` 里是可测的纯判据）。
       * 主持人主动散会走 {@link endRoomMeeting}，由确认框决定，不在这里顺手做。
       */
      const subject: LeaveSubject = { mode: call.mode, direction: call.direction, isHost: call.isHost };
      const endRoomAfterLeave = call.mode === 'room' && shouldAutoEndRoom({
        subject,
        remoteCount: st.remoteCount,
        keepRoom: opts?.keepRoom === true,
      });
      // ★文案要说实话：从「会议」栏进来的不该被叫成"通话"
      const leaveText = call.mode === 'room' ? '已离开会议' : '通话已结束';
      finish(status, st.phase === 'active' ? leaveText : '已取消', { endRoomAfterLeave });
    },

    endRoomMeeting: async () => {
      const st = get();
      const call = st.call;
      // ★只有进行中的会议能散会；已结束后再点一次不该重复发请求
      if (!call || call.mode !== 'room') return;
      if (st.phase !== 'active' && st.phase !== 'connecting') return;

      // ① 先停录制：删房之后 egress 会失去合成源，文件尾部容易缺
      let recordingStopped = false;
      if (st.recordingEgressId) {
        recordingStopped = await stopServerRecording(call.roomName, st.recordingEgressId)
          .then(() => true)
          .catch(() => false);
      }
      if (get().call?.callId !== call.callId) return;

      set({ notice: '正在结束会议…' });
      /**
       * ★★删房会让本端立刻收到 Disconnected：先立 closing，
       * 否则那条回调会抢先把这次结束写成一笔"连接已断开"的失败记录
       * （用户明明是自己点的「结束会议」）。
       */
      closing = true;
      try {
        await meetingApi.deleteRoom(call.roomName);
      } catch (e) {
        closing = false;
        // ★房间已经不在了（别人先散了 / 空房被回收）= 会议本来就结束了，照常收场
        if (/404|not found|不存在|已结束/i.test(errText(e))) {
          if (get().call?.callId === call.callId) {
            finish('completed', '会议已结束', { recordingAlreadyStopped: recordingStopped });
          }
          return;
        }
        // ★散会失败就<b>留在会里</b>：不能让用户以为散成功了，其实别人还在开会
        set({ notice: `结束会议失败：${humanError(e)}` });
        return;
      }
      closing = false;
      if (get().call?.callId !== call.callId) return;
      finish('completed', '会议已结束', { recordingAlreadyStopped: recordingStopped });
    },

    // ★三个开关都以 LiveKit 返回的**实际状态**回写，而不是等回调事件：
    //   事件在"关→开"快速切换、重连、被浏览器回收设备时会漏，一旦漏掉，
    //   按钮就停在错误的一侧（"关了视频按钮不变、再点也打不开"）。
    //   回写一次是幂等的，事件到达后再覆盖成同一个值，不会来回跳。
    toggleMic: async () => {
      const actual = await lkToggleMic();
      set({ micOn: actual });
    },
    toggleCamera: async () => {
      const actual = await lkToggleCamera();
      set({ cameraOn: actual });
    },
    toggleScreenShare: async () => {
      const actual = await lkToggleScreen();
      set({ screenOn: actual });
    },
    toggleRecording: async () => {
      const st = get();
      const call = st.call;
      if (!call || st.phase !== 'active' || st.recordingBusy) return;
      // ★服务端接口是 requireHost：会议里以服务端角色为准（主持人断线重进也还是主持人），
      //   1v1 通话里就是主叫。非主持人调用必被拒。
      const host = call.mode === 'room'
        ? call.isHost ?? call.direction === 'out'
        : call.direction === 'out';
      if (!host) {
        set({ notice: '只有会议主持人可以开启云端录制' });
        return;
      }
      if (st.recordingEgressId) {
        await stopServerRecording(call.roomName, st.recordingEgressId).catch(() => undefined);
        return;
      }
      await startServerRecording(call);
    },
    // ---------------------------------------------------------------- 会中成员
    refreshParticipants: async () => {
      const st = get();
      if (!st.call || st.call.mode !== 'room' || st.phase !== 'active') return;
      await loadParticipants(st.call.callId, { silent: false });
    },

    kickParticipant: async (userId) => {
      const st = get();
      const call = st.call;
      if (!call || call.mode !== 'room' || st.phase !== 'active') return;
      // ★与服务端 requireHost 同口径（见 lib/meetingLeave.amIHost）：
      //   界面用 amIHost 决定显示按钮，这里就不能只看 isHost，
      //   否则老数据上会出现"按钮能点、一点就报没权限"。
      if (!amIHost({ mode: call.mode, direction: call.direction, isHost: call.isHost })) {
        set({ notice: '只有会议主持人可以移出参会人' });
        return;
      }
      try {
        const res = await meetingApi.kickParticipant(call.roomName, userId);
        // ★幂等：目标已经自己走了也是成功，别报错吓人
        set({ notice: res.kickedCount > 0 ? '已将该成员移出会议' : '该成员已离开会议' });
        await loadParticipants(call.callId);
      } catch (e) {
        set({ notice: `移出失败：${humanError(e)}` });
      }
    },

    muteParticipant: async (userId, muted = true) => {
      const st = get();
      const call = st.call;
      if (!call || call.mode !== 'room' || st.phase !== 'active') return;
      if (!amIHost({ mode: call.mode, direction: call.direction, isHost: call.isHost })) {
        set({ notice: '只有会议主持人可以静音成员' });
        return;
      }
      try {
        await meetingApi.muteParticipant(call.roomName, userId, { muted });
        set({ notice: muted ? '已静音该成员' : '已取消静音' });
        await loadParticipants(call.callId);
      } catch (e) {
        set({ notice: `静音失败：${humanError(e)}` });
      }
    },

    muteAll: async () => {
      const st = get();
      const call = st.call;
      if (!call || call.mode !== 'room' || st.phase !== 'active') return;
      if (!amIHost({ mode: call.mode, direction: call.direction, isHost: call.isHost })) {
        set({ notice: '只有会议主持人可以全员静音' });
        return;
      }
      // ★★★一次请求、按席位执行，不再逐个 userId 扇出（2026-11-07）。
      //   旧实现用 {@code muteAllTargets} 收集 userId 再循环调用单点静音接口，
      //   而游客（identity = guest-xxx）解析不出 userId，永远不在目标里 ——
      //   只有游客在线时目标列表恒空，前端据此把按钮禁用，于是「点不动」。
      //   服务端用会议室内的席位操作，游客一并覆盖；已静音的席位自动跳过。
      try {
        const result = await meetingApi.muteAllParticipants(call.roomName);
        if (get().call?.callId !== call.callId) return;
        set({
          notice: result.mutedCount > 0
            ? '已静音全部参会人'
            : '所有参会人都已静音',
        });
      } catch (e) {
        if (get().call?.callId !== call.callId) return;
        set({ notice: `全员静音失败：${humanError(e)}` });
        return;
      }
      await loadParticipants(call.callId);
    },

    updateRoomSettings: async (patch) => {
      const st = get();
      const call = st.call;
      if (!call || call.mode !== 'room' || st.phase !== 'active') return;
      if (!amIHost({ mode: call.mode, direction: call.direction, isHost: call.isHost })) {
        set({ notice: '只有会议主持人可以修改会议设置' });
        return;
      }
      try {
        await meetingApi.updateRoomSettings(call.roomName, patch);
        if (get().call?.callId !== call.callId) return;
        if (patch.muteAll !== undefined) {
          set({ notice: patch.muteAll ? '已全员禁言，主持人可单独放行' : '已解除全员禁言' });
        } else if (patch.danmaku !== undefined) {
          set({ notice: patch.danmaku ? '已开启弹幕' : '已关闭弹幕' });
        }
        // 禁言会同时改成员的发布权限，列表状态要跟着变
        await loadParticipants(call.callId);
      } catch (e) {
        set({ notice: `会议设置失败：${humanError(e)}` });
      }
    },

    setParticipantMicAllowed: async (userId, allowed) => {
      const st = get();
      const call = st.call;
      if (!call || call.mode !== 'room' || st.phase !== 'active') return;
      if (!amIHost({ mode: call.mode, direction: call.direction, isHost: call.isHost })) {
        set({ notice: '只有会议主持人可以调整成员发言权限' });
        return;
      }
      // ★空列表在 LiveKit 里表示"不限制发布源"（不是"什么都不许"）。
      //   收回时也不能传空列表，必须显式列出还允许的来源，否则等于没禁言。
      const sources = allowed ? [] : ['camera', 'screen_share', 'screen_share_audio'];
      try {
        await meetingApi.updatePermissions(call.roomName, userId, { canPublishSources: sources });
        if (allowed) {
          // 对方若是"被禁言自动关麦"的，收到权限变更后会自己开麦；
          // 但被轨道级静音的人不会 —— 这里补一次取消静音，两种静音都能恢复。
          try {
            await meetingApi.muteParticipant(call.roomName, userId, { muted: false });
          } catch {
            /* 非致命：权限已放行，对方自己点麦也能开 */
          }
        }
        if (get().call?.callId !== call.callId) return;
        set({ notice: allowed ? '已允许该成员发言' : '已收回该成员的发言权限' });
        await loadParticipants(call.callId);
      } catch (e) {
        set({ notice: `${allowed ? '放行' : '禁言'}失败：${humanError(e)}` });
      }
    },

    toggleMainView: () => {
      set((s) => ({ mainView: s.mainView === 'remote' ? 'local' : 'remote' }));
    },
    retryAudio: async () => {
      const ok = await resumeAudio();
      if (ok) set({ audioBlocked: false });
    },

    setMinimized: (minimized) => set({ minimized }),

    // ★只是开关，不在这里开窗口：开窗口必须发生在组件层（需要 React 树挂在目标文档里），
    //   见 components/MeetingPopout.tsx
    setPopout: (popout) => set({ popout }),

    clearNotice: () => set({ notice: null }),

    clearEnded: () => {
      clearCallTimers();
      clearRecPoll();
      clearParticipantPoll();
      // ★回到 idle 就没有任何理由还响铃
      stopRingtone();
      set({ phase: 'idle', call: null, ended: null, ...EMPTY_CALL_MEDIA });
    },
  };
});

/**
 * ★★★铃声与相位强绑定：只有 {@code incoming} / {@code outgoing} 允许有铃声。
 *
 * <p>各条收场路径（接听、拒绝、挂断、超时、断线、别的设备接听）都已经显式调过
 * {@link stopRingtone}，但**漏一条就会一直嘟**——新增分支、异常提前 return、
 * 重复挂断都会踩到。这里不枚举路径，只复核结果：相位一变就检查一遍，
 * 不在响铃两态的一律收声。这是"接通了 / 挂断了还在嘟嘟嘟"的最终兜底。
 */
useCallStore.subscribe((state, prev) => {
  if (state.phase === prev.phase) return;
  if (state.phase !== 'incoming' && state.phase !== 'outgoing' && isRinging()) {
    stopRingtone();
  }
});
