import { useEffect, useState } from 'react';
import { Button, Empty, Spin } from 'antd';
import { ApiError } from '../api/client';
import { PLATFORM_REPO_BASE } from '../authMode';
import { docsErrorText, docsFrameUrl, docsRetryable } from '../lib/docs';
import { tabDef } from '../lib/topTabs';
import { useChatStore } from '../store/chat';
import type { Id } from '../api/types';

/** ★ID 比较统一 String 归一（雪花 ID > 2^53，见 api/json.ts）。 */
const sameId = (a: unknown, b: unknown): boolean => a != null && b != null && String(a) === String(b);

/**
 * ★标题取 {@code topTabs} 那一份**真源**，不另写一个字面量。
 *
 * <p>它同时被用作 {@code iframe} 的 {@code title}（无障碍名 + 浏览器量具的抓手）。
 * 两处各写一遍「资料库」的后果是：将来这个标签页再改名，页面上会同时出现两个名字，
 * 而 {@code iframe} 那个名字恰恰是屏幕阅读器唯一能念出来的东西。
 */
const DOCS_TITLE = tabDef('docs').label;

/**
 * 会话窗口顶部「资料库」标签页（DEV-247）。
 *
 * <h2>它做什么</h2>
 *
 * <p>把平台的资料库页面<b>原样嵌进来</b>：{@code {repoBase}/space/{spaceId}/docs}
 * （{@code repoBase} 默认 {@code /repo}，见 {@code lib/docs.ts} 与 {@code authMode.ts}）。
 * 这是"用 iframe 嵌平台页面"这个需求的全部实现 —— 本组件<b>不查资料、不渲染文档</b>。
 *
 * <h2>★★spaceId 从哪来：两条路，都不是猜的</h2>
 *
 * <table border="1">
 *   <tr><th>情况</th><th>来源</th></tr>
 *   <tr><td>群聊 / 团队群</td>
 *       <td>建群（或进团队）时就已经在平台上建好了空间，
 *           {@code ConversationSummaryDto.spaceId} 直接带下来</td></tr>
 *   <tr><td>私聊</td>
 *       <td>★<b>没有</b>，而且平台侧也不存在"私聊空间"这种东西 ——
 *           本组件挂载时调一次 {@code POST /conversations/{convId}/space}，
 *           由服务端<b>懒建</b>一个 {@code type=DM} 的空间并把 id 回写会话行</td></tr>
 * </table>
 *
 * <p>★所以"私聊打不开资料库"不是前端藏起来的问题，而是<b>那个空间当时还不存在</b>。
 * 这也解释了为什么这里必须有加载态与失败态：用户点进来时，可能正在<b>等一个空间被创建</b>。
 *
 * <h2>★★四条不会出声地错的地方</h2>
 *
 * <ul>
 *   <li><b>判空要交给 {@code docsSpaceId}，不能写 {@code spaceId != null}。</b>
 *       后端契约里 {@code 0} 等同于"没有"，而 {@code "0"} 在 JS 里是<b>真值</b> ⇒
 *       手写判空会拼出 {@code /space/0/docs}，那是一个永远白屏、且<b>没有任何报错</b>的页面。
 *       （{@code lib/docs.test.ts} 逐条钉住了这些边界。）</li>
 *   <li><b>失败文案按错误码说，绝不弹原始 {@code message}。</b>
 *       后端 {@code message} 是给开发者的，形状是"一句话（★补充说明）"，还可能带 19 位雪花号。
 *       取法与 {@code ContactList} 进团队那处逐字同款（{@code docsErrorText}）。</li>
 *   <li><b>「重试」按钮必须有一个会变的依赖。</b>失败时 {@code url} 恒为 {@code null}、
 *       {@code convId} 也没变 ⇒ 若 effect 只依赖这两个，点重试<b>不会重跑任何东西</b>
 *       （按钮看起来坏了）。所以引入 {@code retryTick}。</li>
 *   <li><b>「重试」按钮要对<b>不可重试</b>的失败藏起来。</b>
 *       {@code IM_90001} 是<b>永久</b>的（这个会话不该有资料库），
 *       配上按钮的效果是"用户点多少次就失败多少次"，而界面每次都响应了
 *       ⇒ 用户读出的是"这功能坏了"，而事实是"这功能不对这个会话开放"。
 *       判据在 {@code docsRetryable}，与 {@code docsErrorText} 同源。</li>
 * </ul>
 *
 * <h2>★为什么不在这里做"并发合并"</h2>
 *
 * <p>本组件可以来回挂载（切标签页会卸载重挂），每次都调一次 {@code ensureConvSpace} ——
 * 那是<b>刻意</b>的：合并发生在 store 的 {@code docsFlight} 里，与"已有就本地直接返回"
 * 是同一个函数的三步。放在这里做等于把同一份逻辑复制到每个入口。
 *
 * <h2>★★iframe 的属性为什么是这几个</h2>
 *
 * <ul>
 *   <li>{@code sandbox} <b>不含</b> {@code allow-top-navigation}：挡住被嵌页面
 *       把整个 IM 页面导航走（那会让用户"点了个文档，IM 没了"）。</li>
 *   <li>{@code allow-same-origin} <b>必须</b>：平台页面靠同域 Cookie 的登录态，
 *       去掉它页面会退化成未登录。★代价要说明白 ——
 *       有了它，这层 sandbox 对<b>同源</b>页面挡不住 DOM 访问
 *       （规范如此：{@code allow-scripts + allow-same-origin} 同时给，
 *       被嵌页就能自己摘掉 sandbox）。按"内嵌的是自家页面"接受，已入册。</li>
 *   <li>{@code referrerPolicy="no-referrer"}：IM 的 URL 里可能带会话相关的查询串，
 *       没必要随请求带给另一个子应用。</li>
 *   <li>★{@code src} 只可能是 {@code lib/docs.ts} 拼出来的绝对路径或 {@code null}；
 *       {@code null} 时走的是下面那两个分支，<b>绝不会渲染出 {@code src=""}</b>
 *       ——空 src 会让浏览器请求当前页面自身（{@code spaceIconUrl} 那处同款坑）。</li>
 * </ul>
 */
export default function ChatDocsPanel({ convId }: { convId: Id | null }) {
  // ★选择器返回的是原始值（string / number / undefined），不是新对象 ⇒ 不会造成无谓重渲染。
  const spaceId = useChatStore((s) =>
    convId != null ? s.convs.find((c) => sameId(c.convId, convId))?.spaceId : undefined,
  );
  const ensureConvSpace = useChatStore((s) => s.ensureConvSpace);

  /**
   * 上次失败的两件事：给用户看的话，以及<b>要不要给「重试」按钮</b>；
   * {@code null} = 还没失败过。★成功时会被 effect 清掉（见下）。
   *
   * <p>★两件事在**同一个 state 对象**里，不拆成两个 {@code useState}：
   * 拆开就会出现"文案换了、按钮还是上一条的"这种中间态（两次 setState 之间会渲染一次）。
   */
  const [fail, setFail] = useState<{ text: string; retryable: boolean } | null>(null);
  /** ★「重试」的计数器，只为让 effect 有一个会变的依赖（见类注释第三条）。 */
  const [retryTick, setRetryTick] = useState(0);

  const url = docsFrameUrl(spaceId, PLATFORM_REPO_BASE);

  // ★url 已经算出来了就【一次请求都不发】：已有空间的会话（绝大多数）打开面板是零网络的。
  //   反过来，url 为 null 时不能干等 —— 服务端要懒建，那正是本组件的加载态存在的理由。
  useEffect(() => {
    if (convId == null || url) return undefined;
    let alive = true;
    // ★先把上一次的错误清掉：不然重试期间会一直挂着"打开失败"，
    //   用户看到的是"我点了重试但它说还是失败"。
    setFail(null);
    ensureConvSpace(convId).catch((e: unknown) => {
      // ★alive 闸门：切会话时旧请求的失败会晚于新会话的加载态到达，
      //   不挡的话新会话一进来就顶着一句它自己的错误（请求都还没发出去）。
      if (!alive) return;
      const code = e instanceof ApiError ? e.code : undefined;
      setFail({ text: docsErrorText(code), retryable: docsRetryable(code) });
    });
    return () => {
      alive = false;
    };
    // ★retryTick 必须在依赖里；url 从 null 变成有值时本 effect 会重跑一次（直接 return），
    //   这是"空间建好了 ⇒ 把加载态换成 iframe"的那一步。
  }, [convId, url, retryTick, ensureConvSpace]);

  return (
    <div className="chat-panel">
      {/* ★★DEV-249：这里【不放】.chat-panel-head。
          它上面一行就是标签栏，标签上已经写着「资料库」—— 面板里再重复一遍
          等于同一句话在 40px 内出现两次，用户点进来第一眼看到的就是这个重复。
          ★其余面板（成员 / 文件 / 搜索 / Pin）保留 head：它们的 head 里除了标题
          还有「刷新」「筛选」这类**动作**，标题只是顺带；资料库面板整块是 iframe，
          head 里没有任何可操作的东西，删掉不丢功能。
          ★判据是"head 里有没有标题以外的东西"，不是"要不要好看"——
          将来给资料库加个刷新按钮时，head 要连着标题一起回来。 */}

      {url ? (
        <iframe
          className="chat-docs-frame"
          src={url}
          title={DOCS_TITLE}
          referrerPolicy="no-referrer"
          sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-downloads"
        />
      ) : (
        // ★DEV-249：head 已经没有了，这里直接就是面板的第一块内容。
        //   ★仍然要包一层 .chat-panel-scroll：它负责 flex:1 + overflow-y:auto，
        //     少了它，Empty / Spin 这些不定高内容会跟 iframe 分支的布局对不上
        //     （一个撑满、一个塌在顶部），切标签页时整块内容会跳一下。
        <div className="chat-panel-scroll">
          {fail ? (
            <Empty
              image={Empty.PRESENTED_IMAGE_SIMPLE}
              style={{ marginTop: 64 }}
              description={fail.text}
            >
              {/* ★给一个能点的出口。这里的失败绝大多数是"平台抖了一下"（IM_90002），
                  过一会儿真的会好 —— 不说这句话，用户只会以为这个功能坏了。

                  ★★但{@code IM_90001}（这个会话永远不会有资料库）**不给**按钮：
                  那是一个点多少次都同一个结果的操作，按钮给出的暗示是"再试试就好了"
                  —— 与事实相反。判据在 {@code lib/docs.ts} 的 {@code docsRetryable}。 */}
              {fail.retryable && (
                <Button size="small" onClick={() => setRetryTick((n) => n + 1)}>
                  重试
                </Button>
              )}
            </Empty>
          ) : (
            // ★文案说清"在等什么"：私聊第一次点进来是在服务端建空间，
            //   白转圈几秒与"卡住了"在用户眼里没有区别。
            <div style={{ textAlign: 'center', marginTop: 64 }}>
              <Spin />
              <div className="chat-panel-hint" style={{ marginTop: 12, background: 'none' }}>
                正在准备资料库…
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
