/**
 * ★★会中「独立窗口」的宿主 —— 挂在 App 里、和 {@code CallOverlay} 并列。
 *
 * <h2>它做的事只有三件</h2>
 * <ol>
 *   <li>store 里的 {@code popout} 变 true ⇒ 拿一个可缩放的窗口，把
 *       {@code <CallOverlay standalone />} 渲染进去（窗口优先取"点击时预先开好的那个"，
 *       见 {@code primeMeetingWindow}；没有才当场开）；</li>
 *   <li>用户直接关掉那个窗口 ⇒ 把 {@code popout} 关掉，界面自动回到本页
 *       —— 会议<b>不中断</b>，因为 LiveKit 房间在主页面的内存里；</li>
 *   <li>会议结束 / 离开 / 变成 1v1 通话 ⇒ 关窗口，不在屏幕上留一个死窗口。</li>
 * </ol>
 *
 * <h2>★★窗口有两种，靠同一个槽位交接</h2>
 *
 * <p>首选 <b>文档画中画</b>（{@code documentPictureInPicture}）：开出来没有地址栏，
 * 只有标题栏 + 可拖拽边框，正好满足"单独一个窗口、能自由放大缩小"。
 * 安全上下文（https / localhost）才有这个 API，局域网 http 下退回
 * {@code window.open} 的普通弹窗 —— 那种窗口的地址栏是浏览器强加的，前端去不掉。
 * 两种窗口都是<b>同一个 JS 世界</b>，见 {@code lib/meetingWindow.ts}。
 *
 * <h2>★★为什么不新开一个标签页跑整份应用</h2>
 *
 * <p>那样会得到<b>第二个 app 实例</b>：房间、令牌、主持人身份、录制轮询、成员轮询
 * 全都得重新握手一遍，还要处理"两个页面同一账号互相顶下线"（服务端 identity 含平台名）。
 * 这里不搬状态、只搬 DOM：新窗口里那棵 React 树和本页读的是<b>同一份 zustand store</b>。
 *
 * <h2>★开不出来时的回落</h2>
 *
 * <p>{@code requestWindow} / {@code window.open} 在异步链（等待建房间/签令牌）之后调用
 * 都会被拒。拦下时这里只做一件事：把 {@code popout} 关掉，让页内大窗继续用 ——
 * 会议绝不能因为"窗口没弹出来"而受影响。用户可以在页内点「在新窗口打开」再试一次
 * （那一次是直接从点击里触发，几乎一定能弹出来）。
 */
import { useCallback, useEffect, useRef } from 'react';
import { App as AntApp } from 'antd';
import { createRoot, type Root } from 'react-dom/client';

import {
  MEETING_ROOT_ID,
  closeMeetingWindow,
  discardPrimedMeetingWindow,
  takePrimedMeetingWindow,
} from '../lib/meetingWindow';
import { useCallStore } from '../store/call';
import CallOverlay from './CallOverlay';

/** 轮询"窗口是不是被用户关掉了"。★400ms：肉眼几乎无感，又不至于白占 CPU。 */
const WATCH_INTERVAL_MS = 400;

export default function MeetingPopout() {
  const { message } = AntApp.useApp();
  const popout = useCallStore((s) => s.popout);
  const phase = useCallStore((s) => s.phase);
  const call = useCallStore((s) => s.call);

  const winRef = useRef<Window | null>(null);
  const rootRef = useRef<Root | null>(null);
  /** ★"窗口被关掉"的监听清理函数：换窗口 / 收场时都要摘干净，否则会重复 setPopout。 */
  const stopWatchRef = useRef<(() => void) | null>(null);
  /** ★"窗口被拦"只提示一次：否则每次重新渲染都可能再弹一句。 */
  const warnedRef = useRef(false);

  const stopWatcher = useCallback(() => {
    const stop = stopWatchRef.current;
    stopWatchRef.current = null;
    stop?.();
  }, []);

  /**
   * 盯住窗口关闭。
   *
   * <p>★两条信号都要接：画中画窗口被关掉时<b>只会触发 {@code pagehide}</b>
   * （它不是可导航的文档，{@code beforeunload} 也不一定来），普通弹窗则靠
   * {@code closed} 轮询兜底。漏掉任一条，用户关窗后本页会一直停在"会议在新窗口中"。
   */
  const armWatcher = useCallback(
    (win: Window) => {
      stopWatcher();
      const onClosed = () => useCallStore.getState().setPopout(false);
      try {
        win.addEventListener('pagehide', onClosed);
      } catch {
        /* 窗口已销毁：轮询照样能兜住 */
      }
      const timer = window.setInterval(() => {
        if (win.closed) useCallStore.getState().setPopout(false);
      }, WATCH_INTERVAL_MS);
      stopWatchRef.current = () => {
        try {
          win.removeEventListener('pagehide', onClosed);
        } catch {
          /* 见上 */
        }
        window.clearInterval(timer);
      };
    },
    [stopWatcher],
  );

  // ------------------------------------------------------------ ① 收场时收回本页
  useEffect(() => {
    if (!popout) return;
    const gone = phase === 'idle' || phase === 'ended' || !call || call.mode !== 'room';
    if (gone) {
      useCallStore.getState().setPopout(false);
      // ★会议没开成就收场（点「加入」失败、对手先结束…）：手势里预先开出来的那个
      //   窗口还没被接手，必须在这里关掉，否则屏幕上会留一个空白窗口
      discardPrimedMeetingWindow();
    }
  }, [popout, phase, call]);

  // ------------------------------------------------------------ ② 开 / 关窗口
  useEffect(() => {
    if (!popout) {
      const root = rootRef.current;
      rootRef.current = null;
      if (root) {
        try {
          root.unmount();
        } catch {
          // 窗口已经被用户关掉：卸载会碰到一个已销毁的 document，忽略即可
        }
      }
      closeMeetingWindow(winRef.current);
      winRef.current = null;
      stopWatcher();
      // 同上：没被接手的窗口也是孤儿
      discardPrimedMeetingWindow();
      return;
    }

    // 已经有窗口了（例如 store 被重复置 true）：不重复开，但要把监听补回来
    if (winRef.current && !winRef.current.closed) {
      armWatcher(winRef.current);
      return;
    }

    let cancelled = false;

    const attach = (win: Window) => {
      const container = win.document.getElementById(MEETING_ROOT_ID);
      if (!container) {
        closeMeetingWindow(win);
        winRef.current = null;
        useCallStore.getState().setPopout(false);
        return;
      }
      winRef.current = win;
      const root = createRoot(container);
      rootRef.current = root;
      root.render(<CallOverlay standalone />);
      armWatcher(win);
    };

    void (async () => {
      // ★★只接手"点击时就开出来"的那个窗口（见 lib/meetingWindow.ts 的 primeMeetingWindow）。
      //   ★★这里【不再】回落 openMeetingWindow：走到这一步已经脱离用户手势，
      //   普通弹窗要么被拦，要么（浏览器仍认短时激活时）开出一个带 about:blank
      //   地址栏的窗口 —— 后者正是用户反复看到的"那行又回来了"。
      //   拿不到窗口就留在本页大窗口，比开一个难看的假浏览器窗口好。
      const win = await takePrimedMeetingWindow();
      if (cancelled) {
        // ★这一帧用户已经"收回本页"或会已散：刚拿到的窗口不能留成孤儿
        closeMeetingWindow(win);
        return;
      }
      if (!win) {
        useCallStore.getState().setPopout(false);
        if (!warnedRef.current) {
          warnedRef.current = true;
          message.warning('浏览器拦下了独立窗口，会议仍在本页显示；可点会中的「在新窗口打开」再试');
        }
        return;
      }
      warnedRef.current = false;
      attach(win);
    })();

    return () => {
      cancelled = true;
      stopWatcher();
    };
  }, [popout, message, armWatcher, stopWatcher]);

  // ★组件卸载（登出等）：别把窗口留成孤儿
  useEffect(
    () => () => {
      try {
        rootRef.current?.unmount();
      } catch {
        /* 见上 */
      }
      stopWatcher();
      closeMeetingWindow(winRef.current);
      discardPrimedMeetingWindow();
    },
    [stopWatcher],
  );

  return null;
}
