import { useEffect, useState } from 'react';
import { App as AntApp, Button, Input, Modal, Popconfirm, Typography } from 'antd';
import { convApi } from '../api';
import type { ConversationMemberDto, ConversationSummaryDto, Id } from '../api/types';
import { avatarTone } from '../lib/avatarTone';
// ★★DEV-262 引入、DEV-263 收窄：「发消息」的显隐由服务端 canTalk 决定
// （判据 = 是联系人 ACCEPTED 或任一侧是智能体；曾经还有"有共同 Team"一条，已取消）。
import { talkGateOf } from '../lib/canTalk';
import { accountOf, avatarGradient, remarkOf } from '../lib/contact';
// ★DEV-314 ④：名片上那颗大头像点击 ⇒ 全屏预览（全窗口唯一的预览层挂在 ChatWindow）。
import { requestAvatarPreview } from '../lib/avatarPreview';
import { isImeConfirm } from '../lib/ime';
import {
  MEMBER_ROLE,
  canSetNickName,
  canSetRole,
  contactStateOf,
  isOwner,
  isOwnerOrManager,
  memberAvatarOf,
  memberDisplayName,
  memberInitial,
  nextRoleOf,
  roleTagOf,
  type NameScope,
} from '../lib/memberList';
import { isGroupConv } from '../lib/convType';
import { useChatStore } from '../store/chat';
import { IconChat, IconUserPlus } from './icons';
// ★★DEV-383：裸 <img> 收口到 SmartImg（失败/空值回落首字，不留破图）。
import SmartImg from './SmartImg';

/**
 * ★群名片上限：**必须与后端 {@code MEMBER_NICKNAME_MAX_LEN} 逐字相同**（64）。
 *
 * <p>★与群公告同一个坑：后端数的是<b>码点</b>（{@code requireCharLen}），
 * 而 JS 的 {@code str.length} 数的是 UTF-16 单元（一个 emoji 算 2）。
 * 用 {@code length} 当尺子会在含 emoji 的群名片上误杀 —— 所以这里按码点数，
 * 而且<b>不</b>给 {@code Input} 设 {@code maxLength}（那是 UTF-16 的尺子）。
 */
const NICK_MAX_LEN = 64;

/**
 * ★DEV-379：备注名上限 —— 与后端 {@code ImContactService.MAX_REMARK}、
 * {@code im_contact.remark varchar(64)} 对齐（64）。
 *
 * <p>★与群名片**同一个坑**：后端数的是<b>码点</b>，JS 的 {@code str.length} 数的是
 * UTF-16 单元（一个 emoji 算 2）⇒ 这里同样按码点数、同样<b>不</b>给 {@code Input}
 * 设 {@code maxLength}（复用上面的 {@code charLen}）。
 */
const REMARK_MAX_LEN = 64;

/** 按码点数长度（与后端同一把尺子）。 */
const charLen = (s: string): number => [...s].length;

/**
 * ★用户卡片（DEV-194，照用户给的附件 {@code user_card.png} 做）。
 *
 * <h2>★★底部那个按钮是**两种关系、两个动作**（用户原话）</h2>
 *
 * <blockquote>「可以点击群成员展示用户卡片，如果已经是智联录的联系人了，
 * 展示发消息图标，如果不是则展示添加到智联录按钮」</blockquote>
 *
 * <p>所以关系判定只能有一处真源（{@code lib/memberList} 的 {@code contactStateOf}），
 * 而且**四种关系必须分开**：已经是联系人 / 他申请我 / 我申请他 / 没关系。
 * 「我申请他」这一态最容易被漏 —— 漏了就会给一个「添加到智联录」按钮，
 * 用户反复点、每次都回到同一个"等待同意"，看起来就是点了没反应。
 *
 * <h2>★★DEV-262 引入、DEV-263 收窄：这一维问服务端</h2>
 *
 * <p>用户口径：「只要不是联系人一律拒发……包括页面上搜到人也要动态判断是否展示发消息按钮」。
 * DEV-262 时判据是「是联系人 <b>或</b> 双方有共同 Team」，DEV-263 按用户实测反例
 * 把共同 Team 那条<b>取消</b>了 ⇒ 现在只剩「是联系人（ACCEPTED）或任一侧是智能体」。
 * 于是"没关系"这一态底下仍要再分一次：服务端说能发 ⇒ 给「发消息」，不能 ⇒ 给「添加到智联录」。
 *
 * <p>★这一维<b>前端算不出来</b>（智能体主体类型在服务端），得问服务端。所以本组件多了一个
 * {@code loadCanTalk} 的 effect，读的一律走 {@code talkGateOf} 的三态
 * （{@code 'unknown'} ≠ {@code 'no'}，混起来会让按钮一闪即没）。
 *
 * <h2>★附件里那三个按钮（消息 / 语音 / 视频）只做了「发消息」</h2>
 *
 * <p>语音与视频通话在服务端<b>没有承载</b>（设备表里只有一个 {@code voip_token} 字段，
 * 没有任何通话信令）。按本仓一贯口径：<b>宁可少一个按钮，也不给一个点了没反应的</b> ——
 * 摆一个"未接入"的语音按钮在用户卡片最显眼的位置，是拿用户当测试用例。
 * 这一点记在 {@code docs/05} DEV-194，不是遗漏。
 *
 * <p>★附件里的「组织」「未认证」徽章同理<b>没有做</b>：成员列表接口
 * （{@code ConversationMemberDto}）里没有组织/实名信息，也没有按 userId 查资料的端点
 * （全仓只有 {@code /users/me}）。编一个"未认证"标签比不显示它更糟。
 *
 * <h2>★★DEV-197：多了一块「群管理」</h2>
 *
 * <p>两个动作：<b>设/撤管理员</b>（仅群主）与<b>设置群名片</b>（群主/管理员，
 * 管理员管不了同级与群主）。★入口放在卡片上而不是群设置页，是因为这两个动作
 * 都作用在<b>某个人</b>身上 —— 放在设置页会变成"先选人再选动作"的两步操作。
 *
 * <p>★判据一律来自 {@code lib/memberList}（{@code canSetRole} / {@code canSetNickName}），
 * 与成员行上那个「移除」共用同一套"谁能管谁"的规则（{@code memberRoleLevel}）。
 * <b>不</b>在这里另算一份：分叉的表现是"界面给了按钮、服务端拒绝"，
 * 或者更糟 —— "界面没给按钮而用户其实有权限"（后者没人会来报 bug）。
 *
 * <p>★{@code conv} 由外层传（成员面板手上有它）：群主的判定需要
 * {@code conv.ownerUserId} 这个**第三个真源** —— 成员行上那两个布尔
 * 万一都没带上，靠它仍然认得出群主。
 */
export default function UserCard({
  member,
  conv,
  onOpenChat,
  onClose,
}: {
  member: ConversationMemberDto;
  /** ★当前会话（DEV-197 的群管理判据要用 {@code ownerUserId} / {@code myRole}）。 */
  conv?: ConversationSummaryDto | null;
  /** ★「发消息」成功后回调（带上刚开好的 convId），由外层切会话与标签页。 */
  onOpenChat?: (convId: Id) => void;
  /** ★卡片里的动作做完之后希望浮层收起（发消息 / 同意申请都会离开当前上下文）。 */
  onClose?: () => void;
}) {
  const userId = useChatStore((s) => s.userId);
  const contacts = useChatStore((s) => s.contacts);
  const startChatWith = useChatStore((s) => s.startChatWith);
  const addContact = useChatStore((s) => s.addContact);
  const acceptContact = useChatStore((s) => s.acceptContact);
  const loadMembers = useChatStore((s) => s.loadMembers);
  const loadConversations = useChatStore((s) => s.loadConversations);
  // ★DEV-379：改备注名（只改我这一行）。★这是**现成的**仓储动作 —— 与智联录
  //   「修改备注」共用同一条链路（store 里已封装"调用 + 重拉联系人"）。
  const remarkContact = useChatStore((s) => s.remarkContact);
  const { message: toast } = AntApp.useApp();

  const [busy, setBusy] = useState<'' | 'chat' | 'contact' | 'accept' | 'role' | 'nick' | 'remark'>('');
  const [nickOpen, setNickOpen] = useState(false);
  const [nickDraft, setNickDraft] = useState('');
  const [remarkOpen, setRemarkOpen] = useState(false);
  const [remarkDraft, setRemarkDraft] = useState('');

  const canTalkMap = useChatStore((s) => s.canTalkMap);
  const loadCanTalk = useChatStore((s) => s.loadCanTalk);

  const isSelf = userId != null && String(member.userId) === String(userId);
  const state = isSelf ? 'none' : contactStateOf(contacts, member.userId);
  /**
   * ★★DEV-262：能不能给他发消息。★判据是「是我的联系人(ACCEPTED) **或** 任一侧是智能体」，
   * 后者前端算不出来 ⇒ 问服务端（见 store 的 {@code loadCanTalk}）。
   * ★DEV-263 起"双方有共同 Team"那条已取消。
   *
   * <p>★★读的一律走 {@code talkGateOf} 拿三态，<b>绝不</b>写成 {@code canTalkMap[id] === true}
   * 之外的形态：{@code 'unknown'}（还没查出来）必须与 {@code 'no'} 分得开 ——
   * 混在一起就等于"首屏还没查完先把按钮藏了"，用户看到的是按钮一闪即没。
   */
  const gate = isSelf ? 'unknown' : talkGateOf(canTalkMap, member.userId);

  // ★已经是我联系人时不必问（{@code state === 'contact'} 本身就够开这个按钮了）；
  //   ★自己也不问。其余三态（他申请我 / 我申请他 / 没关系）都要问一句 ——
  //   因为"不是联系人但同 Team"照样可以发，这正是用户那句
  //   「只要我们存在共同的团队（Team）就可以发消息」的落点。
  //   ★本调用幂等（已经问过的不会再发请求），所以这个 effect 重复跑是安全的。
  useEffect(() => {
    if (isSelf || state === 'contact') return;
    void loadCanTalk([member.userId]);
  }, [isSelf, state, member.userId, loadCanTalk]);

  const role = roleTagOf(member);
  /**
   * ★★第 4 条拍板（2026-10-08）：用户名片的名字链**按语境选** ——
   * 群里「群名片 → 备注名 → 昵称」，私聊里「备注名 → 群名片 → 昵称」。
   *
   * <p>这张卡片**两个语境都会出现**（群里点头像 / 私聊里点对方头像），
   * 所以不能像成员面板、禁言弹窗那样写死一边；判据复用
   * {@code lib/convType#isGroupConv}（与公告面板、设置面板同一把尺子）。
   *
   * <p>★拿不到 {@code conv}（理论上不该发生）时按**私聊**走：退化成 DEV-312 ⑦
   * 的老行为，不会把群名片误当成本群的名字显示出去 —— 这个方向上出错只是"没变好"。
   *
   * <p>★DEV-312 ⑦（落点6）的语义在私聊这条链上原样保留：点开名片看到的是
   * "我给 TA 起的名字"。底色/首字与这个 name 同源（下面 avatarTone(name)）。
   */
  const nameScope: NameScope = isGroupConv(conv?.convType) ? 'group' : 'direct';
  const name = memberDisplayName(member, remarkOf(contacts, member.userId), nameScope);
  /** ★DEV-312 ⑥a：真头像判据收口 lib/memberAvatarOf（null = 走首字兜底），
      与成员行那颗**同一把尺子** —— 卡片与列表一边有图一边永远首字会当场穿帮。 */
  const avatarSrc = memberAvatarOf(member);

  /**
   * ★★DEV-390：名片上补「昵称：」「账号：」两行 —— 用户 2026-10-13 给了一张微信
   * 个人信息页的截图，原话「**名片卡片上参考微信展示的字段**」。
   *
   * <h2>用户三项拍板（表单 {@code usercard-wechat-fields-1}）</h2>
   * <ul>
   *   <li>① 加「昵称：」<b>与</b>「账号：」两行（对齐微信）；</li>
   *   <li>② <b>只改前端、零服务端改动</b> —— 账号从"他是我联系人"那一行取，
   *       群里点陌生人头像时这一行不出现（这是用户<b>明知</b>并接受的代价）；</li>
   *   <li>③ 标签用「<b>账号：</b>」（与智联录联系人列表现有写法一致）。</li>
   * </ul>
   * <p>★<b>性别图标不做</b>：平台用户资料（{@code PlatformUserInfo}）里
   * <b>根本没有性别字段</b>（只有 {@code userId/tenantId/userName/nickName/avatar/status}）。
   * 编一个性别出来比不显示它更糟 —— 与类注释里「组织/未认证徽章」同一条口径。
   *
   * <h2>★★两行的显示判据：全部是为了"不显示重复/错误的行"</h2>
   *
   * <p>{@code member.name} 的语义是「<b>平台昵称 ?: 平台账号名</b>」（服务端
   * {@code ImConversationDtoAssembler#nameOf}）—— 也就是说<b>它可能就是这个人的账号名</b>。
   * 照抄一行「昵称：{@code member.name}」会出现两种明显的错：
   * <ol>
   *   <li>没设昵称的人，昵称行会显示他的<b>账号名</b> —— 那是<b>标注错误</b>，
   *       比不显示严重（用户会认为"我的昵称怎么变成 lisi 了"）；</li>
   *   <li>大字显示名（群名片/备注/昵称链的结果）与昵称行<b>逐字相同</b>时，
   *       卡片上会连着出现两遍同一个名字。</li>
   * </ol>
   * <p>⇒ 昵称行的判据是三重：非空 <b>且</b> 不等于大字显示名 <b>且</b> 不等于账号名；
   * 账号行的判据是两重：非空 <b>且</b> 不等于大字显示名。
   * ★副作用是"有区分度时才显示"：设了备注/群名片的人必然看到两行（与微信截图一致）；
   * 什么都没设的人只看到「账号：」那一行 —— 这不是"昵称行丢了"，是它没有新信息。
   */
  const account = accountOf(contacts, member.userId);
  /** 平台侧那个名字（= 昵称 ?: 账号名）。★空串与"没有"是一回事（服务端可能降级成 null）。 */
  const platformName = (member.name ?? '').trim() || null;
  const showPlatformNick = platformName != null && platformName !== name && platformName !== account;
  const showAccount = account != null && account !== name;

  // ★DEV-197 群管理：判据全部来自 lib/memberList（见类注释）。
  const amOwner = isOwner(conv, userId);
  const amOwnerOrManager = isOwnerOrManager(conv, userId);
  const ownerUserId = conv?.ownerUserId;
  const viewerId = userId;
  const showSetRole = canSetRole({ iAmOwner: amOwner, viewerId, member, ownerUserId });
  const showSetNick = canSetNickName({ iAmOwnerOrManager: amOwnerOrManager, iAmOwner: amOwner, viewerId, member, ownerUserId });
  /** ★点了之后会变成的角色（1 撤销 / 2 设为）。★永不返回 3（见 lib/memberList）。 */
  const nextRole = nextRoleOf(member);
  const isAdminNow = nextRole === MEMBER_ROLE.MEMBER;
  const nickOver = charLen(nickDraft) > NICK_MAX_LEN;

  /**
   * ★DEV-379：备注名（只写我这一行；空 = 没设过，显示回落平台昵称）。
   * 显示名链（上面的 {@code name}）已经吃了它，这里只是把"我给他起的名字"
   * 单独摆出来一行，好让用户在**当前语境**下就知道自己有没有设过。
   */
  const myRemark = remarkOf(contacts, member.userId);
  const remarkOver = charLen(remarkDraft) > REMARK_MAX_LEN;
  /**
   * ★DEV-379：改备注的入口只在**他是我的联系人**时出现。
   *
   * <p>判据用 {@code contactStateOf} 的 {@code 'contact'}（ACCEPTED 双向态），
   * <b>不</b>用 canTalk 那个 gate：**能发消息 ≠ 在通讯录里** —— 智能体就是典型
   * （可以发消息，但没有"联系人那一行"，备注无处可写，服务端会直接返回 false）。
   * 这两件事混起来的表现是"给了入口、点了报错"，与 DEV-263 收窄 canTalk 是同一条纪律。
   */
  const showRemark = state === 'contact';

  /** ★设/撤管理员：服务端会向全群发一条系统消息，所以外面套了 Popconfirm。 */
  const onSetRole = async () => {
    if (conv?.convId == null) return;
    setBusy('role');
    try {
      const changed = await convApi.setMemberRole(conv.convId, member.userId, nextRole);
      // ★false = 值没变化、服务端没写库（DEV-39），不是失败。
      toast.success(changed ? (isAdminNow ? '已撤销管理员' : '已设为管理员') : '内容没有变化');
      await loadMembers(conv.convId);
      await loadConversations();
    } catch (e) {
      toast.error((e as Error).message);
    } finally {
      setBusy('');
    }
  };

  /** ★设置群名片：空串 = 清除、回落平台昵称（服务端语义），所以永远传字符串。 */
  const onSetNick = async () => {
    if (conv?.convId == null) return;
    setBusy('nick');
    try {
      const changed = await convApi.setMemberNickName(conv.convId, member.userId, nickDraft);
      toast.success(changed ? '群名片已更新' : '内容没有变化');
      setNickOpen(false);
      await loadMembers(conv.convId);
    } catch (e) {
      toast.error((e as Error).message);
    } finally {
      setBusy('');
    }
  };

  /**
   * ★DEV-379：设/清备注名（只改我这一行）。
   *
   * <p>★★**必须看服务端返回值**：{@code updateRemark} 的 {@code false} 不是"内容没变化"，
   * 而是**"对方还不在我的通讯录里"**（{@code ImContactService#updateRemark} 的
   * {@code @return} 注释；底层 {@code UPDATE im_contact ...} 影响行数为 0 就是这个意思）。
   * 两者混起来的后果是：给一个**非联系人**（智能体、陌生人）点了"修改备注"，
   * 界面回一句"备注已更新"、库里一个字没写 —— 用户下次点开还是老样子。
   *
   * <p>★这也正是 {@code ContactList#onRemarkSave} 现役口径的缺陷（丢弃返回值、一律弹成功）；
   * 本处**不照抄**。智联录那处是否一并改，留给用户拍板（见本批报告），不在此处擅自扩大范围。
   *
   * <p>★空串 = 清除备注（服务端语义），所以不做非空校验。
   * ★刻意**不**在这里调 {@code loadConversations()}：DEV-374 之后它是"重置到第一页"，
   *   在名片里触发会把用户已经滚了很多屏的会话列表弹回顶部。
   *   store 的 {@code remarkContact} 已经重拉了联系人（本卡片显示名的真源），够了。
   */
  const onSetRemark = async () => {
    setBusy('remark');
    try {
      const next = remarkDraft.trim();
      const ok = await remarkContact(member.userId, next);
      if (ok) {
        toast.success(next ? '备注已更新' : '备注已清除');
        setRemarkOpen(false);
      } else {
        toast.error('TA 还不在你的智联录里，先添加为联系人');
      }
    } catch (e) {
      toast.error((e as Error).message || '备注保存失败');
    } finally {
      setBusy('');
    }
  };

  /**
   * ★「发消息」：建/开单聊 → 把对方落到我这边 → 交给外层切过去（与「添加伙伴」同一个动作）。
   *
   * ★★DEV-373：成功时【刻意不弹 toast】（用户 2026-10-10：「不用提示"已发起会话"」）。
   *   这张卡片随即关闭、并切到那个会话 —— **界面本身就是回执**，再补一条提示纯属噪音。
   *   ★失败**照旧弹**（见下面的 `toast.error`）：「什么都没发生」必须说出来。
   *   ★`AddPartnerModal.onSendChat` 是同一个动作，**同批同口径**（两处文案原本一字不差）。
   */
  const onSend = async () => {
    setBusy('chat');
    try {
      const convId = await startChatWith(member.userId);
      onClose?.();
      onOpenChat?.(convId);
    } catch (e) {
      toast.error((e as Error).message || '发起会话失败');
    } finally {
      setBusy('');
    }
  };

  /** ★「添加到智联录」：走申请/同意链路（不传 direct ⇒ 对方会收到一条待同意申请）。 */
  const onAdd = async () => {
    setBusy('contact');
    try {
      const r = await addContact(member.userId);
      // ★文案必须区分三种落地形态，否则用户不知道该等谁：
      //   applied=真的发了申请 / accepted=对方本来就申请过我，直接成了 / direct=直连（智能体）
      toast.success(r.accepted ? '已互相成为联系人' : '已发送申请，等待对方同意');
    } catch (e) {
      toast.error((e as Error).message || '添加失败');
    } finally {
      setBusy('');
    }
  };

  const onAccept = async () => {
    setBusy('accept');
    try {
      await acceptContact(member.userId);
      toast.success('已同意，你们现在是联系人');
    } catch (e) {
      toast.error((e as Error).message || '同意失败');
    } finally {
      setBusy('');
    }
  };

  return (
    <div className="user-card">
      {/* ★封面色与头像色**同源**（DEV-201 起改由 `memberDisplayName` 首字与成员面板同源）：
          两处独立取色的话，同一个人的卡片换个会话就会变成另一种配色。
          ★★DEV-201：**头像**改用 `avatarTone`（与成员列表里那颗、左栏会话列表那颗
          **完全同一套**，这是用户要的"别千篇一律"能落地的前提）；
          **封面**保留原来的 `avatarGradient(member.userId)` —— 它是卡片顶部的
          大色块（不是头像），压成中低彩度的实心色会让整张卡片变闷，
          而且它不参与"认出是谁"这件事。两处仍是同源关系（都以这个人自己的
          标识为输入），只是取了不同浓度的表现。 */}
      <div className="user-card-cover" style={{ background: avatarGradient(member.userId) }} />
      {/* ★DEV-312 ⑥a：有真头像渲染 <img>（判据收口 lib/memberAvatarOf，空串已归一
          成 null 不会破图），无图保持"首字 + avatarTone 底色"。底色纪律不变：
          只在无图时给 —— 有图时底色被图片整个盖住，给了也是白给。

          ★★DEV-314 ④（用户原话「点击头像先展示用户名片……**点击名片上的头像才看大图**」）：
          **全屏大图预览的入口从"各处头像"收拢到了这一颗** —— 别处的头像现在开的是
          UserCardTrigger 那张名片，只有名片上这颗大头像才直接弹预览。
          ★只有**真有图**才可点：文字兜底（首字）没有 src，点开必然裂图 ⇒ 不挂 onClick、
          不给手型（与 MessageBubble / ChatWindow 同一条纪律；空 src 的第二道闸在
          lib/avatarPreview 里）。判据用 avatarSrc 而不是再判一次 member.avatar ——
          本组件里"有没有图"只有这一个真源。
          ★★这段注释刻意放在**元素之外**：下面那颗 <img> 与 className 的字符距离本身
          是一条纪律断言的判据（memberList.test.ts 的 assertAvatarRendersImage 用
          "<img> 离坑位 className 不超过 500 字符"近似"在同一个坑位里"）。注释塞进
          标签内部会把那段距离顶过阈值，把一个正确的实现判成"头像又只画首字了"。 */}
      <div
        className="user-card-avatar"
        // ★DEV-314 ④：有图 ⇒ 可点看大图（手型），无图 ⇒ 保持原来的"首字 + 底色"。
        style={avatarSrc ? { cursor: 'pointer' } : avatarTone(name)}
        onClick={avatarSrc ? () => requestAvatarPreview(avatarSrc) : undefined}
        title={avatarSrc ? '点击看大图' : undefined}
      >
        {/* ★★DEV-383：原来这里是**裸 `<img>`** —— 名片头像加载失败就留一个破图图标
            （本批顺带查出的 5 处缺口之一；同一形态的成员行见 MemberPanelBody）。
            ★改用 SmartImg 后外层那个三元判空**不必再写**：它的契约就是"src 为空 ⇒
              一个请求都不发、直接渲染 fallback"（见其类注释第二条）。上面两处
              `avatarSrc` 判断管的是"能不能点/要不要手型"，与渲染什么无关，保持原样。
            ★首字语境要求（与上面的显示名同语境）由下面那个 memberInitial 的第三参承担。 */}
        <SmartImg
          src={avatarSrc}
          alt=""
          fallback={memberInitial(member, remarkOf(contacts, member.userId), nameScope)}
        />
      </div>

      <div className="user-card-body">
        <div className="user-card-name-row">
          <span className="user-card-name">{name}</span>
          {role && <span className={`user-card-role${role === '群主' ? ' owner' : ''}`}>{role}</span>}
          {isSelf && <span className="user-card-role">这是你</span>}
        </div>
        {/* ★★DEV-202 #218：这一行原本是 `ID {userId}`（「明写出来，供『按群号/ID 加人』用」）。
            本轮用户口径是「**不显示用户 id**」，且 #217 会把"按 id 添加"整个去掉 ——
            那一行失去存在理由，删掉。★不是把它藏起来：卡片上再没有别的地方需要这个数字，
            留着 `user-card-id` 类名反而会让下一个人以为"只是暂时隐藏了"。
            （`.user-card-id` 这条 CSS 现在成了无人使用的死规则，见 styles.css 里的注记。） */}

        {/* 空串的 nickname 与「没有群名片」是一回事，不要显示一行空白。 */}
        {member.nickName ? <div className="user-card-line">群名片：{member.nickName}</div> : null}

        {/* ★★DEV-390：照微信个人信息页补的两行（判据与理由见上面 showPlatformNick /
            showAccount 的注释块，这里只说位置）。
            ★★位置是**硬约束**：必须紧跟在**群名片行之后** —— 成员面板量具
            verify-member-panel.mjs 取名片里【第一个】`.user-card-line` 当作
            "群名片行"来断言，新行插到它前面会让那条与本需求毫无关系的断言直接变红。
            ★各自多带一个类名（user-card-nick / user-card-account）只为让量具能精确选到
            这两行；视觉上仍复用 `.user-card-line`，不新增 CSS。
            ★两行都是**只读文本**：账号是平台侧的事实、昵称是平台侧的昵称，
            我们这边没有任何可改它们的入口（能改的只有群名片与备注，那两行各自带着按钮）。 */}
        {showPlatformNick ? (
          <div className="user-card-line user-card-nick">昵称：{platformName}</div>
        ) : null}
        {showAccount ? (
          <div className="user-card-line user-card-account">账号：{account}</div>
        ) : null}

        {/* ★DEV-379：备注行 —— 入口按用户拍板放在**名片**上（不再只藏在智联录里）。
            ★只对"他是我的联系人"显示（见上面 showRemark 的注释：能发消息 ≠ 在通讯录里）。
            ★没设过时也**留着这一行**并显示「未设置」：留白会让用户以为"这里不能改备注"，
              而这正是本需求的痛点（原来根本找不到入口）。
            ★有备注时把值显示出来 —— 它是"我给他起的名字"，用户不该被迫去会话列表里核对。
            ★自己那行本来就没有（state 恒为 'none'），无需额外判断。 */}
        {showRemark && (
          <div className="user-card-line user-card-remark">
            <span className="user-card-remark-label">备注：</span>
            {myRemark ? (
              <span className="user-card-remark-value">{myRemark}</span>
            ) : (
              <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                未设置
              </Typography.Text>
            )}
            <Button
              type="link"
              size="small"
              style={{ padding: 0, height: 'auto' }}
              onClick={() => {
                // ★用当前备注预填：改半个字时不用从头再敲（与设置群名片同一手法）。
                setRemarkDraft(myRemark ?? '');
                setRemarkOpen(true);
              }}
            >
              {myRemark ? '修改' : '设置'}
            </Button>
          </div>
        )}

        {/* ★DEV-197 群管理区。★一个人都管不了时（普通成员、或者目标是群主/同级管理员）
            整块**不渲染** —— 留一个空的「群管理」标题会让用户以为功能坏了。 */}
        {(showSetRole || showSetNick) && (
          <div className="user-card-admin">
            <div className="user-card-admin-title">群管理</div>
            <div className="user-card-admin-actions">
              {showSetRole && (
                <Popconfirm
                  title={isAdminNow ? '撤销管理员' : '设为管理员'}
                  // ★把"全群会收到通知"写在确认框里：这是一个对外可见的动作，
                  //   用户点之前应当知道不只是他这一屏会变。
                  description={
                    isAdminNow
                      ? `撤销后 ${name} 变回普通成员，全群会收到一条通知`
                      : `${name} 将可以管理群成员，全群会收到一条通知`
                  }
                  okText="确定"
                  cancelText="取消"
                  onConfirm={() => onSetRole().catch(() => undefined)}
                >
                  <Button size="small" loading={busy === 'role'}>
                    {isAdminNow ? '撤销管理员' : '设为管理员'}
                  </Button>
                </Popconfirm>
              )}
              {showSetNick && (
                <Button
                  size="small"
                  onClick={() => {
                    // ★用当前群名片（可能是空）预填：用户改了半个字的名字时
                    //   不用从头再敲一遍。
                    setNickDraft(member.nickName ?? '');
                    setNickOpen(true);
                  }}
                >
                  设置群名片
                </Button>
              )}
            </div>
          </div>
        )}

        <div className="user-card-actions">
          {isSelf ? (
            // ★自己不发消息（那会开一个跟自己聊的会话）、也不能加自己为联系人。
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              这是你自己
            </Typography.Text>
          ) : state === 'contact' ? (
            <Button type="primary" block loading={busy === 'chat'} icon={<IconChat size={15} />} onClick={() => onSend().catch(() => undefined)}>
              发消息
            </Button>
          ) : state === 'incoming' ? (
            // ★他申请加我 ⇒ 这里就是那个「同意」的入口（与智联录的「新的伙伴申请」同一个动作）。
            <Button type="primary" block loading={busy === 'accept'} onClick={() => onAccept().catch(() => undefined)}>
              同意申请
            </Button>
          ) : state === 'outgoing' ? (
            // ★已经申请过了 —— 不再给按钮（再点一次什么都不会发生，见类注释）。
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              已发送申请，等待对方同意
            </Typography.Text>
          ) : gate === 'yes' ? (
            // ★★DEV-262：{@code gate === 'yes'} = 服务端判定"能发"。
            //   ★DEV-263 起这一支的现实形态收窄成【对方是智能体】（我删了智能体联系人也能发，
            //   这条豁免是用户拍板要保的）；本地联系人列表与服务端不同步时也会落到这里。
            //   两种情况都该给「发消息」而不是「添加到智联录」。
            //
            //   ★为什么只加在**最后一个分支**（而不是把条件并进上面那句
            //   {@code state === 'contact'}）：那样会**吞掉**「同意申请」这个入口 ——
            //   他申请加我、而服务端又说能发时，卡片上就只剩「发消息」，
            //   用户永远点不到「同意」。两件事互不冲突，谁都不该盖住谁。
            //
            //   ★{@code 'unknown'} 刻意**不**落进这一支：它只表示"还没问出结果"，
            //   与"确定能发"是两回事（见 lib/canTalk.ts 头注释）。
            <Button type="primary" block loading={busy === 'chat'} icon={<IconChat size={15} />} onClick={() => onSend().catch(() => undefined)}>
              发消息
            </Button>
          ) : (
            <Button type="primary" block loading={busy === 'contact'} icon={<IconUserPlus size={15} />} onClick={() => onAdd().catch(() => undefined)}>
              添加到智联录
            </Button>
          )}
        </div>
      </div>

      {/* ★设置群名片的弹窗。★放在 `.user-card` **外面**：卡片本体是
          {@code .user-card-popover} 里的内容，浮层自带 overflow/定位，
          把 Modal 嵌在里面会被浮层的层叠上下文困住（antd Modal 用的是 portal，
          但 DOM 上的父子关系仍会让某些样式作用域命中它）。 */}
      <Modal
        title={`设置 ${name} 的群名片`}
        open={nickOpen}
        onCancel={() => setNickOpen(false)}
        onOk={() => onSetNick().catch(() => undefined)}
        confirmLoading={busy === 'nick'}
        okText="保存"
        cancelText="取消"
        okButtonProps={{ disabled: nickOver }}
        width={360}
      >
        <Input
          value={nickDraft}
          autoFocus
          placeholder="留空 = 使用他的昵称"
          onChange={(e) => setNickDraft(e.target.value)}
          /* ★★DEV-254 需求①：管理员改群名片时输入法组合中按回车**不是**提交（见 lib/ime.ts）。 */
          onPressEnter={(e) => {
            if (isImeConfirm(e)) return;
            if (!nickOver) onSetNick().catch(() => undefined);
          }}
        />
        <div className="nick-hint">
          {/* ★与群公告同一个尺子（按码点数，见文件头的 NICK_MAX_LEN）。 */}
          <Typography.Text type={nickOver ? 'danger' : 'secondary'} style={{ fontSize: 12 }}>
            群名片只在这个群里显示，不影响他的昵称。{charLen(nickDraft)} / {NICK_MAX_LEN}
            {nickOver && '（超出上限，服务端会拒绝）'}
          </Typography.Text>
        </div>
      </Modal>

      {/* ★DEV-379：设置备注名的弹窗。形制与上面「设置群名片」同一个母版
          （portal 在 `.user-card` 外面、IME 回车不提交、按码点数上限）。
          ★语义差别写进提示语里：群名片是**全群可见**的，备注是**只有我自己看得到**的 ——
            用户点之前必须分得清这两件事，否则会以为改了备注别人也能看见。 */}
      <Modal
        title={`设置 ${name} 的备注名`}
        open={remarkOpen}
        onCancel={() => setRemarkOpen(false)}
        onOk={() => onSetRemark().catch(() => undefined)}
        confirmLoading={busy === 'remark'}
        okText="保存"
        cancelText="取消"
        okButtonProps={{ disabled: remarkOver }}
        width={360}
      >
        <Input
          value={remarkDraft}
          autoFocus
          placeholder="留空 = 清除备注，显示他的昵称"
          onChange={(e) => setRemarkDraft(e.target.value)}
          /* ★与设置群名片同一条纪律：输入法组合中按回车**不是**提交（lib/ime.ts）。 */
          onPressEnter={(e) => {
            if (isImeConfirm(e)) return;
            if (!remarkOver) onSetRemark().catch(() => undefined);
          }}
        />
        <div className="nick-hint">
          {/* ★与群名片同一个尺子（按码点数，见文件头的 REMARK_MAX_LEN /
              后端 ImContactService.MAX_REMARK / im_contact.remark varchar(64)）。 */}
          <Typography.Text type={remarkOver ? 'danger' : 'secondary'} style={{ fontSize: 12 }}>
            备注只有你自己看得到，对方不会收到通知。{charLen(remarkDraft)} / {REMARK_MAX_LEN}
            {remarkOver && '（超出上限，服务端会拒绝）'}
          </Typography.Text>
        </div>
      </Modal>
    </div>
  );
}
