import { getMessageElementById, getMessageInputRoot, getMessagePortalRoot, redirectMessageAuth } from './hostRuntime';
import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { Alert, App as AntApp } from 'antd';
import { isPlatformMode } from './authMode';
import LoginPage from './pages/LoginPage';
import ChatPage from './pages/ChatPage';
import GuestMeetingPage from './pages/GuestMeetingPage';
import CallOverlay from './components/CallOverlay';
import MeetingInviteOverlay from './components/MeetingInviteOverlay';
import MeetingPopout from './components/MeetingPopout';
import { readAuthExpiredDetail } from './lib/authEvents';
import { readInviteNo } from './lib/meetingLink';
import { useChatStore } from './store/chat';
// ★★DEV-389：周期兜底对账的间隔（45s）。★刻意从 lib 取而不是在这里写 45000 ——
//   那个常量带着"为什么取区间中点而不是 30/60"的理由与单测（见 lib/reconcilePoll.ts）。
import { RECONCILE_POLL_INTERVAL_MS } from './lib/reconcilePoll';
import { KickReason } from './ws/protocol';

/**
 * ★★`index.html` 里那块静态启动骨架的元素 id（DEV-168）。
 *
 * <p>它盖住的是<b>bundle 加载期</b>的白屏（几十~几百毫秒）——
 * 那段时间 React 一行都还没跑，所以骨架只能写在 HTML 里。
 * ★id 是两处（{@code index.html} 与这里）的约定，改一处必须改另一处；
 * 一致性由 {@code scripts/verify-boot-no-flash.mjs} 量尺寸/底色来兜底。
 */
const BOOT_SKELETON_ID = 'boot-skeleton';

/**
 * ★★邀请链接进来、登录态还在探测时的一张"稍等"卡。
 *
 * <p>★为什么不能直接渲染访客页等结果：平台模式下 {@code restoreSession} 要打一次
 * {@code /users/me} 才知道"我是谁"。先渲染访客页的话，<b>已登录</b>的人会先看到
 * 昵称表单、一两秒后再被换成 IM 客户端 —— 那正是用户抱怨过的"闪"。
 * 这张卡只盖住探测期，样式与访客页同源（{@code .gm-*}），不会换皮。
 */
function InviteBooting({ room }: { room: string }) {
  return (
    <div className="gm-page">
      <section className="gm-card">
        <div className="gm-spinner" />
        <h1>正在确认登录状态…</h1>
        <p className="gm-hint">会议号 {room}</p>
      </section>
    </div>
  );
}

function Shell() {
  const userId = useChatStore((s) => s.userId);
  const authProbe = useChatStore((s) => s.authProbe);
  const authRedirectTarget = useChatStore((s) => s.authRedirectTarget);
  const kicked = useChatStore((s) => s.kicked);
  const rejectMsg = useChatStore((s) => s.rejectMsg);
  const clearKicked = useChatStore((s) => s.clearKicked);
  const restoreSession = useChatStore((s) => s.restoreSession);
  const handleAuthExpired = useChatStore((s) => s.handleAuthExpired);
  const { message } = AntApp.useApp();

  /**
   * ★★会议邀请链接里的入会标识（{@code ?meeting=<邀请码>}，老链接是 9 位会议号）。
   *
   * <p>★只在<b>挂载时</b>读一次：这是"打开页面时的入口参数"，不是会随交互变化的状态。
   * 读出来之后<b>不能</b>像 MeetingPane 那样立刻从地址栏抹掉 —— 访客刷新页面、
   * 或把链接再转发给别人时，会议号必须还在。
   *
   * <p>★未登录 + 有这个参数 ⇒ 走访客入会页（见下面的渲染矩阵）；
   * 已登录时仍然走原来的 IM 客户端（{@code MeetingPane} 会打开"加入会议"弹窗）。
   */
  const [inviteRoom] = useState(() => readInviteNo(window.location.search));

  /**
   * ★★刷新恢复会话 —— 本次接入平台登录态的入口点。
   *
   * <p>两种模式下它做的事完全不同（见 {@code store/chat.ts#restoreSession}）：
   * <ul>
   *   <li>mock：localStorage 里有 {@code mock-token-{id}} 就直接建连；</li>
   *   <li>platform：★localStorage 里<b>什么都没有</b>（凭据是同域 Cookie），
   *       唯一能回答"我是谁"的是服务端 ⇒ 打一次 {@code /users/me} 探测。</li>
   * </ul>
   * <p>★无论哪种模式，这里都<b>不</b>自己判登录成败 —— 探测失败时 store 会把
   * {@code authProbe} 置成 {@code unauthenticated} / {@code unavailable} / {@code redirecting}，
   * 由下面的渲染矩阵决定显示什么、由跳转 effect 决定去哪。App 只负责"发起一次"。
   */
  useEffect(() => {
    restoreSession().catch(() => undefined);
    // 只在挂载时恢复一次
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /**
   * ★★DEV-173：页面要走时把攒着的缓存落盘。
   *
   * <p>缓存平时是攒够 1.2 秒（最多 6 秒）自动写的，但"用户切走/关掉标签页"
   * 不会等这 1.2 秒 —— 定时器再也没有机会触发，而攒在内存里的那批恰恰是
   * 他刚看过的最后几条，是最值钱的一批（下一次冷启动贴的就是它）。
   *
   * <p>★为什么是 {@code pagehide} 而不是 {@code beforeunload}：
   * 后者在移动端和 bfcache 场景<b>不可靠</b>（Safari 上经常根本不触发），
   * 而且注册它会让页面失去 bfcache 资格 —— 换来的却是更差的触发保证。
   * {@code pagehide} 加上 {@code visibilitychange→hidden} 覆盖了关标签页、
   * 切到后台、切到别的 App 三种"真的要走"的情形；重复触发是安全的
   * （{@code flushNow} 在没有脏数据时是空操作，不会白写一次盘）。
   *
   * <p>★挂载期只注册不注销的代价为零：本组件是整棵树的根，与页面同生命周期。
   * 但为了不给 StrictMode 的双执行留下两个监听器，还是老老实实配对的注销。
   */
  useEffect(() => {
    const flush = () => useChatStore.getState().flushCacheNow();
    const onHide = () => {
      // ★只在真的隐藏时写：切回来也会触发一次 visibilitychange（state='visible'）。
      if (document.visibilityState === 'hidden') flush();
    };
    window.addEventListener('pagehide', flush);
    document.addEventListener('visibilitychange', onHide);
    return () => {
      window.removeEventListener('pagehide', flush);
      document.removeEventListener('visibilitychange', onHide);
    };
  }, []);

  /**
   * ★★DEV-179：用户重新"在看"这个页面了 ⇒ 把欠着的已读补掉。
   *
   * <p>用户原话：「用户焦点不在当前浏览器标签时，虽然打开了对话，但也不要直接已读，
   * 用户重新聚焦回来后真正看了才已读」。
   * <b>前半句</b>由 store 里 {@code reportRead} 的闸门负责（判据见
   * {@code lib/userPresence.ts}：标签可见 <b>且</b> 窗口有焦点），
   * 这里负责的是<b>后半句</b>。
   *
   * <p>★为什么必须监听<b>两个</b>事件 —— 它们回答的是两个不同的问题，且不保证同时到达：
   * <ul>
   *   <li>{@code visibilitychange}：标签从后台回到前台（切标签页、最小化后还原）；</li>
   *   <li>{@code window focus}：窗口拿到了焦点（从别的应用切回来、被盖住的窗口重新点开）。
   *       ★这一条<b>原先没有任何地方监听</b>，而它恰恰是用户说的"重新聚焦"——
   *       只监听可见性的话，"窗口被别的应用盖住"这种失焦方式切回来时不会触发任何补报。</li>
   * </ul>
   * 切标签页再切回来时两个事件都会到（先后不定）⇒ 会补报两次，这是<b>幂等</b>的
   * （{@code reportRead} 报的是同一个 seq，且第二次本地未读已经是 0）。
   *
   * <p>★为什么挂在这里而不是 {@code ChatWindow}：那里曾有一段"切回可见就补一次已读"，
   * 但它挂在<b>会卸载的组件</b>上 —— 右栏没有打开会话时它根本不挂载，
   * 而"什么时候该补报"是个<b>页面级</b>生命周期问题（与右栏显示什么无关）。
   * ⇒ 收进 App：一处监听、一处补报。
   *
   * <p>★★DEV-181：<b>只有上</b>面两个事件<b>不够</b> —— 用户报「浏览器获取焦点后，
   * 有时没有触发已读，不是很好复现」。
   *
   * <p>★缺的那一类：<b>焦点从浏览器自己的界面回到页面时，{@code window} 上不会有 focus 事件</b>。
   * 地址栏 / 书签栏 / 停靠的 DevTools 拿到焦点时，<b>文档并没有焦点</b>
   * （{@code document.hasFocus()} 为假），点回页面只是<b>文档内部</b>的焦点转移，
   * 不改变"窗口有没有焦点" ⇒ 不派发 focus。这条路上补报<b>一次都不会发生</b>。
   * 它取决定用户怎么切回来（⌘+Tab 会触发 focus，从地址栏点回来不会）⇒ 看上去就是"有时"。
   *
   * <p>★所以补两个"用户确实在这个页面上"的信号：{@code pointerdown} 与 {@code keydown}。
   * <b>判据没有被放宽</b> —— {@code flushPendingRead} 拿到信号后仍然要过
   * {@code isLooking}（可见 <b>且</b> 有焦点）那一整套闸门，这里加的只是"<b>什么时候去看一眼</b>"。
   *
   * <p>★为什么这两个要用 capture：{@code pointerdown} 在冒泡阶段可能被某个组件的
   * {@code stopPropagation} 吃掉，而"用户点了一下"这件事本身与谁处理了它无关。
   * 用 {@code passive} 是因为我们只读不写、绝不 {@code preventDefault}。
   *
   * <p>★为什么要节流：补报虽然有幂等短路（见 store 的 {@code reportRead}），
   * 但真报一次仍然会发一条 WS 上行。用户连续点击时没必要每次都问一遍。
   * ★节流<b>只加在这两个高频来源上</b>：focus / visibilitychange 是低频且是主路径，
   * 被节流吞掉的话就退回"只赌一次"了（那正是这次要修的东西）。
   */
  useEffect(() => {
    const onLooking = () => useChatStore.getState().flushPendingRead();
    let lastUserActionAt = 0;
    const onUserAction = () => {
      const now = Date.now();
      if (now - lastUserActionAt < 500) return;
      lastUserActionAt = now;
      onLooking();
    };
    const opts = { capture: true, passive: true } as const;
    window.addEventListener('focus', onLooking);
    document.addEventListener('visibilitychange', onLooking);
    getMessageInputRoot().addEventListener('pointerdown', onUserAction, opts);
    getMessageInputRoot().addEventListener('keydown', onUserAction, opts);
    return () => {
      window.removeEventListener('focus', onLooking);
      document.removeEventListener('visibilitychange', onLooking);
      getMessageInputRoot().removeEventListener('pointerdown', onUserAction, opts);
      getMessageInputRoot().removeEventListener('keydown', onUserAction, opts);
    };
  }, []);

  /**
   * ★★DEV-382：**"环境变了"就补一次对账** —— 回到前台、恢复联网。
   *
   * <h2>它修的那个 bug（用户原话）</h2>
   * <p>「新消息有时要刷新页面才看得到，看看是不是有些状态没有处理好，
   * 比如断网重连有没有触发拉新消息、拉消息失败了有没有重试等」
   *
   * <h2>★★与上面那条 effect 的分工（不要合并）</h2>
   * <p>上面那条挂的也是 {@code focus} / {@code visibilitychange}，但它调的是
   * {@code flushPendingRead()}——<b>补的是"已读"</b>，与"消息"一个字的关系都没有。
   * ★改造前全前端<b>零处</b>监听 {@code online} / {@code offline}。
   *
   * <p>⇒ 于是"页面在后台时丢帧"这条最日常的路径上<b>没有任何人去补</b>：
   * WebSocket 不会丢帧（TCP 保证），但浏览器把后台标签页的连接与定时器节流之后，
   * 服务端<b>以为</b>推到了、客户端<b>没收到</b>，两边谁都不会报错 ——
   * 用户切回来看到的还是离开那一刻的那一页，只有刷新（走首屏那条不受此影响的路径）
   * 才能看到新的。这正是用户说的"<b>有时</b>"。
   *
   * <p>★两条 effect <b>刻意分开</b>：判据不同（那条是"用户有没有在看"，
   * 这条是"环境变没变"）、节流口径不同（那条只节流 pointerdown/keydown，
   * 这条对所有来源统一节流）、失败处理不同（那条是本地补报、不会失败；
   * 这条要发请求）。合成一条会让"什么时候该补什么"重新变成一团。
   *
   * <h2>★为什么用这两个事件</h2>
   * <ul>
   *   <li>{@code online}：{@code offline → online} 是<b>明确的缺口信号</b>
   *       —— 断线期间的消息一定没到。★它比 WS 自己的重连更早（网卡起来就派发），
   *       所以两者会各补一次；重复的那次由 store 里的节流窗口与
   *       {@code syncFlight} / {@code tailFlight} 两个 single-flight 合并掉；</li>
   *   <li>{@code visibilitychange → visible}：覆盖"网一直通、但页面被节流"
   *       —— 这一类<b>不</b>会触发 {@code online}（从浏览器的角度看网络从未中断），
   *       所以两个事件缺一不可。</li>
   * </ul>
   * ★{@code document.visibilityState !== 'visible'} 直接返回，而不是判
   * {@code === 'hidden'}：可见性取值不止这两个，凡是不是"用户正看着"的都不该补。
   *
   * <p>★判据（该不该补、多久算同一次）全在 store 与 {@code lib/resumeReconcile} 里，
   * 这里只负责"把两个信号接进来"。
   */
  useEffect(() => {
    const onResume = () => useChatStore.getState().reconcileOnResume();
    const onVisible = () => {
      if (document.visibilityState !== 'visible') return;
      onResume();
    };
    window.addEventListener('online', onResume);
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.removeEventListener('online', onResume);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, []);

  /**
   * ★★★DEV-389：**周期兜底对账** —— 会话"一直开着、什么都没发生"时的那一格。
   *
   * <h2>它补的是上面那条 effect 结构上盖不到的一格</h2>
   *
   * <p>上面那条（DEV-382）是<b>事件</b>驱动的：回到前台、恢复联网、WS 重连、
   * 切回会话 —— 每一个都要求"发生了一件事"。而 101 上真实丢帧的那一类是：
   *
   * <pre>
   * 落库成功 → 【扇出事件发送失败】→ 发送方仍收到 SEND ok → 对端一个帧都没收到
   * </pre>
   *
   * <p>接收端既没断线、也没切后台、也没被重连 ⇒ <b>上面那四个事件一个都不会派发</b>，
   * 页面就那么开着，那条消息永远不来（用户原话：「这条消息对方不刷新页面看不到」）。
   * 唯一的出路是他自己按 F5 —— 而 F5 走的是首屏那条路，所以"刷新就好了"。
   *
   * <h2>★为什么是"定时轮询"这种看起来最笨的做法</h2>
   *
   * <p>因为要对付的正是"<b>什么都没发生</b>"：任何"由某个信号触发"的方案都盖不到它
   * （这是我们刚花了一整轮排查才确认的事实，不是猜的）。
   * ★代价被压到很低：一次 tick 只发一条被水位线挡掉大半的 {@code /sync}
   * ＋最多一条当前会话的 {@code history}；且 45s 一次、页面不可见时不发、
   * WS 没连上时不发、正在飞的时候不叠发。
   *
   * <h2>★三条纪律（写错了都不会有任何报错，只会静默变差）</h2>
   * <ol>
   *   <li><b>与上面那条 effect 刻意分开</b>：判据不同（那条问"环境变没变"，
   *       这条问"轮到我了没有"）、时钟不同（两条各有各的 lastAtMs）、
   *       动作档位不同（这条是降级档，不重拉会话列表/通讯录）。合成一条会让
   *       "什么时候该补什么"重新变成一团；</li>
   *   <li><b>只调 {@code pollReconcile()}，不看返回值</b>：判据与记账全在 store 里
   *       （{@code lib/reconcilePoll} 是纯函数、有单测）。★本仓没有 jsdom/RTL，
   *       判据写在组件里在单测里<b>完全不可见</b>；</li>
   *   <li><b>必须清掉定时器</b>：这个组件会随登录态重挂载，
   *       漏了 {@code clearInterval} 就是"每登录一次多一个 45s 定时器"。</li>
   * </ol>
   *
   * <p>★间隔常量从 {@code lib/reconcilePoll} 取（不在这里写 45000）——
   * 那个文件里有它取 45s 而不是 30s/60s 的理由，以及"必须落在用户拍板的 30~60s 口径内"
   * 的单测。
   */
  useEffect(() => {
    const timer = window.setInterval(() => {
      useChatStore.getState().pollReconcile();
    }, RECONCILE_POLL_INTERVAL_MS);
    return () => {
      window.clearInterval(timer);
    };
  }, []);

  /**
   * ★★DEV-168：摘掉 {@code index.html} 里那块静态启动骨架。
   *
   * <p>★为什么是 {@code useLayoutEffect} 而不是 {@code useEffect}：
   * 它在 DOM 变更之后、浏览器<b>绘制之前</b>同步执行。
   * 本组件这次 commit 出来的就是真正的界面 —— 在这一刻摘掉遮罩，
   * 用户第一次看到的就是它，中间不存在"遮罩没了、React 还没画"的那一帧。
   * （骨架是 {@code position:fixed} 盖在 {@code #root} 之上的，所以即便顺序反了
   * 也只是"多挡一帧"，不会闪；用 layout effect 是为了少一层需要推理的东西。）
   *
   * <p>★{@code ?.remove()} 而不是先判存在：元素本来就可能不在
   * （开发态热更新、或将来某次改动删掉了 HTML 里那段），不该为此抛错。
   */
  useLayoutEffect(() => {
    getMessageElementById(BOOT_SKELETON_ID)?.remove();
  }, []);

  /**
   * ★★DEV-168：自动跳转的唯一执行点。
   *
   * <p>判据（该不该跳、跳到哪）在 {@code lib/authEntry.ts}（纯函数、可单测），
   * store 只把它落成 {@code authProbe + authRedirectTarget} 两个字段 ——
   * 真正碰 {@code location} 的只有这里一处。
   */
  const redirectedRef = useRef(false);
  useEffect(() => {
    // ★★带了会议邀请链接就【不跳登录页】：未登录的人要靠"填昵称入会"这条路进会议，
    //   被送去平台登录页等于把这条需求整个作废。
    if (inviteRoom) return;
    if (authProbe !== 'redirecting' || !authRedirectTarget) return;
    // ★★这道 ref 守卫是【必需】的，不是优化：main.tsx 用了 React.StrictMode，
    //   effect 在开发态会双执行 —— 没有它就会 replace 两次。
    //   它同时兜住了"同一目标因为别的字段变化而让 effect 重跑"的情况。
    if (redirectedRef.current) return;
    redirectedRef.current = true;
    // ★replace 而不是 assign：不留历史记录。
    //   否则用户按返回键会回到 IM，IM 又把他送去登录页 —— 一个用返回键就能重现的跳转循环。
    redirectMessageAuth(authRedirectTarget);
  }, [authProbe, authRedirectTarget, inviteRoom]);

  // HTTP 401 → client.ts 广播 im:auth-expired
  useEffect(() => {
    const onExpired = (e: Event) => {
      // ★走 store 的统一处置（清态 + 平台模式下决定 4010/4011 该跳去哪）
      // ★DEV-168：把载荷里的因由一并传下去 —— 4011 的 message 就是平台指定的登录地址，
      //   不带它的话，运行中会话过期的场景会退化成"显示登录卡片"，
      //   与首屏的自动跳转分裂成两种行为。
      handleAuthExpired(readAuthExpiredDetail(e));
      // ★已经决定要跳走时不要再弹提示：页面正在被替换，那条 toast 只会一闪而过，
      //   而它恰恰是本次要消灭的"闪"的一种。
      if (useChatStore.getState().authProbe === 'redirecting') return;
      message.warning(
        isPlatformMode ? '平台登录态已失效，请重新登录 agent-platform' : '登录状态已失效，请重新登录',
      );
    };
    window.addEventListener('im:auth-expired', onExpired);
    return () => window.removeEventListener('im:auth-expired', onExpired);
  }, [message, handleAuthExpired]);

  // KICK 提示（★too_many_devices / auth_expired 已由 ImSocket 停止自动重连）
  useEffect(() => {
    if (!kicked) return;
    const text =
      kicked.reason === KickReason.TOO_MANY_DEVICES
        ? '该账号已在过多窗口打开，请关闭部分窗口后重试'
        : kicked.reason === KickReason.AUTH_EXPIRED
          ? isPlatformMode
            ? '平台登录态已失效，请重新登录 agent-platform'
            : '登录状态已失效，请重新登录'
          : kicked.message ?? '连接已断开';
    message.warning(text);
    clearKicked();
  }, [kicked, clearKicked, message]);

  useEffect(() => {
    if (rejectMsg) message.error(`长连接握手失败：${rejectMsg}`);
  }, [rejectMsg, message]);

  /** ★已登录时的界面（顶栏 + 聊天页）。骨架态与真实态用的是<b>同一份</b>，见下。 */
  const chatShell = (
    <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {rejectMsg && <Alert type="error" banner closable message={`连接被拒绝：${rejectMsg}`} />}
      <ChatPage />
    </div>
  );

  /**
   * ★★一条邀请链接，三种走法（这是"登录用户和游客用同一个链接"的分派点）。
   *
   * <ol>
   *   <li><b>已登录</b> ⇒ 落到下面的 IM 客户端：{@code MeetingPane} 按 {@code ?meeting=}
   *       预填会议号；若是刚从平台登录页跳回来的，还会直接入会
   *       （见 {@code lib/meetingAutoJoin.ts}）。身份是账号，能带主持人/成员能力。</li>
   *   <li><b>未登录 + 会议开放游客</b> ⇒ {@link GuestMeetingPage}：填个昵称就进。</li>
   *   <li><b>未登录 + 会议不开放游客</b> ⇒ 同样先到 {@link GuestMeetingPage}，
   *       它查出 {@code guestAllowed=false} 后自动跳平台登录页并带上回跳地址。</li>
   * </ol>
   *
   * <p>★★<b>已登录的人不能再走访客页</b>：访客页没有账号身份、没有主持人能力，
   * 更糟的是会议没开放游客时他会看到"仅限登录用户"——明明是登录用户却被拒之门外。
   * 所以这里必须先等登录态探测落地，再决定给哪一页。
   *
   * <p>★放在"登录页 / 骨架"之前：未登录的人要靠"填昵称"或"跳登录再回来"进会议，
   * 任何一种"先显示 IM 登录卡片"的分支都会把这两条路吃掉。
   */
  if (inviteRoom) {
    // ★★判定必须把 userId 放在最前面：探测**成功后** store 会把 authProbe 置回
    //   `idle`（见 store/chat.ts#restoreSession），所以"idle"并不等于"还没结果"。
    //   先看 userId 才不会让已登录的人永远停在"正在确认登录状态…"（本段真实踩过）。
    if (!userId && isPlatformMode && (authProbe === 'idle' || authProbe === 'probing')) {
      return <InviteBooting room={inviteRoom} />;
    }
    if (!userId) return <GuestMeetingPage room={inviteRoom} />;
  }

  // ★★mock 模式：一行不改（登录页的 9001-9009 下拉必须原样保留，
  //   它是本地开发唯一的入口，行为与 DEV-168 无关）。
  if (!isPlatformMode) {
    return userId ? chatShell : <LoginPage />;
  }

  // ★★DEV-168：平台模式的渲染矩阵。★按顺序判，先命中先返回：
  //   ① 已登录 → 真实界面；
  //   ② 平台明确说了"未登录"或"平台不可用" → 登录页（复用既有组件，不新写"落地卡片"）；
  //   ③ 其余（idle / probing / redirecting）→ 骨架。
  if (userId) return chatShell;
  if (authProbe === 'unavailable' || authProbe === 'unauthenticated') return <LoginPage />;

  return (
    // ★★骨架直接复用 {@link ChatPage}，而不是另写一套占位 DOM：
    //   同一套 DOM/CSS（.conv-pane / .chat-pane）⇒ 数据回来时是"填进去"而不是"换一张皮"，
    //   这正是需求里"不要闪"的实现方式。★也省掉了"骨架的样式和真界面的样式是两份真相"
    //   这个必然漂移的问题。
    //
    //   ★class 名与 index.html 里那块静态骨架【同名同语义】（都是 .boot-skeleton）：
    //   一个盖住 bundle 加载期，一个盖住探测期，两者首尾相接 —— 用户在整段启动过程里
    //   看到的都是同一幅画面。
    //   ★aria-busy 让读屏软件知道这是加载态（否则用户会以为界面就是空的）。
    <div className="boot-skeleton" aria-busy="true">
      {chatShell}
    </div>
  );
}

export default function App() {
  return (
    <AntApp message={{ getContainer: getMessagePortalRoot }} notification={{ getContainer: getMessagePortalRoot }}>
      <Shell />
      {/*
        ★通话浮层挂在根节点、与登录态无关：它是全局唯一的"电话"，
        切会话、切标签都不该让它消失（见 components/CallOverlay.tsx 头注释）。
        ★未登录时它恒为 idle，渲染 null，不会挡住登录页。
      */}
      <CallOverlay />
      {/*
        ★★会议邀请的「来电页」（见 components/MeetingInviteOverlay.tsx）：
        与通话浮层并列挂在根节点 —— 收到会议邀请时不论用户在哪个会话，都要看得见。
        ★它自己管铃声；一旦进了通话/会议会自动收队（不会与通话铃声叠加）。
      */}
      <MeetingInviteOverlay />
      {/*
        ★★会中面板的"独立窗口"宿主（见 components/MeetingPopout.tsx）：
        本页这一个只管开/关窗口，窗口里那棵 React 树渲染的是 `<CallOverlay standalone />`。
        两棵树读同一份 store ⇒ 不需要任何跨窗口消息。
      */}
      <MeetingPopout />
    </AntApp>
  );
}
