import { useEffect, useState } from 'react';
import { App as AntApp, Button, Empty, Input, Modal, Spin, Typography } from 'antd';
import { convApi } from '../api';
import type { Id, JoinRequestDto } from '../api/types';
import { UNKNOWN_NAME, firstNameOf } from '../lib/displayName';
import { JOIN_REMARK_MAX_CHARS, joinRequestSummary } from '../lib/joinGroup';
import { dividerTime } from '../lib/timeDivider';
import { useChatStore } from '../store/chat';
import PanelCloseButton from './PanelCloseButton';

/** ★ID 比较统一 String 归一（雪花 ID > 2^53，见 api/json.ts）。 */
const sameId = (a: unknown, b: unknown): boolean => a != null && b != null && String(a) === String(b);

/**
 * 会话窗口顶部「入群申请」标签页（DEV-197-b）—— 群主 / 管理员的审核面板。
 *
 * <h2>★为什么是一个标签页而不是弹窗、也不是抽屉</h2>
 *
 * <p>① 它是<b>常驻的待办</b>，不是一次性的动作：管理员会反复回来看有没有新申请；
 * ② 挂进标签页体系后，「单聊里不出现」是<b>白拿的</b>（{@code groupOnly} 那条判据
 * 与「成员 / 群公告 / 群设置」共用一份），做成抽屉或独立页面就得在别处补一遍
 * "这不是群"的判断，而漏补的表现是单聊里出现一个永远空着的审核页。
 *
 * <h2>★★三条不由本组件决定、但界面必须如实体现的语义</h2>
 *
 * <ul>
 *   <li><b>列表只含 {@code pending}，且按 {@code createTime} <b>升序</b>（先来先审）。</b>
 *       ⇒ 这里<b>不重排、不排序</b>。★倒序的话压在最下面的申请永远没人看，
 *       所以"照服务端给的顺序渲染"本身就是产品需求。</li>
 *   <li><b>权限在服务端现算</b>：普通成员调列表接口报 {@code IM_30001}
 *       （申请表里有申请人写给管理员的附言，那不是给全体成员看的）。
 *       ⇒ 本组件<b>不</b>自己判断"我是不是管理员"，只把失败如实显示出来。
 *       前端复制一份权限口径，两份迟早分叉，而分叉的表现是"面板空着"与
 *       "面板报无权"两种说不出区别的空。</li>
 *   <li><b>审核是幂等的</b>：单子已是终态时服务端返回既有状态、不重复执行、仍 200。
 *       两个人同时审 ⇒ 后到的那次拿到的 {@code reviewerId} 不是我。
 *       ⇒ 界面据此说一句"已被他人处理"，而不是假装是我审的。</li>
 * </ul>
 *
 * <h2>★通过 / 拒绝两种动作的形态刻意不对称</h2>
 *
 * <p>「通过」<b>直接执行</b>（与互动卡片上那个按钮同一个口径）；
 * 「拒绝」<b>先弹一个输入理由的框</b> —— 理由会发给申请人
 * （{@code ReviewJoinRequest.reviewRemark}，见 {@code JoinRequestDto.reviewRemark}），
 * 而"不让你进来"这件事对申请人来说需要一句解释，让他能改了再来。
 * ★理由<b>可以留空</b>：强制填写会逼出一堆"无"和"。"。
 */
export default function ChatJoinRequestsPanel({
  convId,
  onClose,
}: {
  convId: Id | null;
  /** ★DEV-253：关掉这条侧栏（面板不知道"关掉我"是什么意思，见 PanelCloseButton）。 */
  onClose?: () => void;
}) {
  const userId = useChatStore((s) => s.userId);
  const { message: toast } = AntApp.useApp();

  /** 列表本体。{@code null} = 还没拉到（与"拉到了但是空"必须能区分）。 */
  const [list, setList] = useState<JoinRequestDto[] | null>(null);
  /** 拉取失败时的一句话。★有它就不再渲染 Empty —— 见下面 error 分支的注释。 */
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  /** 正在处理的那条（按 requestId）。只给那一行转圈，而不是整面板。 */
  const [busyId, setBusyId] = useState<string | null>(null);
  /** 拒绝理由弹框。{@code null} = 关着；否则是被拒的那条。 */
  const [rejecting, setRejecting] = useState<JoinRequestDto | null>(null);
  const [rejectReason, setRejectReason] = useState('');
  /**
   * ★「重试」计数器 —— 只用来**重新触发下面那个 effect**。
   *
   * <p>★为什么不把拉取逻辑抽成一个函数、让按钮直接调它：那样就有两条路径能改
   * {@code list/error/loading}，而其中一条（重试那条）必然会被漏掉某个 setState
   * —— 表现是"点了重试没反应"，且只有失败之后才看得见。加一个计数器，
   * 拉取逻辑**只有一处**，重试就只是"再来一次"。
   */
  const [tick, setTick] = useState(0);

  /**
   * 每次切会话（或点重试）重拉一次。
   *
   * <p>★不拿 {@code list === null} 当闸门（那是"本组件有没有拉过"）：审核状态是
   * <b>多人共享</b>的，别人刚通过了一条，本端手里那份就过期了，而长连接下行帧里
   * <b>没有</b>申请变更这一类。每次打开面板重拉是最便宜的正确做法（返回体 ≤100 条）。
   */
  useEffect(() => {
    if (convId == null) return undefined;
    let alive = true;
    setLoading(true);
    setError(null);
    // ★切会话先清空：留着上一个群的申请单会让人以为"这个群里也有人申请"。
    //   ★重试时也清空（此刻 list 已经被上一次失败置成 null 了，这里是幂等的）。
    setList(null);
    convApi
      .listJoinRequests(convId)
      .then((rows) => {
        if (alive) setList(Array.isArray(rows) ? rows : []);
      })
      .catch((e: unknown) => {
        // ★失败必须说话。静默的话面板会显示"没有待处理的入群申请"，
        //   而事实是"没拉到" —— 管理员据此以为没人申请，人就在外面干等。
        if (alive) setError((e as Error).message || '加载失败');
      })
      .finally(() => {
        // ★alive 闸门：切会话时旧请求的 finally 会晚于新请求的 setLoading(true) 到达，
        //   不挡的话新会话的转圈会被旧请求提前关掉（经典的竞态闪烁）。
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [convId, tick]);

  const review = async (req: JoinRequestDto, approve: boolean, remark?: string) => {
    if (convId == null || req.requestId == null) return;
    setBusyId(String(req.requestId));
    try {
      const saved = await convApi.reviewJoinRequest(convId, req.requestId, {
        approve,
        // ★空串与缺省等价：服务端按"有没有非空理由"处理，传空串只会多一个字段。
        ...(remark && remark.trim() ? { reviewRemark: remark.trim() } : {}),
      });
      // ★从列表里摘掉这一条，而不是整表重拉：单子已不再是 pending，
      //   本地摘除在任何并发情形下都是对的，且不会让整列闪一下。
      setList((prev) => (prev ?? []).filter((x) => !sameId(x.requestId, req.requestId)));
      if (saved?.reviewerId != null && userId != null && !sameId(saved.reviewerId, userId)) {
        // ★幂等接口的另一种真相：我点的时候别人已经审完了，服务端把**他的**结果返给我。
        //   不说这一句的话，管理员会以为自己那一票生效了（而实际生效的是别人的意见）。
        toast.warning('这条申请已被其他管理员处理，列表已按服务端结果更新');
      } else {
        toast.success(approve ? '已通过，对方已加入群聊' : '已拒绝');
      }
    } catch (e) {
      // ★原样展示服务端文案，**不要**在这里替它分类：
      //   群满 IM_20101 / 群已解散 IM_20105 时单子会**保持 pending**，
      //   所以下面不摘除这一条 —— 摘了就是"界面说处理完了，人却没进来"。
      toast.error(`${approve ? '通过' : '拒绝'}失败：${(e as Error).message}`);
    } finally {
      setBusyId(null);
    }
  };

  const rows = list ?? [];
  const title = `入群申请${rows.length > 0 ? ` · ${rows.length} 条待处理` : ''}`;

  return (
    <div className="chat-panel">
      <div className="chat-panel-head">
        {/* ★★DEV-254 需求②（用户原话「文件的侧边栏"x"的位置不对」）：
            这一段说明原来**写在标题里面**（`<span className="chat-panel-title">{title}
            <Typography.Text>按申请时间先后排列</Typography.Text></span>`）。
            标题因此长到 190px 左右，加上「×」就超过 320px 侧栏的可用宽 288px
            ⇒ head 折成两行、「×」掉到第二行 —— 与文件面板**同一个 bug 形态**，
            只是这里超宽的是文字、那里是筛选器。
            ★量具实测（未修复产物）：入群申请 head 高 **76.8**、标题 top 68 / × top 100.8。
            ★所以修法也同构：head 里**只留「标题 + ×」**，说明文字另起一行
            （`.chat-panel-note`，与文件面板的 `.chat-panel-filter` 共用同一条规则）。 */}
        <span className="chat-panel-title">{title}</span>
        {/* ★DEV-253：右缘那一组（这里只有关闭）。 */}
        <div className="chat-panel-head-end">
          {onClose && <PanelCloseButton onClose={onClose} panel="入群申请" />}
        </div>
      </div>

      {/* ★"升序"要写在界面上：管理员从别处（比如一张卡片）审完一条回来，
          最自然的预期是"新的在最上面"，而这里恰好相反。 */}
      <div className="chat-panel-note">
        <Typography.Text type="secondary" style={{ fontSize: 12, fontWeight: 400 }}>
          按申请时间先后排列
        </Typography.Text>
      </div>

      <div className="chat-panel-scroll">
        {loading && rows.length === 0 ? (
          // ★只在"还没有任何内容可显示"时占屏：已经有列表时刷新不该把它换成转圈。
          <div style={{ textAlign: 'center', marginTop: 64 }}>
            <Spin />
          </div>
        ) : error ? (
          // ★失败态**不能**退化成 Empty：Empty 说的是"就是没有"，
          //   而这里是"我不知道有没有"。两者的下一步动作完全不同（一个去干别的、
          //   一个该重试），所以必须长得不一样。
          <div className="chat-panel-hint" style={{ marginTop: 48, textAlign: 'center' }}>
            <Typography.Text type="danger">入群申请加载失败：{error}</Typography.Text>
            <div style={{ marginTop: 12 }}>
              <Button size="small" onClick={() => setTick((n) => n + 1)}>
                重试
              </Button>
            </div>
          </div>
        ) : rows.length === 0 ? (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            style={{ marginTop: 64 }}
            description={(
              // ★把"为什么可能是空的"一并说了：群设置里若开着「入群需审批」以外的那种
              //   直接放行（joinApprove=false），凭群号申请是**立即入群**、根本不会产生申请单
              //   ⇒ 这一页恒空。不说的话，管理员会以为审核坏了。
              <span>
                没有待处理的入群申请
                <br />
                <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                  若群里未开启「入群需审批」，凭群号申请会直接入群，不会产生申请单。
                </Typography.Text>
              </span>
            )}
          />
        ) : (
          <ul className="join-req-list">
            {rows.map((r) => {
              // ★★DEV-197-c：这一行混着两种来源（本人申请 / 成员邀请转成的申请），
              //   文案由纯函数按 source 算 —— 见 lib/joinGroup.ts 的 joinRequestSummary。
              //   ★名字栏两档都是"要被加进群的那个人"；邀请人写在动作栏里。
              const s = joinRequestSummary(r);
              return (
              <li className="join-req-item" key={String(r.requestId)}>
                <div className="join-req-main">
                  <div className="join-req-head">
                    {/* ★DEV-202 #218 起的名字口径：服务端下发的展示名，空则「未知用户」。
                        ★★不逐条去查资料（那是 N+1）：userName 是服务端批量补好的。 */}
                    <span className="join-req-name">{firstNameOf(UNKNOWN_NAME, s.name)}</span>
                    {/* ★★「申请加入」与「由 李四 邀请加入」必须分开：
                        邀请单写"某某申请加入"是在说谎（那人从没申请过），
                        而管理员对"谁主动"的判断会直接改变通过与否。
                        ★与卡片（服务端下发的 desc）用同一套口径，两处说法一致。 */}
                    <span className={`join-req-action${s.invited ? ' invited' : ''}`}>{s.action}</span>
                  </div>
                  <span className="join-req-time">{dividerTime(r.createTime)}</span>
                  {r.remark ? (
                    // ★附言是申请人写给管理员看的理由，≤64 字（服务端按**字符数**截，
                    //   不是字节数 —— 见 lib/joinGroup.ts 的 charCount 注释）。
                    //   原样显示、不截断：64 字本来就短，再截就看不出他想干什么了。
                    <span className="join-req-remark">{r.remark}</span>
                  ) : s.showRemarkHint ? (
                    // ★没有附言时**不渲染那一行空白**，但也不留悬念：
                    //   一句浅灰的「未填写附言」比什么都没有更容易读懂。
                    //   ★★邀请单**不显示这句**：它根本没有"填理由"这个环节，
                    //   写「未填写」等于暗示"这个人懒得写理由"。
                    <span className="join-req-remark empty">未填写附言</span>
                  ) : null}
                </div>
                <div className="join-req-actions">
                  <Button
                    size="small"
                    type="primary"
                    loading={busyId === String(r.requestId)}
                    // ★点击立即执行、不弹二次确认 —— 与互动卡片上的按钮同一个口径
                    //   （取舍见 InteractionCard 的类注释）。"通过"是可逆的（把人移出群），
                    //   而"不让你进来"才需要一句话解释，所以只有拒绝那一侧有输入框。
                    onClick={() => review(r, true).catch(() => undefined)}
                  >
                    通过
                  </Button>
                  <Button
                    size="small"
                    danger
                    disabled={busyId === String(r.requestId)}
                    onClick={() => {
                      setRejectReason('');
                      setRejecting(r);
                    }}
                  >
                    拒绝
                  </Button>
                </div>
              </li>
              );
            })}
          </ul>
        )}
      </div>

      <Modal
        open={rejecting != null}
        title="拒绝入群申请"
        okText="拒绝"
        cancelText="算了"
        okButtonProps={{ danger: true }}
        onCancel={() => setRejecting(null)}
        onOk={async () => {
          const target = rejecting;
          setRejecting(null);
          if (target) await review(target, false, rejectReason);
        }}
      >
        {/* ★理由发给**申请人**（见 JoinRequestDto.reviewRemark），所以这里说清收件人是谁 ——
            "审核备注"这种措辞会让人以为是写给自己的备忘。 */}
        <Typography.Paragraph type="secondary" style={{ fontSize: 12 }}>
          这一句会发给申请人，让他知道原因（可以留空）。
        </Typography.Paragraph>
        <Input.TextArea
          rows={3}
          value={rejectReason}
          onChange={(e) => setRejectReason(e.target.value)}
          // ★255 是服务端契约上限（ReviewJoinRequest.reviewRemark）；
          //   ★刻意**不**写 64：那是申请人附言的上限（JOIN_REMARK_MAX_CHARS），
          //   两者不是同一个数，混用会让管理员以为"理由也只能写 64 个字"。
          // ★★这里用 antd 的 maxLength + showCount 是**有意的**，与申请人那处
          //   （JoinGroupModal 刻意不用）不矛盾：antd 这两个都是按 UTF-16 码元数，
          //   恰好等于服务端 {@code normalizeReviewRemark} 的 {@code String.length()}
          //   —— 计数与截断同源，不会出现"两个计数器互相打架"。
          //   ★代价是超长粘贴会被静默截到 255（申请人那处为避免这个才不设 maxLength）；
          //   这里接受它：255 字已经远超"一句话拒绝理由"，被截掉的多半是粘贴事故。
          maxLength={255}
          showCount
          placeholder="例如：请先补充说明你要参与的项目"
        />
        {/* ★下面这句是给"申请人那条 64 字上限"留的对照锚点：卡片/面板上显示申请人附言时
            用的是 JOIN_REMARK_MAX_CHARS，两处不一样是刻意的。 */}
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          申请人附言上限为 {JOIN_REMARK_MAX_CHARS} 字。
        </Typography.Text>
      </Modal>
    </div>
  );
}
