/**
 * ★会中「播放音量」控件：一个喇叭按钮 + 自绘弹层滑杆。
 *
 * <h2>为什么自绘</h2>
 *
 * <p>会中界面会渲染进独立窗口（另一个 document），antd 的 cssinjs 只注入主文档 ——
 * 那边弹出的 Slider 会是一根没有轨道、没有提醒的原生控件。这里全部用项目自己的
 * CSS 类，两份宿主长得完全一样（与邀请 / 分享面板同一套约束）。
 *
 * <h2>★两个文档各有一个实例时，怎么保持一致</h2>
 *
 * <p>音量的存取在 {@code lib/meetingVolume}（模块级 + localStorage + 订阅），
 * 组件只订阅；一个窗口里拖动，另一个窗口跟着变。
 *
 * <h2>★★为什么弹层必须是 {@code position: fixed}（用户 2026-11-07 反馈"音量无法设置"）</h2>
 *
 * <p>弹层原来是相对按钮 {@code absolute; bottom: 100%} 往上弹。但会议底栏
 * {@code .meet-controls} 为了让 10 个控件在窄窗口里单行不折行，写了
 * {@code overflow-x: auto; overflow-y: hidden} —— 上弹的弹层整块落在滚动容器之外，
 * <b>被裁得只剩 4px</b>：用户看得见一条白边，点下去命中的却是下面的会议画面，
 * 滑杆根本拖不动。
 *
 * <p>改成 {@code fixed} 并用 JS 换算视口坐标，就跳出了这个滚动容器的裁切；
 * 与「摄像头菜单 / 布局菜单」同一套做法（{@code CallOverlay.placeCamMenu}）。
 * 坐标必须用<b>按钮所在文档</b>的 {@code getBoundingClientRect} 与
 * {@code ownerDocument.defaultView}：独立窗口里那是一个完全不同的 realm。
 */
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';

import { applyOutputVolume } from '../lib/meetingAudio';
import {
  getOutputVolume,
  setOutputVolume,
  subscribeOutputVolume,
  volumePercent,
} from '../lib/meetingVolume';
import { IconVolume } from './icons';

/** 弹层与视口边缘的最小留白；与 CSS 里的圆角 / 阴影观感配套。 */
const EDGE = 8;
/** 弹层与按钮的间距（原来 CSS 的 {@code calc(100% + 10px)}）。 */
const GAP = 10;

export default function MeetingVolumeControl() {
  const [volume, setVolume] = useState(() => getOutputVolume());
  const [open, setOpen] = useState(false);
  /** 弹层的视口坐标；null = 还没量（此时先不画，避免在左上角闪一下）。 */
  const [pos, setPos] = useState<{ left: number; top: number } | null>(null);
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const popRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => subscribeOutputVolume(setVolume), []);

  /**
   * ★点外面收起。不能用全局 {@code document}：独立窗口的那份实例的根
   * 在另一个 document 里，挂到全局 document 上的监听永远收不到那边的点击。
   */
  useEffect(() => {
    if (!open) return;
    const doc = wrapRef.current?.ownerDocument ?? document;
    const onDown = (e: Event) => {
      const root = wrapRef.current;
      if (!root) return;
      // ★跨 document 时 target 来自另一个 realm，`instanceof Node` 恒 false ——
      //   只用 contains 判断（同一 document 内一定成立）。
      const target = e.target as Node | null;
      if (target && root.contains(target)) return;
      setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    doc.addEventListener('mousedown', onDown, true);
    doc.addEventListener('keydown', onKey, true);
    return () => {
      doc.removeEventListener('mousedown', onDown, true);
      doc.removeEventListener('keydown', onKey, true);
    };
  }, [open]);

  /**
   * 按按钮当前的位置算弹层坐标：水平居中且夹在视口内，垂直优先向上弹
   * （按钮永远在页面最底部），上面真放不下才翻到下方。
   */
  const place = useCallback(() => {
    const root = wrapRef.current;
    const pop = popRef.current;
    if (!root || !pop) return;
    const win = root.ownerDocument.defaultView;
    if (!win) return;
    const btn = root.getBoundingClientRect();
    const w = pop.offsetWidth || 200;
    const h = pop.offsetHeight || 84;
    const centered = btn.left + btn.width / 2 - w / 2;
    const left = Math.min(Math.max(EDGE, centered), Math.max(EDGE, win.innerWidth - w - EDGE));
    let top = btn.top - GAP - h;
    if (top < EDGE) top = Math.max(EDGE, Math.min(btn.bottom + GAP, win.innerHeight - h - EDGE));
    setPos({ left, top });
  }, []);

  /**
   * ★每次打开都要重量：窗口可能被拖动、被拉伸（.call-window-large 有 resize 手柄），
   * 也可能在独立窗口里滚动过。尺寸或位置一变，fixed 坐标就过期了。
   */
  useLayoutEffect(() => {
    if (!open) {
      setPos(null);
      return;
    }
    place();
    const doc = wrapRef.current?.ownerDocument;
    const win = doc?.defaultView;
    win?.addEventListener('resize', place);
    doc?.addEventListener('scroll', place, true);
    return () => {
      win?.removeEventListener('resize', place);
      doc?.removeEventListener('scroll', place, true);
    };
  }, [open, place]);

  const pct = volumePercent(volume);

  const change = (next: number) => {
    const applied = setOutputVolume(next / 100);
    // 先落偏好再作用到音轨：两个窗口的订阅者与本地元素都拿到同一个值。
    applyOutputVolume(applied);
    setVolume(applied);
  };

  return (
    <div className="call-control meet-volume" ref={wrapRef}>
      <button
        type="button"
        className={`call-round${pct === 0 ? ' is-off' : ''}`}
        title={pct === 0 ? '播放音量：已静音（点击调整）' : `播放音量：${pct}%`}
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
      >
        <IconVolume size={19} />
      </button>
      <span className="call-control-label">{pct === 0 ? '无声音' : `音量 ${pct}%`}</span>

      {open && (
        <div
          ref={popRef}
          className="meet-volume-pop"
          role="dialog"
          aria-label="播放音量"
          style={
            pos
              ? { left: `${pos.left}px`, top: `${pos.top}px` }
              : { visibility: 'hidden' }
          }
        >
          <div className="meet-volume-head">
            <span>播放音量</span>
            <span className="meet-volume-num">{pct}%</span>
          </div>
          <input
            className="meet-volume-range"
            type="range"
            min={0}
            max={100}
            step={1}
            value={pct}
            aria-label="播放音量"
            onChange={(e) => change(Number(e.target.value))}
          />
          <div className="meet-volume-actions">
            <button type="button" className="meet-volume-link" onClick={() => change(0)}>
              静音
            </button>
            <button type="button" className="meet-volume-link" onClick={() => change(100)}>
              100%
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
