/**
 * ★文件列表左侧的类型徽标（2026-10-22 用户口径：
 * 「图标要对应上各个类型的文档」）。
 *
 * <p>改造前「文件」面板里除图片外**一律**是同一个灰色文档图标（{@code IconFile}），
 * docx / pdf / xlsx / pptx / md / zip 在列表里长得一模一样 —— 用户只能靠读文件名
 * 才分得出这是什么。现在按**后缀**给类别（决定颜色）与短标签（决定文字），
 * 例如 Word 蓝底 {@code DOCX}、Excel 绿底 {@code XLSX}、PDF 红底 {@code PDF}。
 *
 * <p>★判据放在纯函数里（零依赖、有单测），组件只负责把 {@link FileBadge}
 * 画成一块 40×40 的色块。这样"哪种后缀算什么"不会散落在 JSX 的条件里。
 */

/** 与 {@code lib/attachment.ts} 的 kind 对齐（本模块零依赖，故不复用那个类型）。 */
export type BadgeKind =
  | 'word'
  | 'excel'
  | 'ppt'
  | 'pdf'
  | 'markdown'
  | 'text'
  | 'code'
  | 'archive'
  | 'video'
  | 'audio'
  | 'image'
  | 'other';

export interface FileBadge {
  /** 决定底色（见 {@code styles.css} 的 `.file-thumb-*`）。 */
  kind: BadgeKind;
  /** 色块里的短标签；空串表示由组件改画图标（视频/语音/图片）。 */
  label: string;
}

const WORD_EXT = new Set(['doc', 'docx', 'dot', 'dotx', 'rtf', 'odt']);
const EXCEL_EXT = new Set(['xls', 'xlsx', 'xlsm', 'xlsb', 'csv', 'ods']);
const PPT_EXT = new Set(['ppt', 'pptx', 'pps', 'ppsx', 'pot', 'potx', 'odp']);
const MARKDOWN_EXT = new Set(['md', 'markdown', 'mdx']);
const TEXT_EXT = new Set(['txt', 'text', 'log']);
const CODE_EXT = new Set([
  'json', 'xml', 'yaml', 'yml', 'toml', 'ini', 'conf', 'cfg', 'properties', 'sql',
  'js', 'ts', 'tsx', 'jsx', 'java', 'py', 'go', 'rs', 'c', 'h', 'cpp', 'hpp',
  'css', 'scss', 'less', 'sh', 'bash', 'zsh', 'html', 'htm', 'vue',
]);
const ARCHIVE_EXT = new Set(['zip', 'rar', '7z', 'tar', 'gz', 'tgz', 'bz2', 'xz']);

/** 后缀（小写、无点）；没有点 / 点在开头或结尾时返回空串。 */
function extOf(name: string): string {
  const lower = (name ?? '').trim().toLowerCase();
  const dot = lower.lastIndexOf('.');
  if (dot <= 0 || dot === lower.length - 1) return '';
  return lower.slice(dot + 1);
}

/** 标签最多 4 个字符：40px 的色块里再长就会挤成一团（`PROPERTIES` → `PROP`）。 */
function shortLabel(ext: string): string {
  return ext.slice(0, 4).toUpperCase();
}

/**
 * ★一个附件在列表里该显示成哪种徽标。
 *
 * <p>顺序：先看 {@code kind}（图片/视频/语音由发送端定档，后缀不可靠），
 * 再按后缀归类，认不出来的一律 {@code other}（标签仍尽量给真实后缀，
 * 而不是一个骗人的通用名）。
 */
export function fileBadgeOf(kind: string, fileName: string): FileBadge {
  if (kind === 'image') return { kind: 'image', label: '' };
  if (kind === 'video') return { kind: 'video', label: '' };
  if (kind === 'audio') return { kind: 'audio', label: '' };

  const ext = extOf(fileName);
  if (!ext) return { kind: 'other', label: 'FILE' };
  if (WORD_EXT.has(ext)) return { kind: 'word', label: shortLabel(ext) };
  if (EXCEL_EXT.has(ext)) return { kind: 'excel', label: shortLabel(ext) };
  if (PPT_EXT.has(ext)) return { kind: 'ppt', label: shortLabel(ext) };
  if (ext === 'pdf') return { kind: 'pdf', label: 'PDF' };
  if (MARKDOWN_EXT.has(ext)) return { kind: 'markdown', label: shortLabel(ext) };
  if (TEXT_EXT.has(ext)) return { kind: 'text', label: shortLabel(ext) };
  if (CODE_EXT.has(ext)) return { kind: 'code', label: shortLabel(ext) };
  if (ARCHIVE_EXT.has(ext)) return { kind: 'archive', label: shortLabel(ext) };
  return { kind: 'other', label: shortLabel(ext) };
}
