/**
 * ★左栏第三个 Tab —— 「会议」栏。
 *
 * <h2>结构（与飞书对齐）</h2>
 *
 * <pre>
 * ┌──────────────────────────┐
 * │  [发起]   [加入]   [预约]  │  ← 三个平铺操作
 * │  我的预约（有才显示）        │
 * │  历史记录          [刷新]   │
 * │  · 张三与李四的通话  10月8日 │
 * │  · 周会            10月7日 │
 * └──────────────────────────┘
 * </pre>
 *
 * <h2>★★"发起 / 加入"都进同一条房间路径</h2>
 *
 * <p>它们最终都调 {@code useCallStore} 的 {@code startRoomMeeting} / {@code joinRoomMeeting}，
 * 差别只在**要不要先建房**（见 {@code store/call.ts} 里 {@code enterRoom} 的注释）。
 * 于是会中的浮层、录音、屏幕共享、视频开关全部复用现成的那一套，这里<b>不复制</b>任何通话逻辑。
 *
 * <h2>★历史记录是"我参与过"，不是"我发起的"</h2>
 *
 * <p>数据来自 {@code GET /api/instant-message/meetings}（服务端按参会人判定权限），
 * 被叫方也能看到 —— 与聊天流里那条「通话已结束」系统消息是同一份数据。
 * 点一条打开<b>页面内</b>的会议详情弹框（含录音下载，见 {@code lib/meetingDetailDialog}）。
 *
 * <h2>★★预约只在本机</h2>
 *
 * <p>服务端没有"预约"实体（见 {@code lib/meetingSchedule.ts} 的文件头），
 * 所以预约落 {@code localStorage}，卡片上如实写「仅本机可见」。
 * 点「开始」时才真正 {@code createRoom} —— 预约不等于房间已存在。
 *
 * <h2>★★预约里的"会议号 / 分享链接 / 拉人"</h2>
 *
 * <p>会议号在<b>打开预约弹窗时</b>就生成（与"发起"同一个号段、同一个来源），
 * 保存后卡片上显示它，主持人点「开始」时用的也是它 —— 提前发出去的链接才不会指向另一个房间。
 *
 * <p>"拉人"= 从我的联系人里多选，保存后给每人发一条聊天消息（会议号 + 时间 + 邀请链接）。
 * ★本仓没有日历邀请实体，聊天消息是最接近的等价物；只存一份名单在本地的话，
 * 被邀请的人<b>根本不知道</b>有这场会。
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { App as AntApp, Button, Input, Modal, Spin, Switch } from 'antd';

import { meetingRecordApi } from '../api';
import type { MeetingRecordView } from '../api/types';
import { copyText } from '../lib/clipboard';
import { contactTitle } from '../lib/contact';
import { meetingDurationText, meetingMetaText, meetingTimeText, recordBadge } from '../lib/meetingRecord';
import { consumeAutoJoin } from '../lib/meetingAutoJoin';
import {
  buildInviteUrl,
  buildMeetingInviteText,
  defaultMeetingTitle,
  formatMeetingId,
  meetingDisplayTitle,
  makeShareSlug,
  readInviteNo,
  shareKeyOf,
} from '../lib/meetingLink';
import {
  MAX_INVITEES,
  formatScheduleTime,
  makeMeetingNo,
  normalizeMeetingNo,
  scheduleInviteText,
  type ScheduleInvitee,
} from '../lib/meetingSchedule';
import { openMeetingDetail } from '../lib/meetingDetailDialog';
import { subscribeMeetingRecordDeleted } from '../lib/meetingRecordEvents';
import { primeMeetingWindow } from '../lib/meetingWindow';
import { useCallStore } from '../store/call';
import { useChatStore } from '../store/chat';
import { inviteContactsToMeeting } from '../store/meetingInvite';
import UserSearchSelect from './UserSearchSelect';
import { IconJoinRequestSolid, IconRefresh, IconTrash, IconVideo, IconClock } from './icons';

/** 每页条数。★与后端 {@code USER_SCAN_MAX=100} 之内，别写 200（会被静默截断）。 */
const PAGE_SIZE = 30;

/** ★服务端 404（会议模块未启用）要给一句人话，而不是把 HTTP 状态甩给用户。 */
function humanError(e: unknown): string {
  const msg = e instanceof Error ? e.message : typeof e === 'string' ? e : '网络异常';
  if (/404|not found/i.test(msg)) return '会议功能未开启';
  return msg;
}

type MediaType = 'audio' | 'video';
type Dialog = 'start' | 'join' | 'schedule' | null;

export default function MeetingPane() {
  const { message: toast, modal } = AntApp.useApp();
  const startRoomMeeting = useCallStore((s) => s.startRoomMeeting);
  const joinRoomMeeting = useCallStore((s) => s.joinRoomMeeting);
  const callPhase = useCallStore((s) => s.phase);
  const setPopout = useCallStore((s) => s.setPopout);
  /** ★预约里"拉人"的候选与排除项（不能把自己拉进会议邀请）。 */
  const myUserId = useChatStore((s) => s.userId);
  const contacts = useChatStore((s) => s.contacts);
  /** ★邀请文案第一行的"某某邀请你" —— 用当前账号昵称；拿不到时整句退化成"邀请你加入"。 */
  const myName = useChatStore((s) => s.userName);

  // ---------------------------------------------------------------- 历史记录
  const [items, setItems] = useState<MeetingRecordView[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const list = await meetingRecordApi.list({ limit: PAGE_SIZE });
      // ★★服务端正常返回数组，这里防的是"网关/代理返回 data:null"这类半坏响应：
      //   一次 null 会让下面的 `items.length` 在**渲染期**抛出，整页白屏 ——
      //   那不是"列表为空"，而是整个会议栏（含三个操作按钮）都没了。
      setItems(Array.isArray(list) ? list : []);
    } catch (e) {
      setItems([]);
      setError(humanError(e));
    } finally {
      setLoading(false);
    }
  }, []);

  // ★切到这个 Tab 才挂载 ⇒ 首屏拉一次；切走就卸载，不做后台轮询。
  useEffect(() => {
    void load();
  }, [load]);

  /**
   * ★会议结束后自动刷新历史。
   *
   * <p>会议记录是**服务端**在录音生命周期里写的（停止 → egress 传 S3 → 收尾落库），
   * 所以刚离开会议时未必立刻出现；这里只在回到 idle 时拉一次，
   * 剩下的交给用户点「刷新」—— 反复轮询会把一个低频动作变成常态流量。
   */
  useEffect(() => {
    if (callPhase === 'idle') void load();
  }, [callPhase, load]);

  /**
   * ★★删除成功后立刻重拉列表（用户 2026-11-08：「会议记录删除以后历史记录列表没有刷新」）。
   *
   * <p>走全局广播而不是"打开详情时把 load 传进去"：详情弹框还能从系统消息打开，
   * 靠回调只能覆盖一条入口，漏掉的那条就会留下"删了但还在"的一行。
   */
  useEffect(() => subscribeMeetingRecordDeleted(() => void load()), [load]);

  // ---------------------------------------------------------------- 弹窗
  const [dialog, setDialog] = useState<Dialog>(null);
  /**
   * ★★会议类型固定为「语音」，用户不再选（产品口径：进来之后想开画面就点「开视频」）。
   *
   * <p>摄像头按钮在会中<b>常驻</b>（见 CallOverlay 的 call-controls），语音入会的人
   * 随时能开、也能关；所以"语音会议"不是一种受限的会议，只是<b>默认不开摄像头</b>
   * —— 少一个必选项，也少一次"选错类型 → 对方看不到我"的困惑。
   *
   * <p>★保留这个 state 而不是到处写字面量：预约记录里存着 {@code mediaType} 字段
   * （历史数据可能是 video），统一走这里可以保证新旧预约都以语音开局。
   */
  const [mediaType] = useState<MediaType>('audio');
  const [title, setTitle] = useState('');
  const [joinNo, setJoinNo] = useState('');
  const [startAtText, setStartAtText] = useState('');
  /** ★发起/预约时展示的会议号：打开弹窗时生成一次，用户能看到要告诉别人哪个号。 */
  const [newNo, setNewNo] = useState('');
  /**
   * ★★与新会议号配套的分享 slug（12 位，不可枚举）。
   *
   * <p>为什么弹窗里就要有：这个弹窗在<b>建房之前</b>就允许「复制邀请」，
   * 那时还没有 room metadata 可读。先生成一个随建房/预约请求带给服务端，
   * 服务端沿用 —— 链接从第一刻起就不含 9 位数字。
   */
  const [newShareSlug, setNewShareSlug] = useState('');
  /** ★预约时从联系人里选的人（按 userId；名字在保存时从 {@code store.contacts} 取快照）。 */
  const [inviteeIds, setInviteeIds] = useState<string[]>([]);
  /**
   * ★★「发起会议」时从联系人里选的人 —— 会后立刻收到<b>来电式入会通知</b>。
   *
   * <p>与预约的 {@link inviteeIds} <b>刻意分开</b>：预约存的是"到点再说"，发起存的是
   * "现在就进"。共用一个 state 会让"上次预约选的人"悄悄出现在"发起"里并立刻被邀请 ——
   * 那是用户没做过的操作。
   */
  const [startInviteeIds, setStartInviteeIds] = useState<string[]>([]);
  /**
   * ★★是否允许游客（不登录、凭邀请链接填昵称）加入。<b>默认关闭</b>。
   *
   * <p>会议默认只对组织内有账号的人开放：把一条"谁拿到链接谁就能进"的地址
   * 默认发出去，风险大于便利。要给外部人开会，主持人得在这里显式打开。
   * 真正的判据在服务端房间元数据上，这里只是发起时的输入。
   */
  const [allowGuest, setAllowGuest] = useState(false);

  /**
   * ★★邀请链接（`?meeting=…`）由 App 在"已登录"时才放到这里。
   *
   * <p>两条路：
   * <ul>
   *   <li><b>刚刚从平台登录页跳回来</b>（{@code consumeAutoJoin} 命中）⇒ <b>直接入会</b>：
   *       用户是点邀请进来的，登录已经打断了两次，不该再让他点第三次；</li>
   *   <li><b>本来就登录着</b> ⇒ 打开「加入」弹窗并预填会议号（保留一次确认）。</li>
   * </ul>
   *
   * <p>★为什么必须抹掉地址栏里的参数：不抹的话刷新一次又弹一次，
   * 用户会以为"关不掉"；从历史里后退回来时也会再弹。
   * ★用 `replaceState` 而不是 `pushState`：这是"清理垃圾"不是"新的一步"，
   * 不该在浏览器后退栈里留下一条。
   * ★抹参数放在最前面：无论后面走哪条路，地址栏都必须先干净。
   */
  const inviteHandled = useRef(false);
  useEffect(() => {
    // ★StrictMode 下 effect 会双执行；同一场邀请只处理一次
    if (inviteHandled.current) return;
    const no = readInviteNo(window.location.search);
    if (!no) return;
    inviteHandled.current = true;
    setJoinNo(no);
    const url = new URL(window.location.href);
    url.searchParams.delete('meeting');
    window.history.replaceState(null, '', `${url.pathname}${url.search}${url.hash}`);

    // ★登录回跳：直接进会。没有用户手势，所以不开独立窗口（会被弹窗拦截），
    //   会中仍有「在新窗口中打开」可点。
    const auto = consumeAutoJoin(no);
    if (auto && useCallStore.getState().phase === 'idle') {
      void joinRoomMeeting(no, mediaType);
      return;
    }
    setDialog('join');
  }, [joinRoomMeeting, mediaType]);

  /**
   * ★★已经在通话/会议里时，再点「发起 / 加入 / 开始」**必须说话**。
   *
   * <p>{@code enterRoom} 在非 idle 阶段是直接 return 的（不能把正在进行的通话顶掉），
   * 于是用户点下去"什么都没发生" —— 看起来就像"这个按钮根本没实现"。
   * 这里提前拦一句，把"为什么没进去"说出来。
   */
  const guardBusy = useCallback((): boolean => {
    if (callPhase === 'idle') return false;
    toast.error('你正在通话或会议中，请先结束后再操作');
    return true;
  }, [callPhase, toast]);

  /**
   * ★★复制「邀请信息」——一条链接 + 飞书同款的四行说明。
   *
   * <p>★为什么复制整段而不是只复制 URL：收到的人第一眼要能判断
   * "谁邀请我、这是什么会、会议号是多少"。只发一个裸链接时，对方往往先回一句
   * "这是什么"才点开。会议号按 3-3-3 分组展示（{@code formatMeetingId}），
   * 但链接里仍是连续的 9 位数字。
   *
   * <p>★★链接只有一条：登录用户点开直接入会；没登录的人，会议开放游客就填昵称，
   * 没开放就被送去登录、登录成功后自动回来。文案里不再区分"游客链接/登录链接"。
   */
  const copyInvite = useCallback(
    (roomName: string, meetingTitle: string, shareSlug?: string | null) => {
      // ★★链接里放 slug（有的话），会议号只用于文案里的「会议 ID」展示。
      //   老记录没有 slug ⇒ 回退会议号，老链接继续能进（服务端两种值都认）。
      const link = buildInviteUrl(window.location.href, shareKeyOf(shareSlug, roomName));
      if (!link) return;
      const text = buildMeetingInviteText({
        inviter: myName,
        title: meetingTitle,
        roomName,
        url: link,
      });
      void copyText(text).then((ok) => {
        if (ok) toast.success('邀请信息已复制，粘贴到聊天里即可');
        else toast.info(`邀请链接：${link}`);
      });
    },
    [myName, toast],
  );

  /**
   * ★换一组「会议号 + 分享 slug」。
   *
   * <p>两者必须<b>一起</b>换：只换号会让弹窗里显示的号与链接里的 slug 指向
   * 服务端两条不同的键（slug 才是真正建出来的那间房），用户念的号就进不去。
   */
  const rollNewNo = useCallback(() => {
    setNewNo(makeMeetingNo(Math.floor(Math.random() * 10 ** 9)));
    setNewShareSlug(makeShareSlug());
  }, []);

  const openStart = useCallback(() => {
    setTitle('');
    // ★每次打开都回到默认值：上一次取消勾选不该悄悄带到下一场会
    setAllowGuest(false);
    setStartInviteeIds([]);
    rollNewNo();
    setDialog('start');
  }, [rollNewNo]);

  const openJoin = useCallback(() => {
    setJoinNo('');
    setDialog('join');
  }, []);

  const openSchedule = useCallback(() => {
    setTitle('');
    setInviteeIds([]);
    setAllowGuest(false);
    // ★会议号在**打开弹窗时**就生成：预约卡片上的号、"复制邀请"里的链接
    //   必须是同一个号，保存时再生成会让用户刚才复制走的那条链接指向另一个房间。
    //   ★分享 slug 同理（它才是链接里真正带的值）。
    rollNewNo();
    // 默认给"下一个整点"：绝大多数预约都不是"现在就开始"
    const d = new Date(Date.now() + 60 * 60 * 1000);
    d.setMinutes(0, 0, 0);
    setStartAtText(toLocalInput(d.getTime()));
    setDialog('schedule');
  }, [rollNewNo]);

  const closeDialog = useCallback(() => setDialog(null), []);

  /**
   * ★★把「刚点下去的这场会」直接开进独立窗口。
   *
   * <h3>为什么必须紧跟在这一下点击里</h3>
   *
   * <p>{@code window.open} 需要<b>用户手势</b>。等到会中（{@code phase === 'active'}）再开，
   * 中间已经过了"建房 → 签令牌 → 连 LiveKit"三串 {@code await}，手势过期，
   * Chrome 直接按弹窗拦截 ⇒ 用户每次都要再手动点一次「在新窗口中打开」。
   * 所以这里在同一个点击任务里先开窗，{@code MeetingPopout} 随后接手渲染。
   *
   * <p>★只在 {@code phase} 真的变成 {@code connecting} 时才开：被"你正在通话中"挡住、
   * 或者没登录时 {@code enterRoom} 是直接 return 的，那种情况下开一个窗口纯属捣乱。
   */
  const openRoomWindow = useCallback(
    (title: string) => {
      if (useCallStore.getState().phase !== 'connecting') return;
      // ★被拦下就不置 popout：会议照常在本页开，会中还有「在新窗口中打开」可点
      if (!primeMeetingWindow(title)) return;
      setPopout(true);
    },
    [setPopout],
  );

  /**
   * ★★把「立即入会」的邀请发给选中的联系人（来电式通知，不是文字）。
   *
   * <p>★必须等建房成功（{@code phase === 'active'}）再发：房间没建起来就发邀请，
   * 对方点「加入」只会得到"会议不存在或已结束"—— 比不发更像故障。
   * ★发送本身在后台跑（用户已经进了会），失败只在 toast 里点名，不打断会议。
   */
  const notifyMeetingInvitees = useCallback(
    async (
      started: Promise<void>,
      meeting: { roomName: string; title: string },
      contactsToInvite: { userId: string; name: string }[],
    ) => {
      try {
        await started;
      } catch {
        return;
      }
      // ★建房/入会失败（号非法、服务未开启…）就不发了：邀请一个不存在的会议是假承诺
      if (useCallStore.getState().phase !== 'active') return;
      const { ok, failed } = await inviteContactsToMeeting({
        roomName: meeting.roomName,
        title: meeting.title,
        mediaType,
        contacts: contactsToInvite,
      });
      if (failed.length === 0) {
        toast.success(`已邀请 ${ok} 位联系人入会`);
      } else {
        toast.warning(
          ok > 0
            ? `已邀请 ${ok} 人，${failed.length} 人没发出去（${failed.slice(0, 3).join('、')}）`
            : `邀请没发出去：${failed.slice(0, 3).join('、')}`,
        );
      }
    },
    [mediaType, toast],
  );

  const doStart = useCallback(() => {
    if (!newNo) return;
    if (guardBusy()) return;
    setDialog(null);
    // ★从联系人里选的人：在**这一刻**取名字快照（联系人可能随后被改备注）
    const chosen = startInviteeIds.slice(0, MAX_INVITEES).map((id) => {
      const c = contacts.find((x) => String(x.userId) === id);
      return { userId: id, name: c ? contactTitle(c) : '' };
    });
    const meetingTitle = title.trim();
    // ★建会期间浮层自己会显示「正在创建会议…」，这里不需要额外 loading
    // ★把弹窗里那枚 slug 一起带下去：服务端写进 room metadata + 会议记录，
    //   与刚才「复制邀请」用的值必须是同一个。
    const started = startRoomMeeting(mediaType, newNo, meetingTitle, allowGuest, newShareSlug);
    // ★★必须紧跟在这一下点击里：异步之后 window.open 会丢用户手势、被弹窗拦截
    openRoomWindow(meetingTitle || defaultMeetingTitle(newNo));
    // ★邀请在建会成功之后才发（见 notifyMeetingInvitees 的注释）
    if (chosen.length > 0) {
      void notifyMeetingInvitees(
        started,
        { roomName: newNo, title: meetingTitle || defaultMeetingTitle(newNo) },
        chosen,
      );
    }
  }, [
    newNo,
    newShareSlug,
    mediaType,
    title,
    allowGuest,
    startInviteeIds,
    contacts,
    startRoomMeeting,
    guardBusy,
    openRoomWindow,
    notifyMeetingInvitees,
  ]);

  const doJoin = useCallback(() => {
    const room = normalizeMeetingNo(joinNo);
    if (!room) {
      toast.error('会议号格式不对，请核对后重试');
      return;
    }
    if (guardBusy()) return;
    setDialog(null);
    void joinRoomMeeting(room, mediaType);
    // 同上：凭号入会也直接开到独立窗口里
    openRoomWindow(defaultMeetingTitle(room));
  }, [joinNo, mediaType, joinRoomMeeting, toast, guardBusy, openRoomWindow]);

  /**
   * ★★把邀请**真正发出去**：给每个受邀人开一条单聊，发一条带会议号与链接的文字。
   *
   * <h3>为什么是发消息，而不是只把名字存下来</h3>
   *
   * <p>"拉人"在飞书里是发日历邀请；本仓没有日历实体（服务端没有预约接口，见
   * {@code lib/meetingSchedule.ts} 的文件头），最接近的等价物就是<b>一条聊天消息</b>：
   * 对方能收到、能点开、链接会把会议号填好。只把名字存在我这台浏览器里的话，
   * 被邀请的人<b>什么都不知道</b> —— 那不是"拉人"，只是一份私人名单。
   *
   * <h3>★逐个人发、失败只计数不中断</h3>
   *
   * <p>某个人因为权限/网络发不出去，不该让后面的人全都收不到；
   * 也不该把整条预约判失败（预约本身是本机的，已经存下了）。
   * 所以这里累计成功/失败，最后用一句话告诉用户"谁没通知到"。
   */
  const notifyInvitees = useCallback(
    async (
      meeting: { roomName: string; title: string; startAt: number; shareSlug?: string | null },
      invitees: ScheduleInvitee[],
    ) => {
      const link = buildInviteUrl(
        window.location.href,
        shareKeyOf(meeting.shareSlug, meeting.roomName),
      );
      // ★复用同一个文案函数：预约卡片、聊天消息、会议信息面板里的说法必须一致
      const text = scheduleInviteText(
        {
          id: '',
          title: meeting.title,
          startAt: meeting.startAt,
          roomName: meeting.roomName,
          mediaType: 'audio',
          invitees,
        },
        link,
        Date.now(),
      );
      let ok = 0;
      const failed: string[] = [];
      for (const p of invitees) {
        try {
          // ★服务端 createP2p 幂等：已经有单聊的会直接返回那一条，不会造出第二条会话
          const convId = await useChatStore.getState().createP2p(p.userId);
          await useChatStore.getState().sendText(convId, text);
          ok += 1;
        } catch {
          failed.push(p.name || '一位联系人');
        }
      }
      if (failed.length === 0) {
        toast.success(`已通知 ${ok} 位参会人`);
      } else {
        toast.warning(
          ok > 0
            ? `已通知 ${ok} 人，${failed.length} 人没发出去（${failed.slice(0, 3).join('、')}）`
            : `邀请没发出去：${failed.slice(0, 3).join('、')}`,
        );
      }
    },
    [toast],
  );

  const [scheduling, setScheduling] = useState(false);
  const doSchedule = useCallback(async () => {
    const ts = fromLocalInput(startAtText);
    if (ts == null) {
      toast.error('请选择开始时间');
      return;
    }
    if (ts < Date.now() - 60_000) {
      toast.error('开始时间已经过去了');
      return;
    }
    if (scheduling) return;
    // ★名字在**保存这一刻**从联系人里取快照：之后改名/删好友都不影响这张卡片，
    //   也不会因为联系人还没加载完就把人显示成空字符串。
    const invitees: ScheduleInvitee[] = inviteeIds.slice(0, MAX_INVITEES).map((id) => {
      const c = contacts.find((x) => String(x.userId) === id);
      return { userId: id, name: c ? contactTitle(c) : '' };
    });
    setScheduling(true);
    try {
      // ★★预约落服务端（im_meeting, status=0）：换设备/多端登录都能看到同一条。
      //   ★会议号必须把弹窗里显示的那个号带上：用户刚才「复制邀请」拿到的链接、
      //   以及发给联系人的邀请消息用的都是它，服务端另起一个号会让这些链接全部失效。
      const created = await meetingRecordApi.schedule({
        title: title.trim() || undefined,
        roomName: newNo,
        startAt: toServerTime(ts),
        meetingType: mediaType === 'audio' ? 1 : 2,
        allowGuest,
        inviteeUserIds: invitees.map((i) => i.userId),
        // ★与弹窗里「复制邀请」用的是同一个 slug：服务端另生成一个会让那条链接立刻失效。
        shareSlug: newShareSlug,
      });
      setDialog(null);
      await load();
      toast.success(
        invitees.length > 0
          ? `已预约，正在通知 ${invitees.length} 人`
          : '预约已保存，其他设备也能看到',
      );
      if (invitees.length > 0) {
        void notifyInvitees(
          {
            roomName: created.roomName || newNo,
            title: title.trim(),
            startAt: ts,
            // ★用服务端落库后的 slug（客户端给的那个会被沿用，但以返回值为准）
            shareSlug: created.shareSlug,
          },
          invitees,
        );
      }
    } catch (e) {
      toast.error(`预约失败：${humanError(e)}`);
    } finally {
      setScheduling(false);
    }
  }, [
    startAtText,
    scheduling,
    inviteeIds,
    contacts,
    title,
    mediaType,
    allowGuest,
    load,
    toast,
    notifyInvitees,
    newNo,
    newShareSlug,
  ]);

  /** ★取消预约（仅主持人、仅未开始）：服务端把 status 置成 3。 */
  const cancelSchedule = useCallback(
    (m: MeetingRecordView) => {
      modal.confirm({
        title: '取消这场预约？',
        content: '取消后所有人都会收到通知，记录会标记为「已取消」。',
        okText: '取消预约',
        okButtonProps: { danger: true },
        cancelText: '先留着',
        onOk: async () => {
          try {
            await meetingRecordApi.cancelSchedule(m.id);
            await load();
            toast.success('预约已取消');
          } catch (e) {
            toast.error(`取消失败：${humanError(e)}`);
          }
        },
      });
    },
    [load, modal, toast],
  );

  /**
   * ★删除会议记录（需求 8：「实际上删除的是用户的关系」）。
   *
   * <p>主持人删的是会议本身（所有人都不再看到），其他人只删掉自己与这条记录的关系；
   * 进行中的会议服务端会拒绝 —— 先结束会议。
   */
  // ---------------------------------------------------------------- 渲染
  /**
   * ★删除入口已经搬到「会议详情」里（用户 2026-11-07 原话：「会议删除按钮别放在列表上，
   * 本身列表就比较窄」）—— 列表项只剩"点开看详情"一个动作，不会被误触删掉记录。
   * 实际删除在「会议详情」弹框里（用户 2026-11-07 最终口径：页面内弹框，见 lib/meetingDetailDialog）。
   */
  /**
   * ★按 status 分组（口径与服务端一致）：0=未开始（预约） 1=进行中 2=已结束 3=已取消。
   *
   * <p>★"进行中"必须单独成一段：需求就是"用户能在会议记录里看到进行中的会议，
   * 并在没入会的端上点进去" —— 把它埋进历史列表最底下，等于没做。
   */
  const scheduledMeetings = useMemo(
    () => items.filter((m) => m.status === 0).sort((a, b) => (startTsOf(a) ?? 0) - (startTsOf(b) ?? 0)),
    [items],
  );
  const liveMeetings = useMemo(() => items.filter((m) => m.status === 1), [items]);
  const historyMeetings = useMemo(
    () => items.filter((m) => m.status !== 0 && m.status !== 1),
    [items],
  );
  /**
   * ★进行中会议的「已进行 xx」需要一个时间基准。
   *
   * <p>只在这类会议存在时每 30 秒走一格：列表本身<b>不轮询接口</b>
   * （那会把低频动作变成常态流量），这里只是让文案不要一直停在刷新那一刻。
   */
  const [nowTick, setNowTick] = useState(() => Date.now());
  useEffect(() => {
    if (liveMeetings.length === 0) return;
    const timer = window.setInterval(() => setNowTick(Date.now()), 30_000);
    return () => window.clearInterval(timer);
  }, [liveMeetings.length]);
  const now = nowTick;

  return (
    <div className="meeting-pane">
      {/* ---------------------------------------------------------- 三个操作 */}
      <div className="meeting-actions">
        <ActionTile icon={<IconVideo size={22} />} label="发起" tone="primary" onClick={openStart} />
        <ActionTile icon={<IconJoinRequestSolid size={22} />} label="加入" tone="plain" onClick={openJoin} />
        <ActionTile icon={<IconClock size={22} />} label="预约" tone="plain" onClick={openSchedule} />
      </div>

      {/* ---------------------------------------------------------- 我的预约（服务端，多端同步） */}
      {scheduledMeetings.length > 0 && (
        <div className="meeting-section">
          <div className="meeting-section-head">
            <span className="meeting-section-title">我的预约</span>
          </div>
          <ul className="meeting-schedules">
            {scheduledMeetings.map((s) => {
              const ts = startTsOf(s);
              const room = s.roomName ?? '';
              return (
                <li className="meeting-schedule" key={String(s.id)}>
                  <div className="meeting-schedule-main">
                    <div className="meeting-schedule-title">{meetingDisplayTitle(s.title, room)}</div>
                    {/* ★时间与会议号**分两行**：250px 下挤在一行时末尾的号会被截成
                        「3674…」，而会议号恰好是这张卡片上唯一要念给别人听的东西。 */}
                    <div className="meeting-schedule-meta">
                      {ts != null ? formatScheduleTime(ts, now) : meetingTimeText(s.startTime)}
                      {s.memberCount != null && s.memberCount > 0 ? ` · ${s.memberCount} 人` : ''}
                    </div>
                    <div className="meeting-schedule-no">会议号 {formatMeetingId(room) || '—'}</div>
                  </div>
                  <span className="meeting-state meeting-state-upcoming">{s.statusText || '待开始'}</span>
                  <div className="meeting-schedule-actions">
                    <Button
                      size="small"
                      type="primary"
                      ghost
                      disabled={!room}
                      onClick={() => {
                        if (!room || guardBusy()) return;
                        // ★开始会议沿用预约时的会议号：服务端会把同一条记录 0→1，
                        //   不需要再建一条新记录。
                        // ★游客开关也要沿用预约时勾的那个：预约阶段不建房，开关只存在
                        //   记录上；这里写死 false 会让预约里勾过的开关到开会时凭空消失。
                        void startRoomMeeting(mediaType, room, s.title ?? '', s.allowGuest === true);
                        openRoomWindow(s.title || defaultMeetingTitle(room));
                      }}
                    >
                      开始
                    </Button>
                    <Button
                      size="small"
                      type="text"
                      title="复制会议号"
                      disabled={!room}
                      onClick={() => {
                        void copyText(room).then((ok) => {
                          if (ok) toast.success('会议号已复制');
                          else toast.info(`会议号：${room}`);
                        });
                      }}
                    >
                      复制
                    </Button>
                    {/* ★预约卡片上也要能再取一次邀请链接：预约建好之后用户往往
                        过一会儿才想起来叫别人，不该逼他回忆"那个链接在哪复制"。 */}
                    <Button
                      size="small"
                      type="text"
                      title="复制邀请信息（会议主题 / 会议 ID / 会议链接）"
                      disabled={!room}
                      onClick={() => copyInvite(room, s.title ?? '', s.shareSlug)}
                    >
                      邀请
                    </Button>
                    {/* ★只有主持人能取消（服务端也会校验）；非主持人点它只会拿到一句拒绝 */}
                    {s.host && (
                      <Button
                        size="small"
                        type="text"
                        title="取消这场预约"
                        icon={<IconTrash size={14} />}
                        onClick={() => cancelSchedule(s)}
                      />
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
        </div>
      )}

      {/* ---------------------------------------------------------- 进行中的会议（未入会的端可点进） */}
      {liveMeetings.length > 0 && (
        <div className="meeting-section">
          <div className="meeting-section-head">
            <span className="meeting-section-title">进行中的会议</span>
            <span className="meeting-section-note">可直接入会</span>
          </div>
          <ul className="meeting-schedules">
            {liveMeetings.map((m) => {
              const room = m.roomName ?? '';
              // ★进行中按开始时间实时算：duration_sec 要到会议结束才写，
              //   直接读落库值会显示 0（用户 2026-11-07：「会议时长没有展示出来」）。
              const liveFor = meetingDurationText(m, nowTick);
              return (
                <li className="meeting-schedule is-live" key={String(m.id)}>
                  <div className="meeting-schedule-main">
                    <div className="meeting-schedule-title">{meetingDisplayTitle(m.title, room)}</div>
                    <div className="meeting-schedule-meta">
                      {meetingTimeText(m.startTime)}
                      {liveFor ? ` · 已进行 ${liveFor}` : ''}
                      {m.memberCount != null && m.memberCount > 0 ? ` · ${m.memberCount} 人` : ''}
                    </div>
                    <div className="meeting-schedule-no">会议号 {formatMeetingId(room) || '—'}</div>
                  </div>
                  <span className="meeting-state meeting-state-live">{m.statusText || '进行中'}</span>
                  <div className="meeting-schedule-actions">
                    <Button
                      size="small"
                      type="primary"
                      disabled={!room}
                      onClick={() => {
                        if (!room || guardBusy()) return;
                        void joinRoomMeeting(room, mediaType);
                        openRoomWindow(m.title || defaultMeetingTitle(room));
                      }}
                    >
                      入会
                    </Button>
                  </div>
                </li>
              );
            })}
          </ul>
        </div>
      )}

      {/* ---------------------------------------------------------- 历史记录 */}
      <div className="meeting-section">
        <div className="meeting-section-head">
          <span className="meeting-section-title">历史记录</span>
          <button type="button" className="meeting-refresh" title="刷新" onClick={() => void load()}>
            <IconRefresh size={14} />
          </button>
        </div>

        {loading && (
          <div className="mtg-center">
            <Spin />
          </div>
        )}
        {!loading && error != null && (
          <div className="mtg-error">
            {error}
            <Button size="small" className="mtg-retry" onClick={() => void load()}>
              重试
            </Button>
          </div>
        )}
        {!loading && error == null && items.length === 0 && (
          <div className="mtg-empty">
            <IconVideo size={28} />
            <div className="mtg-empty-title">还没有会议记录</div>
            <div className="mtg-empty-hint">
              点上面的「发起」开一场会，或「预约」一个将来的会；预约和进行中的会议都会出现在这里。
            </div>
          </div>
        )}
        {!loading &&
          error == null &&
          historyMeetings.map((m) => (
            /*
             * ★外壳从 <button> 换成 <div>：行内多了「删除」按钮，
             * 按钮里嵌按钮是非法 HTML，浏览器会把内层按钮扔出去。
             */
            <div className="mtg-row" key={String(m.id)}>
              <button
                type="button"
                className="mtg-item"
                title="查看会议详情"
                onClick={() => openMeetingDetail(String(m.id), meetingDisplayTitle(m.title, m.roomName))}
              >
                {/* ★列表项不再放前置图标：左栏只有 250px，图标占掉 32px 后
                    标题与时间只能二选一换行（用户 2026-11-07 明确要求去掉）。 */}
                <span className="mtg-item-main">
                  <span className="mtg-item-top">
                    <span className="mtg-item-title">{meetingDisplayTitle(m.title, m.roomName)}</span>
                    <span className="mtg-item-time">{meetingTimeText(m.startTime)}</span>
                  </span>
                  <span className="mtg-item-bottom">
                    <span className="mtg-item-meta">{meetingMetaText(m)}</span>
                    <span className={`mtg-badge mtg-badge-${recordBadge(m.recordStatus).tone}`}>
                      {recordBadge(m.recordStatus).text}
                    </span>
                  </span>
                </span>
              </button>
            </div>
          ))}
      </div>

      {/* ---------------------------------------------------------- 发起 */}
      <Modal
        title="发起会议"
        open={dialog === 'start'}
        onCancel={closeDialog}
        onOk={doStart}
        okText="开始"
        cancelText="取消"
        destroyOnClose
      >
        <div className="meeting-form">
          <label className="meeting-field">
            <span className="meeting-field-label">会议主题</span>
            <Input
              value={title}
              maxLength={60}
              placeholder="不填就用会议号当标题"
              onChange={(e) => setTitle(e.target.value)}
            />
            {/* ★不再让人选"视频会议/语音会议"：一律语音开局，进会后需要画面就点「开视频」。
                写一行提示，避免用户以为这个会只能说话、不能露脸。 */}
            <div className="meeting-field-hint">语音入会；进会后想露脸，点会中的「开视频」即可，随时可关。</div>
          </label>
          <div className="meeting-field">
            <span className="meeting-field-label">会议号</span>
            <div className="meeting-no-row">
              <span className="meeting-no">{formatMeetingId(newNo)}</span>
              <Button size="small" type="text" onClick={rollNewNo}>
                换一个
              </Button>
              <Button
                size="small"
                type="text"
                onClick={() => {
                  void copyText(newNo).then((ok) => {
                    if (ok) toast.success('会议号已复制');
                    else toast.info(`会议号：${formatMeetingId(newNo)}`);
                  });
                }}
              >
                复制
              </Button>
              {/* ★★「复制邀请」：9 位数字靠嘴念/手抄极容易错一位（线上真发生过 12 ⇄ 21），
                  链接点开就把号填好，不给他抄错的机会。
                  ★关掉游客开关后这个链接发出去也没用（对方会看到"未开放游客加入"），
                    所以直接禁用 —— 让人复制一条注定失败的链接是最差的一种提示。 */}
              <Button
                size="small"
                type="text"
                title="复制邀请信息（会议主题 / 会议 ID / 会议链接）"
                onClick={() => copyInvite(newNo, title, newShareSlug)}
              >
                复制邀请
              </Button>
            </div>
          </div>
          {/* ★★「邀请参会人」：发起时从我的联系人里选，开始后他们立刻收到来电式入会通知。
              ★与预约的「添加参与者」是两个独立名单（见 startInviteeIds 的注释）。 */}
          <div className="meeting-field">
            <span className="meeting-field-label">邀请参会人</span>
            <UserSearchSelect
              multiple
              showMyContacts
              value={startInviteeIds}
              onChange={setStartInviteeIds}
              excludeUserIds={[myUserId]}
              placeholder="从联系人中选择，可多选（可留空）"
            />
            <div className="meeting-field-hint">
              开始会议后，他们会立刻收到<b>入会通知</b>（和来电一样，可以直接点「加入会议」）。
            </div>
          </div>
          {/* ★★游客开关：默认关 —— 会议默认只让登录用户参加。
              打开后邀请链接才可用（服务端会按它签访客令牌）。 */}
          <div className="meeting-field">
            <div className="meeting-guest-row">
              <span className="meeting-field-label">允许游客加入</span>
              <Switch
                size="small"
                checked={allowGuest}
                onChange={setAllowGuest}
                aria-label="允许游客加入"
              />
            </div>
            <div className="meeting-field-hint">
              {allowGuest
                ? '打开邀请链接的人不登录也能进：填个昵称即可。'
                : '打开邀请链接的人需要先登录；登录成功后会自动回到这场会议。'}
            </div>
          </div>
        </div>
      </Modal>

      {/* ---------------------------------------------------------- 加入 */}
      <Modal
        title="加入会议"
        open={dialog === 'join'}
        onCancel={closeDialog}
        onOk={doJoin}
        okText="加入"
        cancelText="取消"
        destroyOnClose
      >
        <div className="meeting-form">
          <label className="meeting-field">
            <span className="meeting-field-label">会议号 / 邀请码</span>
            <Input
              autoFocus
              value={joinNo}
              maxLength={80}
              placeholder="输入会议号或邀请码，也可直接粘贴会议链接"
              onChange={(e) => setJoinNo(e.target.value)}
              onPressEnter={doJoin}
            />
            <div className="meeting-field-hint">
              ★两种值都认：9 位会议号（<b>945 968 030</b> 这种），
              或者邀请链接里的<b>邀请码</b>（一串小写字母数字，例如 <code>k7m2xq9r4t6w</code>）。
              复制整条链接粘进来也可以。
            </div>
            <div className="meeting-field-hint">
              ★只有<b>正在进行的会议</b>才能加入：号错了会明确告诉你"会议不存在或已结束"，不会给你开一个空房间；
              预约了但还没开始的会会提示「会议还没开始」。
            </div>
            <div className="meeting-field-hint">语音入会；进会后想露脸，点会中的「开视频」即可，随时可关。</div>
          </label>
        </div>
      </Modal>

      {/* ---------------------------------------------------------- 预约 */}
      <Modal
        title="预约会议"
        open={dialog === 'schedule'}
        onCancel={closeDialog}
        onOk={doSchedule}
        okText="保存"
        cancelText="取消"
        destroyOnClose
      >
        <div className="meeting-form">
          <label className="meeting-field">
            <span className="meeting-field-label">会议主题</span>
            <Input
              autoFocus
              value={title}
              maxLength={60}
              placeholder="例如：周会"
              onChange={(e) => setTitle(e.target.value)}
            />
          </label>
          <label className="meeting-field">
            <span className="meeting-field-label">开始时间</span>
            {/* ★用原生 datetime-local：项目里没有声明 dayjs，不为了一个输入框引新依赖 */}
            <input
              type="datetime-local"
              className="meeting-input"
              value={startAtText}
              onChange={(e) => setStartAtText(e.target.value)}
            />
          </label>
          {/* ★★会议号 + 邀请链接：预约阶段就定下来，和"开始"时用的是同一个号。 */}
          <div className="meeting-field">
            <span className="meeting-field-label">会议号</span>
            <div className="meeting-no-row">
              <span className="meeting-no">{formatMeetingId(newNo)}</span>
              <Button size="small" type="text" onClick={rollNewNo}>
                换一个
              </Button>
              <Button
                size="small"
                type="text"
                onClick={() => {
                  void copyText(newNo).then((ok) => {
                    if (ok) toast.success('会议号已复制');
                    else toast.info(`会议号：${formatMeetingId(newNo)}`);
                  });
                }}
              >
                复制
              </Button>
              <Button
                size="small"
                type="text"
                title="复制邀请信息（会议主题 / 会议 ID / 会议链接）"
                onClick={() => copyInvite(newNo, title, newShareSlug)}
              >
                复制邀请
              </Button>
            </div>
            <div className="meeting-field-hint">
              链接里带的是这场会议的<b>邀请码</b>（不是会议号），对方点开就能进、不用手抄；会议<b>开始后</b>链接才能加入。
            </div>
          </div>
          {/* ★开关在「开始」时生效（预约阶段不建房），所以要跟着预约记录存下来。 */}
          <div className="meeting-field">
            <div className="meeting-guest-row">
              <span className="meeting-field-label">允许游客加入</span>
              <Switch
                size="small"
                checked={allowGuest}
                onChange={setAllowGuest}
                aria-label="允许游客加入"
              />
            </div>
            <div className="meeting-field-hint">
              {allowGuest
                ? '打开邀请链接的人不登录也能进：填个昵称即可。'
                : '打开邀请链接的人需要先登录；登录成功后会自动回到这场会议。'}
            </div>
          </div>
          {/* ★★「拉人」：从我的联系人里选，保存后自动给对方发一条带会议号与链接的消息。 */}
          <div className="meeting-field">
            <span className="meeting-field-label">添加参与者</span>
            <UserSearchSelect
              multiple
              showMyContacts
              value={inviteeIds}
              onChange={setInviteeIds}
              excludeUserIds={[myUserId]}
              placeholder="从联系人中选择，可多选"
            />
            <div className="meeting-field-hint">
              保存后会给他们各发一条会议邀请（会议号 + 时间 + 入会链接）。
            </div>
          </div>
          <div className="meeting-field-hint">
            预约保存在服务端，<b>多端登录都能看到同一条</b>；到点后在会议栏点「开始」即可开会（其他端也能看到「进行中」并直接入会）。
          </div>
        </div>
      </Modal>
    </div>
  );
}

// ---------------------------------------------------------------- 小组件

function ActionTile(props: { icon: ReactNode; label: string; tone: 'primary' | 'plain'; onClick: () => void }) {
  return (
    <button type="button" className={`meeting-action meeting-action-${props.tone}`} onClick={props.onClick}>
      <span className="meeting-action-icon">{props.icon}</span>
      <span className="meeting-action-label">{props.label}</span>
    </button>
  );
}

/**
 * 服务端时间串（{@code yyyy-MM-dd HH:mm:ss}，无时区）→ 本机毫秒。
 *
 * <p>★必须把空格换成 {@code T}：Safari 对 {@code new Date('2026-11-08 14:30:00')}
 * 直接返回 Invalid Date —— 整个预约列表的时间会集体变成空白。
 */
function startTsOf(m: { startTime?: string | null }): number | null {
  const s = (m.startTime ?? '').trim();
  if (!s) return null;
  const ts = new Date(s.replace(' ', 'T')).getTime();
  return Number.isFinite(ts) ? ts : null;
}

/** 本机毫秒 → 服务端接受的 {@code yyyy-MM-ddTHH:mm:ss}（本地时间，不带 Z）。 */
function toServerTime(ts: number): string {
  const d = new Date(ts);
  const p = (n: number): string => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}:00`;
}

/** `datetime-local` 的格式是本地时间 `YYYY-MM-DDTHH:mm`（**不要** toISOString，那是 UTC）。 */
function toLocalInput(ts: number): string {
  const d = new Date(ts);
  const p = (n: number): string => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
}

/** 反向解析；空串/坏值返回 null（调用方据此报"请选择开始时间"）。 */
function fromLocalInput(text: string): number | null {
  if (!text) return null;
  const ts = new Date(text).getTime();
  return Number.isFinite(ts) ? ts : null;
}
