import { useMemo } from 'react';
import { Drawer, Empty, Typography } from 'antd';
// ★★DEV-430：视频/语音/文件复用气泡里那三个组件 —— 见文件头「附件要能看能播」。
//   ★不存在循环依赖：MessageBubble 不 import 本文件（两者都由 ChatWindow 引入）。
import { FileCard, VideoAttachment, VoiceAttachment } from './MessageBubble';
// ★★DEV-383：antd <Image> 的「失败重试 → 用尽后给重新加载按钮」（见该文件头注释）。
import RetryableImage from './RetryableImage';
import type { MessageDto } from '../api/types';
import { safeMediaUrl } from '../api/uploadUrl';
import { isAttachmentKind, type AttachmentKind } from '../lib/attachment';
import { MERGE_FORWARD_DIGEST } from '../lib/forward';
import RichText from '../lib/markdown';
import { itemNoun, parseMergeBody } from '../lib/mergeForwardView';
import { dividerTime } from '../lib/timeDivider';

/**
 * ★★DEV-305 ③：合并转发（{@code merge_forward}）卡片的<b>明细抽屉</b> ——
 * 用户点气泡里的「[聊天记录]」卡片时展开，列出快照里的全部子消息。
 *
 * <h2>★它是纯本地组件：零请求、零 loading、零 error 态</h2>
 *
 * <p>快照式存储（用户拍板口径①）的全部意义就在这里 —— 子消息已经<b>复制</b>进
 * body 了，明细不需要问服务端任何事。与 {@code QuoteChainDrawer}（每次打开拉一次
 * replyChain，有 alive 闸门/骨架屏/错误 Alert 三件套）相比，这里连 useEffect 都没有：
 * {@code useMemo} 解析一次 body，数据与消息同生共死。
 * ★推论：切会话不必重置本抽屉的打开态吗？—— 要重置，但那由 ChatWindow 做
 * （它持有 msg 引用；组件自己判 {@code open && msg == null} 兜底画 Empty）。
 *
 * <h2>★形态照 QuoteChainDrawer 的用户拍板先例</h2>
 *
 * <p>独立右侧抽屉（width 400）、<b>不进</b>顶部标签页体系、看完即关 ——
 * 「这段聊天记录里说了什么」是一个问题的答案，不是常驻工作区。
 *
 * <h2>★无头像列</h2>
 *
 * <p>快照契约<b>刻意</b>不存头像 URL（lib/forward 文件头的裁定：存了也是别人会话里的
 * 过期地址）。行内只画「名字 + 时间」，名字是快照定格时的 senderName ——
 * 改名/退群后这里显示的仍是<b>转发那一刻</b>的名字，这正是"快照"的语义。
 *
 * <h2>★文本项走气泡同款 RichText（DEV-306）</h2>
 *
 * <p>快照里的 {@code text} 是<b>对端可控</b>内容（转发的人管不了原文里写了什么），
 * 与气泡正文的信任等级完全相同 ⇒ 渲染器也必须相同：{@code RichText} 内含
 * marked 解析 + <b>DOMPurify 消毒单点</b>（lib/markdown 的裁定：消毒只此一处，
 * 任何绕过它直塞 HTML 的写法都是漏洞）。旧版这里是纯文本插值 —— md 源码
 * 原样露出（用户反馈「没有 md 渲染」），修复即接入同一管线，不另写第二套。
 *
 * <h2>★★附件的信任边界在本组件（不在 parse 层）</h2>
 *
 * <p>{@code parseMergeBody} 只做结构解析、<b>不</b>验证 url（见其文件头）；
 * 把 url 塞进 DOM 属性（{@code <img src>}）之前必须过 {@code safeMediaUrl} ——
 * 本组件就是"画的地方"，image 附件逐个过闸，闸不放行的<b>不画缩略图</b>。
 *
 * <h2>★★DEV-430：视频/语音/文件也要能看能播（关闭原「G 缺口」）</h2>
 *
 * <p>原实现只给图片画缩略图，file/audio/video 一律退化成一行<b>只读文件名</b> ——
 * 用户看到合并记录里有一段视频，点哪里都没反应（用户原话：「视频无法查看和播放」）。
 * 快照里的 url 本来就是原消息的地址，浏览器能取到就能播；把它渲染成不可点的灰字，
 * 是把"可能过期"当成了"一定打不开"，代价是<b>正常地址也永远打不开</b>。
 *
 * <p>现在的口径：<b>与气泡里完全同一套组件</b>（{@code VideoAttachment} /
 * {@code VoiceAttachment} / {@code FileCard}）—— 视频有封面 + 播放按钮、语音可播可转写、
 * 文件可下载。★同一个东西在两个渲染面长成两个样子，正是本仓反复记过的坑。
 *
 * <p>★过期的地址仍然要如实降级，但降级点是<b>播放器/下载自身</b>：视频播放失败时
 * 下面那行 {@code FileCard} 仍在，文件点击失败由 {@code saveAndOpenMedia} 报错。
 * <b>只有 {@code safeMediaUrl} 拦下的地址</b>才退回只读文件名 + 一句原因 ——
 * 那种地址连"试一下"都不该发生（DEV-159 纪律：危险 URL 不落在 DOM 属性上）。
 */
export default function MergeForwardDrawer({
  msg,
  open,
  onClose,
}: {
  /** 被点的那条 {@code merge_forward} 消息（快照全在它的 body 里）。null = 没得看。 */
  msg: MessageDto | null;
  open: boolean;
  onClose: () => void;
}) {
  /**
   * ★解析放在 useMemo 而不是渲染体内联：明细行/摘要行/标题都从同一份视图来，
   * 解析两遍是两把尺子。parse 返回 null（body 畸形）时画 Empty 兜底 ——
   * 正常到不了这里（气泡侧同一把 parse 判 null 就不画可点卡片），
   * 但抽屉被"消息在打开期间被撤回/替换"打到 null 时不能白屏。
   */
  const view = useMemo(() => (msg ? parseMergeBody(msg.body) : null), [msg]);

  return (
    <Drawer title={view?.title ?? MERGE_FORWARD_DIGEST} open={open} onClose={onClose} width={400}>
      {view == null ? (
        // ★与 QuoteChainDrawer 的"畸形响应留一句话，不留白"同款裁定。
        <Empty description="无法展开这段聊天记录" />
      ) : (
        <div className="merge-fwd-items" data-merge-fwd-items="">
          {view.items.map((it, i) => (
            // ★key 用行号：快照定格后不增删不排序，行号就是稳定身份证
            //   （子消息没有自己的 msgId —— 契约里刻意不存，雪花 ID 超出 JS 精度）。
            <div className="merge-fwd-item" key={i}>
              <div className="merge-fwd-item-meta">
                <span className="merge-fwd-item-name">{it.senderName}</span>
                <span className="merge-fwd-item-time">{dividerTime(it.sendTime)}</span>
              </div>
              {it.text != null && (
                <div className="merge-fwd-item-text">
                  {/* ★DEV-306：与气泡同一渲染器（md 渲染 + DOMPurify 消毒单点都在 RichText 内）。
                      names 刻意不传：快照里没有 mention 上下文，@高亮无从谈起（渲染为纯文本无副作用）。 */}
                  <RichText text={it.text} />
                </div>
              )}
              {it.attachments.length > 0 && (
                <div className="merge-fwd-item-atts">
                  {it.attachments.map((a, j) => {
                    // ★★DEV-430：所有类型都先过闸；只有被拦下的才退回只读文件名
                    //   （旧实现只对 image 过闸，其余类型一律不可点 —— 见文件头）。
                    const url = safeMediaUrl(a.url);
                    if (!url) {
                      return (
                        <div className="merge-fwd-att-file" key={j}>
                          <Typography.Text ellipsis style={{ maxWidth: 280 }}>
                            {a.fileName || `[${itemNoun(a.kind)}]`}
                          </Typography.Text>
                        </div>
                      );
                    }
                    if (a.kind === 'image') {
                      return (
                        <RetryableImage
                          key={j}
                          src={url}
                          alt={a.fileName || '图片'}
                          className="merge-fwd-thumb"
                          width={96}
                          height={96}
                          style={{ objectFit: 'cover', borderRadius: 6 }}
                          // ★★DEV-383：同文件面板那处（compact + 尺寸内联钉住，理由见那里注释）。
                          //   ★`.merge-fwd-thumb` 在 styles.css 里**没有**定义 ⇒ 尺寸全靠
                          //     这里的 width/height 属性，失败态必须自己把 96×96 补上。
                          compactReload
                          reloadStyle={{ width: 96, height: 96, borderRadius: 6, flexShrink: 0 }}
                        />
                      );
                    }
                    // ★★DEV-430：与气泡里**同一套组件**（视频封面+播放、语音可播可转写、
                    //   文件可下载）。快照不存 size ⇒ 传 0，FileCard 会显示「下载」而不是假大小。
                    const kind: AttachmentKind = isAttachmentKind(a.kind) ? a.kind : 'file';
                    if (kind === 'video') {
                      return (
                        <VideoAttachment
                          key={j}
                          a={{ kind, url, fileName: a.fileName || '视频', size: 0 }}
                        />
                      );
                    }
                    if (kind === 'audio') {
                      return (
                        <VoiceAttachment
                          key={j}
                          a={{ kind, url, fileName: a.fileName || '语音', size: 0 }}
                        />
                      );
                    }
                    return (
                      <FileCard
                        key={j}
                        kind={kind}
                        url={url}
                        fileName={a.fileName || '文件'}
                        size={0}
                      />
                    );
                  })}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </Drawer>
  );
}
