import type { CSSProperties } from 'react';
import { Image } from 'antd';
import type { ImageProps } from 'antd';
import ImgReloadButton from './ImgReloadButton';
import { useImageRetry } from '../lib/useImageRetry';

/**
 * ★★DEV-383：给 <b>antd {@code <Image>}</b> 用的「失败重试 + 用尽后给重载按钮」包装。
 *
 * <h2>为什么不能直接在 antd {@code <Image>} 上挂一个 {@code onError}</h2>
 *
 * <p>因为{@code rc-image}（antd Image 的底座，本仓是 7.12.0）的失败判定
 * <b>不走 {@code <img>} 自己的 {@code onError}</b>：
 *
 * <pre>
 * useStatus.js
 *   useEffect(() =&gt; { isImageValid(src).then(v =&gt; { if (!v) setStatus('error') }) }, [src]);
 *   const srcAndOnload = isError &amp;&amp; fallback ? { src: fallback } : { onLoad, src };
 * </pre>
 *
 * <p>也就是说：它<b>另起一个 {@code new Image()} 预加载探测</b>原地址，探到失败后
 * 把 DOM 里那张 {@code <img>} 的 {@code src} 换成 {@code fallback} 地址 ——
 * <b>原图根本就不在 DOM 里</b>。所以"挂个 onError 记下失败"这条路在传了
 * {@code fallback} 的调用点上<b>永远不会被触发</b>：那张 fallback 图加载得好好的，
 * 既不 error 也不告诉我们原图怎么样了。
 *
 * <h2>★★因此这个包装做了两件必须成对出现的事</h2>
 *
 * <ol>
 *   <li><b>调用点不再传 {@code fallback}</b>（本组件的 props 直接把 {@code fallback}
 *       从 antd 的类型里摘掉，编译期就挡住）—— 这样 {@code srcAndOnload} 走的是
 *       {@code { onLoad, src }} 那一支，原图仍在 DOM 里，我们传的 {@code onError}
 *       才会被触发（{@code Image.js} 里 {@code onError} 是无条件挂到 {@code <img>} 上的）；</li>
 *   <li><b>失败态由我们接管</b>：{@code exhausted} 时<b>根本不渲染 antd Image</b>，
 *       改渲染 {@link ImgReloadButton}。于是"灰底小山 + 永远不再试"这个终态
 *       被换成了"用户点一下就能再要一次"。</li>
 * </ol>
 *
 * <h2>★重试靠 {@code key}，不是靠重新渲染</h2>
 *
 * <p>{@code src} 不变时 React 只会复用同一个元素做属性比对，浏览器不会再发请求
 * ——"重试"必须靠 {@code key={attempt}} 强制卸载重挂（详见 {@code lib/useImageRetry}）。
 *
 * <h2>★为什么只在这些坑位用</h2>
 *
 * <p>用户拍板的口径是<b>按钮只给内容型图片</b>（消息气泡图、附件/正文图、文件面板、
 * 合并转发）。头像是"认人"的辅助信息——它挂了就用首字兜底，再挂一个按钮只会让
 * 界面变吵；而且一屏几十颗头像同时重试会给服务端制造一次没必要的尖峰。
 */
export interface RetryableImageProps extends Omit<ImageProps, 'src' | 'fallback' | 'onError'> {
  src: string;
  /**
   * ★★小坑位（文件面板 40×40、合并转发 96×96）专用：重载按钮只显示图标。
   * <p>40px 里塞不下「重新加载」四个字，塞进去就是一团黑。
   */
  compactReload?: boolean;
  /** 让重载按钮与它替换掉的那张图**同尺寸**（否则图片位会塌成一个不一样大的方块）。 */
  reloadStyle?: CSSProperties;
  /** 重载按钮的定位类（例如在网格里占满一格）。 */
  reloadClassName?: string;
  /** 超时阈值，缺省见 {@code lib/imgRetry}。 */
  timeoutMs?: number;
}

export default function RetryableImage({
  src,
  compactReload,
  reloadStyle,
  reloadClassName,
  timeoutMs,
  ...rest
}: RetryableImageProps) {
  const { attempt, exhausted, onError, onLoad, reload } = useImageRetry(src, {
    ...(timeoutMs != null ? { timeoutMs } : {}),
  });

  if (exhausted) {
    return (
      <ImgReloadButton
        onReload={reload}
        {...(compactReload != null ? { compact: compactReload } : {})}
        {...(reloadStyle != null ? { style: reloadStyle } : {})}
        {...(reloadClassName != null ? { className: reloadClassName } : {})}
      />
    );
  }

  return (
    <Image
      {...rest}
      // ★★换 key ⇒ 卸载重挂 ⇒ 真的重新发请求（理由见文件头）。
      key={attempt}
      src={src}
      // ★这两个是我们自己接管的失败/成功信号；antd 的 fallback 已被 props 类型摘掉。
      onError={onError}
      onLoad={onLoad}
    />
  );
}
