import { useState } from 'react';
import { App as AntApp, Form, Input, Modal, Tabs, Typography } from 'antd';
import { useChatStore } from '../store/chat';
import { CREATE_GROUP_JOIN_RULE } from '../lib/groupJoinRule';
import { CREATE_GROUP_AGENT_HINT } from '../lib/agentMode';
import { createGroupOutcome } from '../lib/memberAdd';
import UserSearchSelect from './UserSearchSelect';
import AgentSearchSelect from './AgentSearchSelect';

/**
 * ★★「创建群聊」弹窗（DEV-328：初始成员支持【智能体】）。
 *
 * <h2>★为什么改的只有前端</h2>
 *
 * <p>服务端对"建群初始成员里有智能体"<b>早就全链路支持</b>：
 * <ul>
 *   <li>{@code filterAddable} 对智能体短路平台"账号还在吗"预检（DEV-166，
 *       否则 N 个智能体 = N 次必然查不到的往返 + N 条污染可观测性的 WARN）；</li>
 *   <li>DEV-294 需求①权限闸：创建者对所选智能体<b>必须有使用权限</b>
 *       （★DEV-336 拍板②起呈现与「加群员」同形：无权限的<b>摘出本批</b>、
 *       由 {@code memberResult.failedUserIds} 点名，不再整批拒绝；
 *       唯一保留的整批拒绝 = 勾的人一个可用的都不剩，那时群根本不建）；</li>
 *   <li>DEV-271 拍板④：建群即落 {@code AgentBinding}（inviter=创建者），
 *       mode=null ⇒ 默认<b>唤起</b> —— 且<b>刻意不给</b>建群请求加 agentMode 字段。</li>
 * </ul>
 * 缺口只是本弹窗的选人组件只有"搜人"一个来源（{@code /search/contacts}），
 * 而智能体没有本地副本、必须走 {@code /contacts/agents}（见 {@link AgentSearchSelect}）。
 *
 * <h2>★形态照抄 {@code AddMemberModal} 的双 Tab 母版，两处<b>刻意不同</b>
 * （★原有第三处，DEV-336 起被服务端行为推翻，见第 3 条）</h2>
 *
 * <ol>
 *   <li><b>没有「衔接模式」选择器</b> —— 服务端拍板④（见
 *       {@code CREATE_GROUP_AGENT_HINT} 的注释）：建群是最高频路径，不塞低频开关；
 *       默认唤起、建群后去群成员面板改。底部文案把这条说清楚，不静默。</li>
 *   <li><b>失败时弹窗不关、已选不清</b> —— 与母版同款：搜索是远程的，
 *       关掉弹窗等于让用户把那几个名字重新搜一遍。</li>
 *   <li>★<b>旧差异「没有三分流说明」已作废（DEV-336）</b>：原先建群时所有初始成员
 *       都直接进群、"要不要同意"是「添加群员」独有的事实，所以这里刻意不放三分流说明。
 *       ★★现在服务端建群走与加群员<b>完全相同的分流</b>（同 Team 与智能体直接进、
 *       其他用户等本人同意）⇒ 底部成对文案（{@code CREATE_GROUP_JOIN_RULE}）改讲
 *       这套规则；结果 toast 由 {@code lib/memberAdd.createGroupOutcome} 按回执里的
 *       {@code memberResult} 算 —— 再只说「群已创建」，就是把"等同意"显示成"都进了"。</li>
 * </ol>
 *
 * <h2>★「只拉智能体」是合法组合</h2>
 *
 * <p>用户需求原话："创建群时支持只拉智能体，现在只能拉人"。
 * 本弹窗的成员校验只看<b>总数</b>（用户 + 智能体 ≥ 1），不按类型设下限；
 * 服务端 {@code createGroup} 的 guests 也允许全部是智能体
 * （人数闸门按总数算、权限闸逐个查、绑定行逐个落）⇒ "我 + N 个智能体"两端都通。
 */
export default function CreateGroupModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [form] = Form.useForm<{ name: string }>();
  const createGroup = useChatStore((s) => s.createGroup);
  const selectConv = useChatStore((s) => s.selectConv);
  const userId = useChatStore((s) => s.userId);
  const { message: toast } = AntApp.useApp();
  const [loading, setLoading] = useState(false);

  /**
   * ★两个 Tab 各存一份已选（提交时取并集）—— 与 {@code AddMemberModal} 同款。
   * ★都是<b>字符串 id</b>：{@code UserSearchSelect} 交出来的就是 id 数组，
   * {@code AgentSearchSelect} 的多选形态也一样；智能体的 subjectId 是服务端编码过的
   * 独立号段，与人不会撞号 ⇒ 提交路径<b>不需要任何"按类型分叉"的代码</b>。
   */
  const [tab, setTab] = useState<'user' | 'agent'>('user');
  const [uids, setUids] = useState<string[]>([]);
  const [agentIds, setAgentIds] = useState<string[]>([]);
  const total = uids.length + agentIds.length;

  /**
   * ★state 长在本组件上（{@code destroyOnClose} 销毁的是 Modal 的<b>子树</b>，
   * 销毁不了这里的 useState）⇒ 关闭与提交成功后都必须手动复位，
   * 否则下一次打开会残留上一次的勾选 —— 而界面看起来是"全新的弹窗"。
   */
  const reset = () => {
    setUids([]);
    setAgentIds([]);
    setTab('user');
  };

  const close = () => {
    reset();
    onClose();
  };

  const onOk = async () => {
    const v = await form.validateFields();
    if (total === 0) {
      // ★与母版同款：空选提交给一条明确的 warning，而不是让服务端的
      //   "至少选择 1 名成员"隔着一次往返再弹回来。
      toast.warning('请至少选择 1 名成员（用户或智能体均可）');
      return;
    }
    setLoading(true);
    try {
      // ★并集提交，**用户在前**、去重 —— 与 AddMemberModal 逐字同款
      //   （顺序只影响"哪一批先处理"的直觉，不影响语义；重复 id 会让服务端计数多报）。
      const all = Array.from(new Set([...uids, ...agentIds]));
      const conv = await createGroup(v.name.trim(), all);
      // ★★DEV-336：结果文案来自纯函数 lib/memberAdd.createGroupOutcome（母版同款：
      //   不写 toast[outcome.level](...)，动态取方法名依赖 this 绑定）。
      //   memberResult 缺失（幂等回放等）时它退回裸的「群已创建」。
      const outcome = createGroupOutcome(conv.memberResult);
      if (outcome.level === 'warning') toast.warning(outcome.text);
      else toast.success(outcome.text);
      form.resetFields();
      reset();
      onClose();
      await selectConv(conv.convId);
    } catch (e) {
      toast.error((e as Error).message);
      // ★★失败时【直接返回】：弹窗不关、已选不清 —— 用户原地就能重试（见类注释第 3 条）。
    } finally {
      setLoading(false);
    }
  };

  /**
   * ★Tab 标题带上<b>已选计数</b>（母版同款）：零值不显示（界面安静），
   * 非零才跳出来提醒 —— 建群比加人更需要它：提交按钮在弹窗底栏，
   * 用户切到另一个 Tab 后看不见上一个 Tab 选了几个人。
   */
  const tabLabel = (text: string, n: number) => (n > 0 ? `${text}（${n}）` : text);

  return (
    <Modal title="创建群聊" open={open} onCancel={close} onOk={onOk} confirmLoading={loading} destroyOnClose>
      <Form form={form} layout="vertical">
        <Form.Item name="name" label="群名称" rules={[{ required: true, message: '请输入群名称' }]}>
          <Input placeholder="例如：项目讨论组" maxLength={50} />
        </Form.Item>
        {/* ★成员区不再挂在 Form.Item 的 name 上：两个 Tab 的已选是**组件 state**
            （跨 Tab 保留，切走再切回来不丢），Form 只管群名称。
            ★label 留在 Form.Item 上（不带 name = 纯布局），样式与"群名称"一致。 */}
        <Form.Item label="初始成员（可稍后再加，至少 1 名）" required>
          <Tabs
            activeKey={tab}
            onChange={(k) => setTab(k === 'agent' ? 'agent' : 'user')}
            items={[
              {
                key: 'user',
                label: tabLabel('用户', uids.length),
                children: (
                  <>
                    {/* ★原文案原样保留（只是从弹窗底部挪进了所属 Tab）：
                        这句"与创建单聊同一条规则校验"是 DEV-36 闸门的事实陈述。 */}
                    <div className="member-add-hint">
                      只能邀请平台上的「可联系人」（服务端按与创建单聊同一条规则校验）；
                      搜不到的人需要先在平台侧建立可见关系。你不会出现在候选里。
                    </div>
                    {/* ★★DEV-355（拍板①⑤）：showMyContacts = 打开弹窗就先列出
                        「我的联系人」，与「添加群员」那处是同一对开关。
                        ★建群没有"已有成员"概念，所以排除项仍然只有自己。 */}
                    <UserSearchSelect
                      multiple
                      showMyContacts
                      excludeUserIds={[userId]}
                      value={uids}
                      onChange={setUids}
                      placeholder="输入姓名搜索可联系人"
                    />
                  </>
                ),
              },
              {
                key: 'agent',
                label: tabLabel('智能体', agentIds.length),
                children: (
                  <>
                    {/* ★与「添加群员」弹窗同句：候选=当前租户内你能用到的
                        （DEV-294 权限闸在前端的第一道体现；服务端还有第二道）。 */}
                    <div className="member-add-hint">搜索已发布的智能体（当前租户内你能用到的）</div>
                    {/* ★★DEV-355：同上（智能体那一半）。 */}
                    <AgentSearchSelect multiple showMyContacts value={agentIds} onChangeIds={setAgentIds} />
                  </>
                ),
              },
            ]}
          />
        </Form.Item>
        {/* ★★DEV-315 需求①的成对文案（★DEV-336 起内容整体换过：两端从"解释差别"
            变成"宣告同一套规则"；两半仍由 groupJoinRule.test.ts 钉住）。 */}
        <Typography.Text type="secondary" style={{ fontSize: 12 }}>
          {CREATE_GROUP_JOIN_RULE.here}
          <br />
          {CREATE_GROUP_JOIN_RULE.elsewhere}
        </Typography.Text>
        {/* ★★DEV-328：智能体的事实说明（直接进群 / 默认唤起 / 面板可改）——
            真源收在 lib/agentMode.ts（三段各对着一处服务端事实，见那里注释），
            由 agentMode.test.ts 钉住关键短语。 */}
        <Typography.Text type="secondary" style={{ fontSize: 12, display: 'block', marginTop: 4 }}>
          {CREATE_GROUP_AGENT_HINT}
        </Typography.Text>
      </Form>
    </Modal>
  );
}
