/**
 * ★DEV-173：本地缓存的<b>落盘时机调度</b>（debounce + maxWait）。
 *
 * <h2>★为什么和 {@code convCache.ts} 分成两个文件</h2>
 *
 * <p>两者的失败模式<b>没有共同的症状</b>，混在一起会让单测互相干扰：
 * <ul>
 *   <li>{@code convCache.ts} 的失败是「<b>存进去的读出来不对</b>」—— 纯数据问题；</li>
 *   <li>本文件的失败是「<b>写的次数/时机不对</b>」—— 纯调度问题。
 *       写多了表现为输入框掉帧，写少了表现为"关掉浏览器再打开还是空的"。</li>
 * </ul>
 * 所以这里<b>不认识</b>任何 DTO，只认识"哪些东西脏了"。
 *
 * <h2>★为什么必须有 maxWait（只有 debounce 是不够的）</h2>
 *
 * <p>只有 debounce 的话，一个每 1 秒来一条消息的活跃群会把定时器<b>永远顶掉</b>
 * —— 用户聊了一整天，一个字节都没落盘，第二天打开还是空的。
 * {@link FLUSH_MAX_WAIT_MS} 是"攒着的东西最久能压多久"的硬上限。
 *
 * <h2>★为什么是 debounce 而不是"每条都写"</h2>
 *
 * <p>一次落盘 ≈ 一次 {@code JSON.stringify}(20KB) + {@code localStorage.setItem}，
 * 而 {@code setItem} 是<b>同步阻塞</b>的。量级 1~3ms，单看不吓人，
 * 但高频群每秒好几条，逐条写就是每秒好几次主线程停顿 —— 那会直接变成
 * "打字的时候偶尔卡一下"，而这种 bug 没人能定位到这里。
 */
/** 攒多久没有新动静就落盘。 */
export const FLUSH_DEBOUNCE_MS = 1200;

/** ★攒着的东西最多压这么久，到点必落（防止持续活跃把定时器永远顶掉）。 */
export const FLUSH_MAX_WAIT_MS = 6000;

/** 这次要写什么。★调用方（store）拿它去 {@code convCache.writeCache}。 */
export interface DirtySnapshot {
  /** 会话列表是否变脏（未读 / 置顶 / 免打扰 / 摘要前进…）。 */
  convs: boolean;
  /** ★变脏的会话 id。只写这些，不写全部 —— 这是"分包"能省下开销的前提。 */
  msgs: string[];
}

/** ★注入点：时钟与定时器。生产用默认值，单测塞假时钟（见 cacheFlush.test.ts）。 */
export interface FlushClock {
  now: () => number;
  setTimer: (fn: () => void, ms: number) => unknown;
  clearTimer: (handle: unknown) => void;
}

const DEFAULT_CLOCK: FlushClock = {
  now: () => Date.now(),
  setTimer: (fn, ms) => setTimeout(fn, ms),
  clearTimer: (h) => clearTimeout(h as ReturnType<typeof setTimeout>),
};

export interface FlushSchedulerOptions extends Partial<FlushClock> {
  debounceMs?: number;
  maxWaitMs?: number;
}

export interface FlushScheduler {
  /** 会话列表脏了。 */
  markConvs: () => void;
  /** 某个会话的消息脏了。★`convId` 内部会 String 归一。 */
  markMsgs: (convId: string) => void;
  /**
   * 立刻落盘（{@code pagehide} / 手动触发）。
   *
   * @returns 是否真的写了 —— {@code false} = 没有脏数据，<b>没有调用 write</b>。
   */
  flushNow: () => boolean;
  /** 有没有攒着没写的东西。 */
  isDirty: () => boolean;
  /** ★停掉（登出 / 组件卸载后）。之后再 mark 是空操作。 */
  dispose: () => void;
}

/**
 * ★★建一个落盘调度器。
 *
 * @param write 真正写盘的回调。★它<b>必须自己吞掉所有异常</b>
 *   （{@code convCache.writeCache} 就是这么做的：配额失败降级、再失败返回 {@code ok:false}）。
 *   万一它还是抛了，本调度器会把脏标记<b>原样放回去</b>并停止重排定时器 ——
 *   宁可等下一次 mark 再写，也不要在一个空转的循环里反复抛。
 */
export function createFlushScheduler(
  write: (dirty: DirtySnapshot) => void,
  opts: FlushSchedulerOptions = {},
): FlushScheduler {
  const now = opts.now ?? DEFAULT_CLOCK.now;
  const setTimer = opts.setTimer ?? DEFAULT_CLOCK.setTimer;
  const clearTimer = opts.clearTimer ?? DEFAULT_CLOCK.clearTimer;
  const debounceMs = opts.debounceMs ?? FLUSH_DEBOUNCE_MS;
  const maxWaitMs = opts.maxWaitMs ?? FLUSH_MAX_WAIT_MS;

  let dirtyConvs = false;
  const dirtyMsgs = new Set<string>();
  /** ★"这一批脏数据最早是什么时候脏的"—— maxWait 的起算点，只在变脏的那一刻记一次。 */
  let firstDirtyAt: number | null = null;
  let timer: unknown = null;
  let disposed = false;

  function isDirty(): boolean {
    return dirtyConvs || dirtyMsgs.size > 0;
  }

  function clearPending(): void {
    if (timer !== null) {
      clearTimer(timer);
      timer = null;
    }
  }

  /**
   * ★把这一批脏数据取走并清空。
   *
   * <p>"先取走再写"而不是"写完再清"：写在时间上是不确定的（可能抛、可能慢），
   * 而这中间随时可能有新的 mark 进来 —— 先清再写，那些新 mark 才会正确地
   * 排到<b>下一批</b>，不会被这次写顺手带走后又当成已写。
   */
  function takeSnapshot(): DirtySnapshot {
    const snap: DirtySnapshot = { convs: dirtyConvs, msgs: [...dirtyMsgs] };
    dirtyConvs = false;
    dirtyMsgs.clear();
    firstDirtyAt = null;
    return snap;
  }

  function restore(snap: DirtySnapshot): void {
    dirtyConvs = dirtyConvs || snap.convs;
    for (const id of snap.msgs) dirtyMsgs.add(id);
    // ★不重排定时器：等下一次 mark 或显式 flushNow。自动重排会在"write 恒抛"
    //   时变成一个永不停止的重试循环，而缓存写盘失败本来就不该有任何用户可见的后果。
  }

  function flush(): void {
    clearPending();
    if (!isDirty()) return;
    const snap = takeSnapshot();
    try {
      write(snap);
    } catch {
      restore(snap);
    }
  }

  /**
   * ★排下一次落盘。
   *
   * <p>等待时间 = {@code min(debounceMs, 距离 maxWait 还剩多久)}。
   * 这个 {@code min} 就是"debounce 但保证不饿死"的全部实现 ——
   * 持续活跃时它会一路缩到 0（到点立刻写），安静下来时它就是纯 debounce。
   */
  function schedule(): void {
    if (disposed) return;
    const t = now();
    if (firstDirtyAt === null) firstDirtyAt = t;
    const elapsed = t - firstDirtyAt;
    if (elapsed >= maxWaitMs) {
      flush();
      return;
    }
    const wait = Math.min(debounceMs, maxWaitMs - elapsed);
    clearPending();
    timer = setTimer(flush, Math.max(0, wait));
  }

  function mark(convId: string | null): void {
    if (disposed) return;
    if (convId === null) dirtyConvs = true;
    else dirtyMsgs.add(String(convId));
    schedule();
  }

  return {
    markConvs: () => mark(null),
    markMsgs: (convId) => mark(String(convId)),

    flushNow: () => {
      if (disposed || !isDirty()) {
        // ★没有脏数据时【不】调用 write：一次空的写盘 = 一次无谓的
        //   stringify + setItem，而 pagehide 在所有页面上都会触发一次。
        clearPending();
        return false;
      }
      flush();
      return true;
    },

    isDirty,

    dispose: () => {
      disposed = true;
      clearPending();
      // ★顺手把脏标记清掉：dispose 的语义是"别再用这个调度器了"，
      //   留着脏数据只会让下一个持有者拿到一份来历不明的待写清单。
      dirtyConvs = false;
      dirtyMsgs.clear();
      firstDirtyAt = null;
    },
  };
}
