/**
 * ★★「会议详情」弹框里的内容 —— 用户 2026-11-07 的最终口径：
 *
 * <blockquote>
 * 「会议详情的弹框不是新浏览器窗口弹框，页面内弹框」
 * </blockquote>
 *
 * <p>宿主在 {@code lib/meetingDetailDialog.tsx}（模块级单例 + 遮罩），本文件只管内容。
 *
 * <h2>★★为什么这个文件里一个 antd 组件都没有</h2>
 *
 * <p>它要能在**任何 document** 里长对：会中界面会被渲染进独立窗口
 * （见 {@code lib/meetingWindow.ts}），那边没有 antd v5 的 cssinjs 样式
 * （样式只在主文档 head 里注入）——{@code <Button>} 会是一颗裸按钮，
 * {@code App.useApp()} 更是直接拿不到上下文。
 *
 * <p>所以这里只用项目自己的类 + 原生 {@code <button>}，删除也用行内二次确认，
 * 不弹 {@code Modal}。好处是同一份内容可以同时服务页面内弹框与会中窗口。
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';

import { meetingRecordApi } from '../api';
import type {
  MeetingRecordDetailView,
  MeetingRecordFileView,
  MeetingRecordMemberView,
  MeetingTranscriptView,
} from '../api/types';
import { copyText } from '../lib/clipboard';
import { formatMeetingId, meetingDisplayTitle } from '../lib/meetingLink';
import { notifyMeetingRecordDeleted } from '../lib/meetingRecordEvents';
import {
  bytesText,
  deleteActionLabel,
  deleteConfirmText,
  durationText,
  fileBadge,
  fileCanDownload,
  playKind,
  meetingDurationText,
  meetingMetaText,
  meetingTimeText,
  recordBadge,
  recordingDisplayName,
  speakerLabels,
  speakerNameOf,
  timelineText,
  transcriptBadge,
  transcriptIsDone,
  transcriptPlainText,
  transcriptSummary,
} from '../lib/meetingRecord';
import { IconCallEntry, IconFile, IconPhone, IconTrash } from './icons';

/** 服务端 404（会议模块未启用）要给一句人话，而不是把 HTTP 状态甩给用户。 */
function humanError(e: unknown): string {
  const msg = e instanceof Error ? e.message : typeof e === 'string' ? e : '网络异常';
  if (/404|not found/i.test(msg)) return '会议功能未开启';
  return msg;
}

interface Props {
  meetingId: string;
  /** 标题栏在详情加载出来之前先显示的会议名（可省）。 */
  title?: string;
  /** 关闭弹框（右上角 ×）。 */
  onClose?: () => void;
  /** 删除成功：记录已经没了，弹框里也没有"列表"可回，直接关掉。 */
  onDeleted?: () => void;
}

export default function MeetingDetailDialog({ meetingId, title, onClose, onDeleted }: Props) {
  const [detail, setDetail] = useState<MeetingRecordDetailView | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  /** 正在签名的文件 id（一个按钮一个转圈）。 */
  const [signing, setSigning] = useState<string | null>(null);
  /**
   * ★当前正在播放的文件（null = 收起播放器）。
   *
   * <p>地址是<b>现签的播放地址</b>（inline），不是下载地址；两者指向同一个对象，
   * 区别只在 `Content-Disposition`，所以在这里互相替换会直接表现成
   * "点播放先弹下载框"。
   */
  const [playing, setPlaying] = useState<{
    fileId: string;
    kind: 'video' | 'audio';
    url: string;
    name: string;
  } | null>(null);
  const [removing, setRemoving] = useState(false);
  /** ★删除是行内二次确认：第一次点击只是把按钮换成「确认删除 / 取消」。 */
  const [confirming, setConfirming] = useState(false);
  const [flash, setFlash] = useState<{ text: string; fail?: boolean } | null>(null);
  const flashTimer = useRef<number | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);

  const showFlash = useCallback((text: string, fail = false) => {
    setFlash({ text, fail });
    if (flashTimer.current != null) window.clearTimeout(flashTimer.current);
    flashTimer.current = window.setTimeout(() => setFlash(null), 2200);
  }, []);

  useEffect(
    () => () => {
      if (flashTimer.current != null) window.clearTimeout(flashTimer.current);
    },
    [],
  );

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const d = await meetingRecordApi.detail(meetingId);
      setDetail(d);
    } catch (e) {
      setError(humanError(e));
    } finally {
      setLoading(false);
    }
  }, [meetingId]);

  useEffect(() => {
    void load();
  }, [load]);

  const meeting = detail?.meeting;
  /**
   * ★是不是主持人 —— 决定删除的影响范围（服务端只认 `hostUserId`，这里只是把
   * 它的口径如实展示出来，别让参会人以为自己能删掉别人的记录）。
   */
  const isHost = meeting?.host === true;
  // ★详情没回来之前先用调用方传进来的会议名，弹框标题不会先闪一下「会议详情」。
  const displayTitle = meeting
    ? meetingDisplayTitle(meeting.title, meeting.roomName ?? detail?.roomName)
    : title || '会议详情';

  /**
   * ★点一次「播放」= 向服务端现签一个 inline 地址。
   *
   * <p>为什么不在列表加载时就把地址取回来：签名地址是临时凭证，
   * 列表停留几分钟后地址就过期了，用户点播放只会看到黑屏。
   * 每次点击现签，链接才永远"刚出炉"。
   */
  const play = useCallback(
    async (file: MeetingRecordFileView) => {
      const kind = playKind(file.status, file.contentType, file.filename);
      if (kind == null) {
        showFlash('这个文件不支持在页面内播放，请下载后查看', true);
        return;
      }
      // 再点同一个文件 = 收起播放器（按钮变成"收起点播"）
      if (playing?.fileId === file.id) {
        setPlaying(null);
        return;
      }
      setSigning(file.id);
      try {
        const res = await meetingRecordApi.fileUrl(meetingId, file.id);
        const url = res.playUrl || res.url;
        if (!url) {
          showFlash(res.reason || '录制文件还在生成中，请稍后再试');
          return;
        }
        setPlaying({
          fileId: file.id,
          kind,
          url,
          name: res.filename || file.filename || '会议录制',
        });
      } catch (e) {
        showFlash(humanError(e), true);
      } finally {
        setSigning(null);
      }
    },
    [meetingId, playing?.fileId, showFlash],
  );

  const download = useCallback(
    async (file: MeetingRecordFileView) => {
      setSigning(file.id);
      try {
        const res = await meetingRecordApi.fileUrl(meetingId, file.id);
        // ★下载优先用附件地址（带 attachment 响应头与可读文件名）；
        //   url 是老字段，等价于 downloadUrl，留着兜底。
        const url = res.downloadUrl || res.url;
        if (!url) {
          // ★不是错误：录音还在生成 / 存储未配置，后端给了人话原因
          showFlash(res.reason || '录制文件还在生成中，请稍后再试');
          return;
        }
        // ★锚点挂到<b>弹框所在的</b> document 上（会中窗口是另一份 document）：
        //   挂错了在某些浏览器里会被当成"后台页面发起的"而静默丢掉。
        const doc = rootRef.current?.ownerDocument ?? document;
        const a = doc.createElement('a');
        a.href = url;
        a.rel = 'noopener';
        a.download = res.filename || file.filename || 'meeting-recording';
        doc.body.appendChild(a);
        a.click();
        a.remove();
      } catch (e) {
        showFlash(humanError(e), true);
      } finally {
        setSigning(null);
      }
    },
    [meetingId, showFlash],
  );

  /** 复制整篇转写：与会中窗口共用同一份文档上下文（见 {@code lib/clipboard.ts} 文件头）。 */
  const copyTranscript = useCallback(
    async (t: MeetingTranscriptView) => {
      const text = transcriptPlainText(t.segments ?? []);
      if (!text) {
        showFlash('这份转写还没有文字内容', true);
        return;
      }
      const ok = await copyText(text, undefined, rootRef.current?.ownerDocument ?? undefined);
      showFlash(ok ? '转写文字已复制' : '复制失败，请手动选中复制', !ok);
    },
    [showFlash],
  );

  const doRemove = useCallback(async () => {
    setRemoving(true);
    try {
      await meetingRecordApi.remove(meetingId);
      /**
       * ★先广播再关框：会议栏的历史记录可能不是本次打开的入口（系统消息里也能打开
       * 这个弹框），靠回调只能覆盖一条路径 —— 广播才能让所有在看的列表都消失掉。
       */
      notifyMeetingRecordDeleted(meetingId);
      onDeleted?.();
    } catch (e) {
      showFlash(humanError(e), true);
      setConfirming(false);
    } finally {
      setRemoving(false);
    }
  }, [meetingId, onDeleted, showFlash]);

  return (
    <div className="mtg-window" ref={rootRef}>
      <header className="mtg-window-head">
        <span className="mtg-window-title" title={displayTitle}>
          {displayTitle}
        </span>
        <button type="button" className="mtg-window-btn" title="刷新" onClick={() => void load()}>
          刷新
        </button>
        <button type="button" className="mtg-window-x" title="关闭" aria-label="关闭" onClick={() => onClose?.()}>
          ×
        </button>
      </header>

      <div className="mtg-window-body">
        {loading && <div className="mtg-center mtg-empty-inline">正在加载会议详情…</div>}
        {!loading && error != null && (
          <div className="mtg-error">
            {error}
            <button type="button" className="mtg-btn" onClick={() => void load()}>
              重试
            </button>
          </div>
        )}
        {!loading && error == null && !meeting && (
          <div className="mtg-center mtg-empty-inline">这条会议记录已不存在</div>
        )}

        {!loading && error == null && meeting && (
          <>
            <div className="mtg-card">
              <div className="mtg-detail-head">
                <span className="mtg-icon">
                  {meeting.origin === 2 ? <IconPhone size={18} /> : <IconCallEntry size={18} />}
                </span>
                <div className="mtg-detail-head-main">
                  <div className="mtg-title">{displayTitle}</div>
                  <div className="mtg-meta">{meetingMetaText(meeting)}</div>
                </div>
                <Badge b={recordBadge(meeting.recordStatus)} />
              </div>

              <dl className="mtg-kv">
                <div>
                  <dt>会议号</dt>
                  <dd>{meetingDisplayRoom(meeting.roomName ?? detail?.roomName)}</dd>
                </div>
                <div>
                  <dt>状态</dt>
                  <dd>{meeting.statusText || statusFallback(meeting.status)}</dd>
                </div>
                <div>
                  <dt>开始时间</dt>
                  <dd>{meetingTimeText(meeting.startTime) || '—'}</dd>
                </div>
                <div>
                  <dt>结束时间</dt>
                  <dd>{meetingTimeText(meeting.endTime) || '—'}</dd>
                </div>
                <div>
                  <dt>时长</dt>
                  <dd>{meetingDurationText(meeting) || '—'}</dd>
                </div>
              </dl>

              <div className="mtg-detail-actions">
                {confirming ? (
                  <>
                    <span className="mtg-confirm-text">{deleteConfirmText(isHost)}</span>
                    <button
                      type="button"
                      className="mtg-btn"
                      onClick={() => setConfirming(false)}
                      disabled={removing}
                    >
                      取消
                    </button>
                    <button
                      type="button"
                      className="mtg-btn is-danger"
                      onClick={() => void doRemove()}
                      disabled={removing}
                    >
                      <IconTrash size={13} />
                      {removing ? '删除中…' : isHost ? '确认删除会议' : '确认删除'}
                    </button>
                  </>
                ) : (
                  <button
                    type="button"
                    className="mtg-btn is-danger"
                    onClick={() => {
                      if (meeting.status === 1) {
                        showFlash('会议还在进行中，请先「结束会议」再删除', true);
                        return;
                      }
                      setConfirming(true);
                    }}
                  >
                    <IconTrash size={13} />
                    {deleteActionLabel(isHost)}
                  </button>
                )}
              </div>
            </div>

            <Section title={`参会人（${detail?.members?.length ?? meeting.memberCount ?? 0}）`}>
              <div className="mtg-members">
                {(detail?.members ?? []).map((m: MeetingRecordMemberView, i: number) => (
                  <span className="mtg-member" key={`${m.userId ?? 'u'}-${i}`}>
                    {m.displayName || '未命名'}
                    {m.role === 2 && <em>主持人</em>}
                  </span>
                ))}
                {(detail?.members?.length ?? 0) === 0 && (
                  <span className="mtg-empty-inline">无参会人记录</span>
                )}
              </div>
            </Section>

            <Section title={`录制文件（${detail?.files?.length ?? 0}）`}>
              {/* ★播放器内嵌在详情里，不跳新页面：播放地址是现签的 inline 地址，
                  浏览器直接按对象类型解码，不会触发"另存为"。 */}
              {playing && (
                <div className="mtg-player">
                  <div className="mtg-player-head">
                    <span className="mtg-player-name" title={playing.name}>
                      {playing.name}
                    </span>
                    <button
                      type="button"
                      className="mtg-player-x"
                      title="关闭播放器"
                      aria-label="关闭播放器"
                      onClick={() => setPlaying(null)}
                    >
                      ×
                    </button>
                  </div>
                  {playing.kind === 'video' ? (
                    <video
                      key={playing.url}
                      className="mtg-player-media"
                      src={playing.url}
                      controls
                      autoPlay
                      playsInline
                      preload="metadata"
                    />
                  ) : (
                    <audio
                      key={playing.url}
                      className="mtg-player-media is-audio"
                      src={playing.url}
                      controls
                      autoPlay
                      preload="metadata"
                    />
                  )}
                </div>
              )}
              {(detail?.files?.length ?? 0) === 0 ? (
                <div className="mtg-empty-inline">
                  {meeting.recordStatus === 1
                    ? '录制进行中，结束后会自动保存到这里'
                    : '这场会议没有录制文件'}
                </div>
              ) : (
                <ul className="mtg-files">
                  {(detail?.files ?? []).map((f) => (
                    <li className="mtg-file" key={f.id}>
                      <span className="mtg-file-icon">
                        <IconFile size={16} />
                      </span>
                      <div className="mtg-file-main">
                        {/* ★展示名不是对象存储 key（见 recordingDisplayName 的注释）；
                            下载时仍用真实文件名（download() 里的 res.filename）。 */}
                        <div className="mtg-file-name">{recordingDisplayName(f.filename)}</div>
                        <div className="mtg-file-meta">
                          {[bytesText(f.sizeBytes), f.durationSec ? durationText(f.durationSec) : '']
                            .filter(Boolean)
                            .join(' · ') || '—'}
                          {f.error ? ` · ${f.error}` : ''}
                        </div>
                      </div>
                      <Badge b={fileBadge(f.status)} />
                      {playKind(f.status, f.contentType, f.filename) != null && (
                        <button
                          type="button"
                          className="mtg-btn"
                          disabled={signing === f.id}
                          onClick={() => void play(f)}
                        >
                          {signing === f.id ? '准备中…' : playing?.fileId === f.id ? '收起' : '播放'}
                        </button>
                      )}
                      {fileCanDownload(f.status) && (
                        <button
                          type="button"
                          className="mtg-btn"
                          disabled={signing === f.id}
                          onClick={() => void download(f)}
                        >
                          {signing === f.id ? '准备中…' : '下载'}
                        </button>
                      )}
                    </li>
                  ))}
                </ul>
              )}
            </Section>

            {/* ★转写单独一节：文件 READY 与转写完成是两条异步链路，
                能下载不代表文字已经出来，合并展示会让人以为"转写丢了"。 */}
            {(detail?.transcripts?.length ?? 0) > 0 && (
              <Section title={`会议转写（${detail?.transcripts?.length ?? 0}）`}>
                <div className="mtg-transcripts">
                  {(detail?.transcripts ?? []).map((t) => (
                    <TranscriptCard
                      key={t.id}
                      transcript={t}
                      sourceName={recordingDisplayName(
                        (detail?.files ?? []).find((f) => f.id === t.sourceFileId)?.filename ?? '',
                      )}
                      onCopy={() => void copyTranscript(t)}
                    />
                  ))}
                </div>
              </Section>
            )}
          </>
        )}
      </div>

      {flash && <div className={`mtg-window-flash${flash.fail ? ' is-fail' : ''}`}>{flash.text}</div>}
    </div>
  );
}

// ---------------------------------------------------------------- 小组件

function Badge({ b }: { b: { text: string; tone: string } }) {
  return <span className={`mtg-badge mtg-badge-${b.tone}`}>{b.text}</span>;
}

function Section({ title: t, children }: { title: string; children: ReactNode }) {
  return (
    <div className="mtg-section">
      <div className="mtg-section-title">{t}</div>
      {children}
    </div>
  );
}

/**
 * 一份录制的转写卡片。
 *
 * <p>★未完成时只给一句「在做什么」，不显示句子 —— 后端在完成前不下发
 * {@code segments}，前端也不该用「0 句」去暗示"已经识别完但没内容"。
 */
function TranscriptCard({
  transcript,
  sourceName,
  onCopy,
}: {
  transcript: MeetingTranscriptView;
  sourceName: string;
  onCopy: () => void;
}) {
  const segments = transcript.segments ?? [];
  const done = transcriptIsDone(transcript.status);
  const labels = speakerLabels(segments);
  const failed = transcriptBadge(transcript.status).tone === 'failed';
  // 连续同一个人只显示一次说话人名，避免每句都顶一个蓝色标签。
  let prevSpeaker: string | null = null;

  return (
    <div className="mtg-transcript">
      <div className="mtg-transcript-head">
        <span className="mtg-transcript-src" title={sourceName}>
          {sourceName}
        </span>
        <Badge b={transcriptBadge(transcript.status)} />
        {done && segments.length > 0 && (
          <button type="button" className="mtg-btn" onClick={onCopy}>
            复制全文
          </button>
        )}
      </div>

      {done ? (
        segments.length === 0 ? (
          <div className="mtg-transcript-note">这段录制里没有识别到语音内容</div>
        ) : (
          <>
            <div className="mtg-transcript-meta">{transcriptSummary(transcript)}</div>
            <ol className="mtg-segs">
              {segments.map((s, i) => {
                const name = speakerNameOf(labels, s.speakerId);
                const showName = name !== prevSpeaker;
                prevSpeaker = name;
                return (
                  <li className="mtg-seg" key={`${i}-${s.beginMs ?? 0}`}>
                    <span className="mtg-seg-time">{timelineText(s.beginMs)}</span>
                    <span className="mtg-seg-main">
                      {showName && <span className="mtg-seg-speaker">{name}</span>}
                      <span className="mtg-seg-text">{s.text}</span>
                    </span>
                  </li>
                );
              })}
            </ol>
          </>
        )
      ) : (
        <div className={`mtg-transcript-note${failed ? ' is-fail' : ''}`}>{transcriptNote(transcript)}</div>
      )}
    </div>
  );
}

/**
 * 未完成时的说明文案。
 *
 * <p>★不渲染服务端 {@code error} 原文：那里可能有 ffmpeg 输出、对象存储路径 ——
 * 用户要的是"接下来会怎样"，不是排查日志（同 {@code lib/stt.ts} 的文案纪律）。
 */
function transcriptNote(t: MeetingTranscriptView): string {
  switch (t.status) {
    case 1:
      return '录制已保存，稍后会自动从视频里提取音频';
    case 2:
      return '正在从录制里提取音频…';
    case 3:
      return '音频已就绪，排队等待识别';
    case 4:
      return '正在识别语音并区分说话人，时间较长的会议需要几分钟';
    case 6:
      return '这份录制没能转成文字，可以稍后刷新再看';
    case 7:
      // 两种跳过：没有音轨，或有人声轨但识别不出说话内容（静音会议）。
      return '这份录制里没有可转写的声音';
    default:
      return '暂未开始转写';
  }
}

function statusFallback(status?: number): string {
  switch (status) {
    case 0:
      return '未开始';
    case 1:
      return '进行中';
    case 2:
      return '已结束';
    case 3:
      return '已取消';
    default:
      return '—';
  }
}

/** 会议号：9 位按 3-3-3 分组展示（与列表/会中口径一致）。 */
function meetingDisplayRoom(room?: string | null): string {
  return formatMeetingId(room ?? '') || '—';
}
