import { useEffect, useMemo, useRef, useState } from 'react';
import { Select, Spin, Tag, Typography } from 'antd';
import { contactApi } from '../api';
import type { AgentSearchItem } from '../api/types';
import { SUBJECT_TYPE, contactTitle } from '../lib/contact';
import {
  dropLocalDuplicatedAgents,
  mergeLocalFirst,
  pickHintOption,
  pickMyContacts,
} from '../lib/contactPicker';
import { useChatStore } from '../store/chat';

/**
 * ★智能体远程搜索选择器 —— 「添加伙伴」弹窗**智能体 Tab** 的选人入口。
 *
 * <h2>★★它返回的值可以直接喂给 {@code contactApi.add}</h2>
 *
 * <p>选项的 {@code value} 就是智能体的 **subject id**（服务端编码过），
 * 与真人 Tab 的 {@code UserSearchSelect} 产出的是**同一种值**。
 * 于是「加为联系人 / 发消息」两条提交路径**完全不用分叉** ——
 * 这正是服务端 {@code AgentSearchItem.userId} 沿用同名字段的用意。
 *
 * <p>★★**不要**在这里做"智能体的 id 要减掉 10^12"之类的还原：
 * 段位阈值是可调的，抄到前端后某天调整段位，这里会**静默失效**
 * （把智能体当成人加到通讯录里，不报错）。类型判断一律看服务端的
 * {@code subjectType}（见 {@code lib/contact.ts} 的 {@code SUBJECT_TYPE}）。
 *
 * <h2>★防抖 300ms / 空关键字不发请求</h2>
 *
 * <p>与 {@code UserSearchSelect} 同款（理由见那个组件的注释）：
 * 逐字符直打会产生一串只被最后一次用到的请求，而**空关键字返回全部可见智能体**
 * ——那是一次没有 UI 承载的全量查询。
 *
 * <h2>★★空结果有两种意思，文案必须分开</h2>
 *
 * <p>服务端的 {@code degraded=true} 表示"我们没问成"（内网凭据没配 / 平台不可用），
 * 与"真的没有匹配"完全是两件事。统一说成"没有找到相关智能体"的话，
 * 用户会去改关键字、改到怀疑自己 —— 而真正该做的是找运维配 key。
 * ⇒ 降级时显示一句**弱提示**（不是红色报错：少配一个环境变量不是故障）。
 */
/**
 * ★★DEV-256（用户原话「可以添加用户，也可以添加智能体」）：本组件现在<b>两种形态</b>，
 * 由 {@code multiple} 决定 —— 但**交出去的东西不一样**，这是刻意的。
 *
 * <table border="1">
 *   <tr><th></th><th>回调</th><th>拿到什么</th><th>谁在用</th></tr>
 *   <tr><td>单选（默认）</td><td>{@code onChange}</td><td><b>整条 item</b></td>
 *       <td>「添加伙伴」—— 它要用 {@code subjectType} 打角标、用 {@code name} 写提示</td></tr>
 *   <tr><td>多选</td><td>{@code onChangeIds}</td><td><b>id 数组</b></td>
 *       <td>「添加群员」—— 提交给服务端的就是 id</td></tr>
 * </table>
 *
 * <p>★★<b>多选为什么不给 items</b>（这不是偷懒，是避开一个必然踩的坑）：
 * 选项列表来自<b>按关键字的一次搜索</b>（{@code items}）。用户搜「A」选一个、
 * 再搜「B」选一个时，{@code items} 已经换成 B 的结果 —— 若在这里用
 * {@code items.find(id)} 去还原已选项，<b>搜没了的那一个会凭空消失</b>，
 * 而组件看起来一切正常（选的框还在，只是交出去时少了人）。
 * ⇒ 与 {@code UserSearchSelect} 同款：多选路径只交出 id，调用方自己维护已选集合。
 *
 * <h2>★★DEV-355：{@code showMyContacts} —— 「从我的联系人里快速选择」（智能体那一半）</h2>
 *
 * <p>需求与规则与 {@code UserSearchSelect} <b>逐条相同</b>（那边有完整的来龙去脉：
 * 空关键字列本地、有关键字本地置顶 + 远程补全、上限 50 + 提示行、
 * 开关默认关闭以隔离「添加伙伴」、联系人没到手时的 fail-safe），
 * 差别只有一条：这里筛的是 {@code subjectType === AGENT} 的<b>智能体联系人</b>
 * （拍板③：两个 Tab 各自只列对应类型的联系人）。
 *
 * <p>★★<b>它为什么也需要这个开关</b>：智能体在平台侧<b>没有本地副本</b>必须走远程搜索
 * （见 {@code CreateGroupModal} 类注释），但用户<b>已经把某个智能体加为联系人</b>之后，
 * 它就成了"我的联系人"里的一行（{@code ContactItem.subjectType === 2}）——
 * 建群时想再拉它进群，同样不该让他凭记忆去搜。
 *
 * <p>★<b>不排除任何 id</b>（与「用户」Tab 不同：那边要排自己与已在群的人）——
 * 这是本组件本来的行为，本批<b>不改</b>：智能体的 subject id 是服务端编码的独立号段，
 * 不会与自己撞号；"已在群"那一格由服务端的 {@code memberResult} 回报。
 */

/**
 * ★选项的展示形态（远程搜索项与本地联系人项<b>共用同一份</b>，DEV-355 起抽出）。
 *
 * <p>★两条来源必须长得<b>一模一样</b>：用户看不出"这条是从我的联系人里来的"——
 * 对他而言这只是同一个智能体的两种找到方式（拍板①：一个控件，不切模式）。
 * ★抽成模块级函数还有一个具体好处：它不是 hook，调用它不改变组件里 hooks 的<b>顺序</b>。
 */
function agentOptionLabel(it: AgentSearchItem) {
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 6, overflow: 'hidden' }}>
      <span style={{ fontWeight: 500 }}>{it.name || '未命名智能体'}</span>
      <Tag color="blue" style={{ marginInlineEnd: 0 }}>
        智能体
      </Tag>
      {/* ★只给"仅团队空间可见"的加标注：Tenant（全租户）是常态，
          每个都标一遍等于没标；而用户确实需要知道某个智能体别人看不到。 */}
      {it.scope === 'Space' ? <Tag style={{ marginInlineEnd: 0 }}>仅团队可见</Tag> : null}
      {it.description ? (
        <Typography.Text type="secondary" ellipsis style={{ flex: 1, minWidth: 0, fontSize: 12 }}>
          {it.description}
        </Typography.Text>
      ) : null}
    </span>
  );
}

export default function AgentSearchSelect({
  value,
  onChange,
  onChangeIds,
  multiple = false,
  placeholder = '输入智能体名称或描述搜索',
  showMyContacts = false,
}: {
  /**
   * ★当前选中的 subject id（受控）。
   * ★多选时传<b>数组</b>；单选时可传单个值或 {@code null}（原调用方传的就是 {@code null}）。
   */
  value?: string | string[] | null;
  /** ★单选：把**整条**选中项交出去（见上表）。 */
  onChange?: (item: AgentSearchItem | null) => void;
  /** ★多选：交出当前选中的**全部** id（增量/全量由调用方按 antd 的语义理解为"全量"）。 */
  onChangeIds?: (ids: string[]) => void;
  /** ★默认 {@code false} = 保持原有的单选形态，「添加伙伴」一个字都不用改。 */
  multiple?: boolean;
  placeholder?: string;
  /**
   * ★★DEV-355：打开"空关键字先列出我的<b>智能体</b>联系人"（默认<b>关闭</b>，理由见类注释）。
   * ★与 {@code UserSearchSelect} 的同名开关是一对：同一个弹窗的两个 Tab 各开一个。
   */
  showMyContacts?: boolean;
}) {
  const isMulti = multiple === true;
  /**
   * ★把 antd 交回来的值归一成 id 数组（两种模式共用一条路径）。
   * ★必须容错 {@code ''}：antd 在"清空"时给的是 {@code undefined}，但历史上也见过空串，
   * 而空串会被当成一个合法的 subject id 提交上去（服务端按查不到的人处理）。
   */
  const toIds = (v: unknown): string[] => {
    if (Array.isArray(v)) return v.map((x) => String(x)).filter(Boolean);
    if (v == null || v === '') return [];
    return [String(v)];
  };
  const [keyword, setKeyword] = useState('');
  const [items, setItems] = useState<AgentSearchItem[]>([]);
  const [loading, setLoading] = useState(false);
  /** ★区分"还没搜"与"搜了没结果"（两种空态文案不同）。 */
  const [searched, setSearched] = useState(false);
  /** ★★平台侧不可用（"没问成"），与"没有匹配"分开表达。 */
  const [degraded, setDegraded] = useState(false);
  /**
   * ★★多选：{@code id → 名字} 的**累积**缓存（只增不减，一次会话内有效）。
   *
   * <p>要它是因为"已选项的展示名"和"已选项的来源列表"寿命不同：
   * {@code items} 每次搜索都被整份替换，而用户<b>已经选中的</b>那几个人必须继续显示名字。
   * 不缓存的后果很具体：选了「小明」再搜别的词，小明那个 tag 会变成一串
   * 他从没见过的<b>数字 id</b>（antd 找不到 option 时用 value 当标签）——
   * 用户会以为选错了人，而取消重选还是这样。
   *
   * <p>★写进 ref 只在 effect 的响应回调里（不在渲染期写），读在渲染期 —— 这是安全的。
   * ★单选路径完全不受影响（单选不需要跨搜索保留展示名：一次只有一个，且它当下就在列表里）。
   */
  const labelCache = useRef(new Map<string, string>());

  /** ★★DEV-355：本地"我的智能体联系人"要用的两样东西（与 UserSearchSelect 同款）。 */
  const contacts = useChatStore((s) => s.contacts);
  const loadContacts = useChatStore((s) => s.loadContacts);

  /**
   * ★★联系人还没到手时<b>补拉一次</b>（与 {@code UserSearchSelect} 逐条同款，
   * 那边写了完整理由：enterSession 会拉但此刻可能还没回来、store 没有"已加载"标记、
   * 用 {@code length} 而不是数组本身当依赖、失败吞掉、开关关闭时一行不执行）。
   */
  useEffect(() => {
    if (!showMyContacts) return;
    if (contacts.length > 0) return;
    void loadContacts().catch(() => undefined);
  }, [showMyContacts, contacts.length, loadContacts]);

  /**
   * ★★本地的智能体联系人（拍板③的另一半：这里只筛 {@code subjectType === AGENT}）。
   *
   * <p>★转成 {@link AgentSearchItem} 的形状而不是另造一种候选类型 —— 这样它能与
   * 远程结果走<b>同一条</b> label 渲染与单选还原路径（下面 {@code onChange} 就是靠这个
   * 把"从本地选的那一个"也找回来的）。
   * ★{@code description}/{@code scope} 天然缺席（联系人那一行没有这两个字段），
   * 渲染时自然不显示 —— <b>不是</b>占位成空串。
   * ★{@code name} 用 {@link contactTitle}（与智联录同一把尺子：备注 &gt; 昵称 &gt; 账号名，
   * 且名字后面带「（账号）」消歧）—— 用户在智联录里看到的名字，在这里必须一模一样。
   */
  const localPick = useMemo(() => {
    if (!showMyContacts) return { items: [] as AgentSearchItem[], remaining: 0 };
    const r = pickMyContacts(contacts, { subjectType: SUBJECT_TYPE.AGENT, keyword });
    const localItems = r.items.map((c) => ({
      userId: c.userId,
      subjectType: c.subjectType,
      name: contactTitle(c),
      avatar: c.avatar,
    }));
    // ★★DEV-355 修复：本地那一行的 userId 是 subject id，远程那一行是引用令牌 ——
    //   两侧 id 不同空间，靠 value 去重配不上，同一个智能体会露出两行（用户实测截图）。
    //   ⇒ 按名字把"远程已经搜到"的本地项剔掉，远程那条留下（令牌两边都能提交）。
    return {
      items: dropLocalDuplicatedAgents(localItems, items),
      remaining: r.remaining,
    };
  }, [showMyContacts, contacts, keyword, items]);

  useEffect(() => {
    const kw = keyword.trim();
    if (!kw) {
      setItems([]);
      setSearched(false);
      setDegraded(false);
      setLoading(false);
      return;
    }
    setLoading(true);
    const timer = setTimeout(() => {
      contactApi
        .searchAgents(kw, 1, 20)
        .then((r) => {
          const list = r.items ?? [];
          setItems(list);
          // ★★DEV-256：把这一批的名字记进缓存（只增不减，见 labelCache 的注释）——
          //   用户选完再搜别的词时，已选 tag 靠它继续显示名字而不是 id。
          for (const it of list) {
            labelCache.current.set(String(it.userId), it.name || '未命名智能体');
          }
          setDegraded(r.degraded === true);
          setSearched(true);
        })
        .catch(() => {
          // ★失败不弹错（与 UserSearchSelect 同款）：搜索是输入过程中的辅助动作，
          //   逐次报错会刷屏。★但这里把它标成 degraded —— 请求失败与"没搜到"
          //   对用户是两回事，前者不该显示"没有找到相关智能体"。
          setItems([]);
          setDegraded(true);
          setSearched(true);
        })
        .finally(() => setLoading(false));
    }, 300);
    // ★清理：关键字变了就取消上一次定时（否则快速输入会打出一串请求，
    //   后到的旧响应会覆盖新响应 —— 经典的"搜索结果对不上输入"）。
    return () => {
      clearTimeout(timer);
      setLoading(false);
    };
  }, [keyword]);

  const options = items.map((it) => ({ value: String(it.userId), label: agentOptionLabel(it) }));
  /** ★本地智能体联系人的选项（开关关闭时是空数组 —— 界面上"本地"这一层整体不存在）。 */
  const localOptions = localPick.items.map((it) => ({ value: String(it.userId), label: agentOptionLabel(it) }));

  const selectedIds = toIds(value);
  /**
   * ★★DEV-355：基准列表 = 【本地置顶 + 远程补全】（拍板①）。
   * ★开关关闭时 {@code base === options} —— 逐字回到本批之前的行为。
   */
  const base = showMyContacts ? mergeLocalFirst(localOptions, options) : options;
  /**
   * ★真正交给 antd 的选项 = 上面的基准列表 + **已选但不在列表里**的那些（用缓存名兜底）。
   * ★只对多选做（单选没有"选完又搜别的词"这种状态：换关键字时选中项也换了）。
   */
  const baseIds = new Set(base.map((o) => o.value));
  const carryOver = isMulti
    ? selectedIds
        .filter((id) => !baseIds.has(id))
        // ★缓存里也没有时回落显示 id —— 这是**能看见**的降级（一个数字），
        //   比回落成空字符串或"未知智能体"强：至少能对上服务端日志里的那个 id。
        .map((id) => ({ value: id, label: labelCache.current.get(id) ?? id }))
    : [];
  /**
   * ★截断提示行（拍板④），放在<b>整个列表的最末</b> —— 它在语义上是"后面还有"。
   * ★只对多选做：单选形态是「添加伙伴」那条路，本批刻意不碰它（拍板⑤）。
   */
  const hint = showMyContacts && isMulti ? pickHintOption(localPick.remaining) : null;
  const mergedOptions = isMulti ? [...base, ...carryOver, ...(hint ? [hint] : [])] : base;

  return (
    <Select
      showSearch
      // ★选项是服务端搜出来的，本地再过滤一遍会与"服务端按名称 + 描述匹配"的规则打架
      //   （本地只比 label 渲染出来的文本）。★尤其描述被 ellipsis 截断后，
      //   本地过滤会认为"描述里有匹配"的项不匹配。
      filterOption={false}
      // ★多选形态给 antd 交 'multiple'；单选形态【必须传 undefined 而不是 'single'】——
      //   antd 对 mode='single' 的处理与"不传 mode"并不完全等价（它会渲染出可清空的单选框），
      //   而「添加伙伴」那边现在的外观是既有的、不该被这次改动碰到。
      mode={isMulti ? 'multiple' : undefined}
      // ★★受控值必须【按形态分别取】：
      //   多选 ⇒ 整份数组；单选 ⇒ 取第 0 个（antd 单选不认数组，传数组进来它一个字都渲染不出来）。
      //   ★注意这里用的 selectedIds 而不是裸 value：它已经把 '' 与 null 归一掉了
      //   （见 toIds 的注释），否则单选清空之后 antd 会把空串当成一个合法值回传。
      value={isMulti ? selectedIds : selectedIds[0]}
      onChange={(v) => {
        if (isMulti) {
          // ★★多选只交 id（理由见类注释的表）：antd 给的 v 就是 id 数组，
          //   这里【不做】 items.find 还原 —— 选了 A 再搜 B 时 items 已经换成 B 的结果，
          //   还原会让 A 静默消失。
          onChangeIds?.(toIds(v));
          return;
        }
        // ★单选路径逐字保持原样：把**整条 item**交出去。
        //   ★items.find 找不到时交 null（不是 undefined）—— 调用方按 null 清空选中。
        // ★★DEV-355：查找范围扩到【远程 + 本地】。开关关闭时 localPick.items 恒为空 ⇒
        //   逐字等价于原来那句。★不扩的话，将来若有人开着开关用单选形态，
        //   从本地候选选中的那个会回落成 null（= 看起来"点了没反应"）。
        onChange?.(
          [...items, ...localPick.items].find((it) => String(it.userId) === String(toIds(v)[0])) ?? null,
        );
      }}
      onSearch={setKeyword}
      // ★★必须是 mergedOptions 不是 options：多选时"已选但不在本次搜索结果里"的那些
      //   要靠它才有 label 可渲染（否则 antd 回落把数字 id 当标签显示）。
      options={mergedOptions}
      placeholder={placeholder}
      style={{ width: '100%' }}
      notFoundContent={
        loading ? (
          <Spin size="small" />
        ) : degraded ? (
          <Typography.Text type="warning" style={{ fontSize: 12 }}>
            智能体资料暂不可用，请稍后再试
          </Typography.Text>
        ) : searched ? (
          '没有找到相关智能体'
        ) : (
          '输入关键词开始搜索'
        )
      }
    />
  );
}
