import { useEffect, useLayoutEffect, useRef, useState } from 'react';
// ★DEV-260：`App` 是为了 `App.useApp()` 的 message —— 理由与 ChatWindow.tsx:714 同一处：
//   antd v5 的静态方法拿不到主题/上下文，必须走 hook。
import { App as AntApp, Dropdown, Tooltip } from 'antd';
import AddPartnerModal from '../components/AddPartnerModal';
import ContactList from '../components/ContactList';
import ConvList from '../components/ConvList';
import ChatWindow from '../components/ChatWindow';
import CreateGroupModal from '../components/CreateGroupModal';
import JoinGroupModal from '../components/JoinGroupModal';
import MeetingPane from '../components/MeetingPane';
import MeetingDetailHost from '../lib/meetingDetailDialog';
import SearchPanel from '../components/SearchPanel';
import {
  IconGroupEnter,
  IconPlus,
  IconSearch,
  IconUserPlus,
  IconUsersPlus,
} from '../components/icons';
import type { Id } from '../api/types';
import { pendingIncomingCount } from '../lib/contact';
// ★★DEV-356：邀请链接弹确认框时替换掉「加入群组」那句默认说明（要说清群号是哪来的）。
import { INVITE_CONFIRM_HINT } from '../lib/groupInvite';
import { readInviteNo } from '../lib/meetingLink';
import { applyUnreadTitle } from '../lib/titleBadge';
import {
  CONV_WIDTH_DEFAULT,
  CONV_WIDTH_MIN,
  clampConvWidth,
  convWidthMax,
  isConvResizeEnabled,
  readConvWidth,
  saveConvWidth,
} from '../lib/convWidth';
import { useChatStore } from '../store/chat';

/**
 * ★左栏的三个 Tab：消息 / 会议 / 智联录。
 *
 * <p>★「会议」最初是第三位（用户当时原话「在智联录后面增加会议tab」）；2026-11-08
 * 用户改成**消息 会议 智联录** —— 会议提前到第二位，智联录垫底。
 * 它不只是"再加一个入口"，而是把原来藏在「+」菜单里的会议记录**抬到一级**
 * （见 {@code MeetingPane} 的文件头）。
 *
 * <p>★次序**只由下面 JSX 的 DOM 顺序决定**：`.conv-tabs` 里没有 `order` 之类的
 * CSS 重排，所以改次序 = 移动这两个按钮，别去动样式表。
 */
type PaneTab = 'messages' | 'contacts' | 'meetings';

const BADGE_MAX = 99;
const badgeText = (n: number): string => (n > BADGE_MAX ? `${BADGE_MAX}+` : String(n));

export default function ChatPage() {
  // ★★DEV-254 需求③：这里原有 `const activeConvId = useChatStore((s) => s.activeConvId);`，
  //   它的唯一读点就是被删掉的那个 MemberDrawer 挂载点（`convId={activeConvId}`）。
  //   ★必须一起删：`noUnusedLocals` 会让构建直接失败（TS6133），
  //     而且留一个没人读的 selector 会让下一个改动者以为页面上还有人在用当前会话。
  const selectConv = useChatStore((s) => s.selectConv);
  // ★DEV-260：应用内浮层用它弹（见下面 contactApplyNotice 那条 effect）。
  const { message: toast } = AntApp.useApp();

  // ---------------------------------------------------------------- 左栏拖宽
  /*
   * ★用户要求：会话列表与聊天区之间的分隔线可以左右拖动。
   *
   * <p>宽度真源分两层，别混：
   * <ul>
   *   <li>{@code desiredWidthRef} = 用户**想要**的宽度（落 localStorage）。窗口缩小被
   *       临时压窄时它不变 —— 窗口再变宽要恢复，而不是把用户的偏好在一次 resize 里抹掉；</li>
   *   <li>{@code convWidth} = 当前**实际**宽度（已按容器 clamp）。拖动过程中直接改
   *       CSS 变量、**不**每帧 setState：{@code ChatPage} 的子组件里有整个会话列表，
   *       每帧重渲染会在快速拖动时掉帧。</li>
   * </ul>
   *
   * <p>★首屏不闪：{@code index.html} 的启动骨架也读同一个 localStorage 键并写同一个
   * CSS 变量（见那边的内联脚本）。这里再写一次是幂等的 —— 两处取值必须同源。
   */
  const layoutRef = useRef<HTMLDivElement>(null);
  const convPaneRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{
    pointerId: number;
    startX: number;
    startWidth: number;
    width: number;
  } | null>(null);
  const [savedWidth] = useState(readConvWidth);
  const desiredWidthRef = useRef(savedWidth);
  const [containerWidth, setContainerWidth] = useState(() =>
    typeof window === 'undefined' ? 1280 : window.innerWidth,
  );
  const [convWidth, setConvWidth] = useState(() =>
    clampConvWidth(savedWidth, typeof window === 'undefined' ? 1280 : window.innerWidth),
  );
  const [resizing, setResizing] = useState(false);
  /**
   * ★悬停意图（hover intent）延迟：鼠标只是快速划过分隔条时**不改变光标形状**。
   * 手柄命中区有 8px，用户从会话列表扫向聊天区时会短暂压过它；若立刻把光标变成
   * col-resize，每次横穿页面都闪一下，反而像卡顿（用户反馈：「快速划过时不要变形」）。
   * ⇒ 停留超过 {@link CONV_HOVER_INTENT_MS} 才认作"想拖"，此时再给左右箭头光标；
   *   快速穿过时计时器会被 pointerleave 取消，光标始终是默认箭头。
   * ★按下时无论如何都会进入拖动态（body.conv-resizing 全局锁 col-resize），
   *   所以即使手速很快、悬停没到阈值，真正拖起来也有明确反馈。
   */
  const CONV_HOVER_INTENT_MS = 150;
  const [hoverArmed, setHoverArmed] = useState(false);
  const hoverTimerRef = useRef<number | null>(null);
  const cancelHoverIntent = () => {
    if (hoverTimerRef.current !== null) {
      window.clearTimeout(hoverTimerRef.current);
      hoverTimerRef.current = null;
    }
  };
  const onResizerEnter = () => {
    if (!resizeEnabled || dragRef.current) return;
    cancelHoverIntent();
    hoverTimerRef.current = window.setTimeout(() => {
      hoverTimerRef.current = null;
      setHoverArmed(true);
    }, CONV_HOVER_INTENT_MS);
  };
  const onResizerLeave = () => {
    cancelHoverIntent();
    setHoverArmed(false);
  };
  const resizeEnabled = isConvResizeEnabled(containerWidth);
  const widthMax = convWidthMax(containerWidth);

  /** 把"当前宽度"落到 CSS 变量上 —— 启动骨架、真界面与拖拽手柄读的是同一个值。 */
  const applyConvWidth = (width: number) => {
    document.documentElement.style.setProperty('--conv-pane-width', `${width}px`);
  };

  // ★必须在 paint 前同步：否则首次渲染会按默认 250 画一帧再跳到保存值。
  useLayoutEffect(() => {
    applyConvWidth(convWidth);
  }, [convWidth]);

  // 量真实容器宽度（IM 可能嵌在任意宽度的宿主里），并跟随宿主 resize 更新。
  useLayoutEffect(() => {
    const el = layoutRef.current;
    if (!el) return;
    const measure = () => setContainerWidth(el.clientWidth || window.innerWidth);
    measure();
    if (typeof ResizeObserver === 'undefined') {
      window.addEventListener('resize', measure);
      return () => window.removeEventListener('resize', measure);
    }
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // 容器变化时只改"实际宽度"，不动用户偏好：缩窄再放大能回到用户拖过的那一档。
  useLayoutEffect(() => {
    const next = clampConvWidth(desiredWidthRef.current, containerWidth);
    setConvWidth(next);
    applyConvWidth(next);
  }, [containerWidth]);

  // 拖到一半组件被卸载（切路由/关闭弹层）时别把全局光标留在 col-resize；
  // 悬停计时器也要清掉，避免卸载后 setState。
  useEffect(
    () => () => {
      document.body.classList.remove('conv-resizing');
      if (hoverTimerRef.current !== null) window.clearTimeout(hoverTimerRef.current);
    },
    [],
  );

  const startResize = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!resizeEnabled) return;
    cancelHoverIntent();
    setHoverArmed(false);
    const startWidth = convPaneRef.current?.getBoundingClientRect().width ?? convWidth;
    dragRef.current = {
      pointerId: e.pointerId,
      startX: e.clientX,
      startWidth,
      width: startWidth,
    };
    e.currentTarget.setPointerCapture(e.pointerId);
    e.preventDefault();
    setResizing(true);
    // ★整页锁光标与选中：拖到聊天区上方时不能变成选中文字/出现 I-beam。
    document.body.classList.add('conv-resizing');
  };

  const moveResize = (e: React.PointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== e.pointerId) return;
    const next = clampConvWidth(drag.startWidth + e.clientX - drag.startX, containerWidth);
    drag.width = next;
    applyConvWidth(next);
  };

  const endResize = (e: React.PointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== e.pointerId) return;
    dragRef.current = null;
    setResizing(false);
    document.body.classList.remove('conv-resizing');
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
    desiredWidthRef.current = drag.width;
    setConvWidth(drag.width);
    saveConvWidth(drag.width);
  };

  const resetConvWidth = () => {
    if (!resizeEnabled) return;
    const next = clampConvWidth(CONV_WIDTH_DEFAULT, containerWidth);
    desiredWidthRef.current = next;
    setConvWidth(next);
    saveConvWidth(next);
  };

  const resizeByKeyboard = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!resizeEnabled) return;
    const step = e.shiftKey ? 32 : 16;
    let delta = 0;
    if (e.key === 'ArrowLeft') delta = -step;
    else if (e.key === 'ArrowRight') delta = step;
    else if (e.key === 'Enter') {
      e.preventDefault();
      resetConvWidth();
      return;
    } else return;
    e.preventDefault();
    const next = clampConvWidth(convWidth + delta, containerWidth);
    desiredWidthRef.current = next;
    setConvWidth(next);
    saveConvWidth(next);
  };

  const loadContacts = useChatStore((s) => s.loadContacts);
  const loadMyGroups = useChatStore((s) => s.loadMyGroups);
  // ★★DEV-231 需求②（用户原话「会话列表顶部智联录左边的消息上不需要出现红色新消息数字」）：
  //   **「消息」Tab 上的那个总未读徽标已删**。
  //   ★只删这一个 —— 「智联录」那个（下面的 `pendingIncoming`）**保留**：
  //     用户说的是"智联录**左边**的消息上"，指的就是紧挨着智联录左侧那个。
  //   ★★不加"未读为 0 就把值置 0"之类的小动作 —— 用户要的是**这个位置没有数字**，
  //     不是"数字好看一点"。每个会话自己的未读红点（`.conv-item` 的 `.unread-dot`）
  //     不在此列，那个仍在。
  //
  // ★★DEV-374：这一条**原本接着写**「所以这里不再订阅 `unreadTotal`」——那句话现在
  //   <b>作废了</b>，必须删掉，否则下一个改动者会照着它把标题那条订阅当成违规删除。
  //   ★两件事要分开看，它们只是恰好在同一行代码上：
  //     ① 「Tab 上的徽标」——仍然<b>没有</b>，一个字没变；
  //     ② 「要不要订阅 `unreadTotal`」——<b>要</b>，因为标签页标题改口径后
  //        它成了唯一真源（见下面 `unreadTotal` 那段的长注释）。
  //   ★原来那个"删掉订阅而不是留着不用（noUnusedLocals 会构建失败）"的理由
  //     现在不适用了：这个值<b>有</b>读点，就是标题。
  // ★红点只数"他申请加我"（status=2）：自己发出的申请也亮的话，
  //   红点会一直挂着直到对方操作，用户点进去却无事可做 —— 那种红点等于噪音。
  //   ★★DEV-374：它现在<b>只</b>服务于「智联录」Tab 上那个徽标（无头值勿删）。
  const pendingIncoming = useChatStore((s) => pendingIncomingCount(s.contacts));

  /**
   * ★★DEV-259（用户原话「现在用户没有在消息界面时，没法通知到用户有新消息」）：
   * 写进<b>标签页标题</b>的未读数。
   *
   * <h2>★★DEV-374 口径：<b>直接读服务端</b>的 {@code unreadTotal}</h2>
   *
   * <p>★取数从"本地 {@code convs} 红点求和"换成"服务端那一个数"。这一改把
   * <b>两轮</b>口径调整收口到同一个终点上：
   * <ol>
   *   <li><b>DEV-372</b>（用户拍板）：标题要与<b>宿主角标</b>（{@code window.__im} 的
   *       {@code onUnreadChange}，来源就是 {@code /unread-total}）
   *       <b>完全相等</b>。当时的做法是"在本地求和时把服务端的两项口径补上"
   *       ——{@code filter((c) => !c.dnd)} 补免打扰、{@code + pendingIncomingCount(...)}
   *       补联系人申请数。那是一次<b>对齐</b>，但仍是"两套算法算同一个数"。</li>
   *   <li><b>DEV-374</b>（本批）：<b>不装了，两边读同一个源</b>。
   *       用户原话「改读服务端未读总数（推荐）—— 准，且与宿主角标同源」。</li>
   * </ol>
   * ⇒ 于是 {@code lib/imBridge.ts} 那句「与 IM 自己在浏览器标题上显示的那个角标
   * 同一个数」<b>第一次在实现上成真</b>（以前只是"算出来恰好相等"）。
   *
   * <h3>★★为什么 DEV-374 必须换掉本地求和（不只是"更准"）</h3>
   * <p>本批给会话列表加了<b>游标分页</b>：本地 {@code convs} 从此<b>不再等于全部会话</b>，
   * 而只是"已经加载的那几页"。本地求和的两个症状都是用户能直接看到的：
   * <ul>
   *   <li>恒<b>偏小</b>—— 还没滚到的那些页里的未读一条都没算进去；</li>
   *   <li>并且会<b>随滚动跳变</b>—— 往下滚一次，标题上的数字自己涨一截。
   *       这比"一开始就少一点"更糟：它看起来像新消息来了。</li>
   * </ul>
   * 服务端的 {@code /unread-total} 是全量口径，与"手上加载了几页"无关 ⇒ 两个症状一起消失。
   *
   * <h3>★随之作废的旧理由（留档，别照它改回去）</h3>
   * <p>本段原来写着：「取数口径 = 会话列表里那些红点之和，<b>不是</b> {@code store.unreadTotal}」，
   * 理由是"标题必须与用户看到的红点对得上"。DEV-372 已经推翻了它（两个数字并排出现在
   * 同一屏上时，<b>不一致本身</b>就是最刺眼的 bug），DEV-374 是它的最终形态。
   * ★同理作废的还有 {@code :36-44} 那条「这里不再订阅 {@code unreadTotal}」。
   *
   * <h3>★刷新时机（本批不新增任何轮询）</h3>
   * <p>已有三处足够：进会话 {@code enterSession} 拉一次、
   * 收消息（{@code onMsgRecv} / 扇出）各一次、本地已读减数一次。
   * ★这里只是把<b>已经算好的那个数</b>写进标题，不触发任何请求。
   *
   * <h3>★为什么放在 {@code ChatPage} 而不是 {@code ChatWindow}</h3>
   * <p>右栏没有打开任何会话时 {@code ChatWindow} 是空态、根本不挂载，
   * 而"没打开会话"恰恰是未读最容易堆积的时候。
   *
   * <p>★为什么用 {@code useEffect} 而不是在 selector 里写：selector 必须是纯函数。
   * 而这里是副作用（改 {@code document.title}），放在 effect 里才是它该待的地方。
   * ★selector 只返回一个 number：{@code useChatStore} 按<b>返回值</b>做 {@code Object.is}
   * 比较，返回数字才不会每次 store 变化都重渲染 —— 与改之前那条求和的理由相同。
   */
  const unreadTotal = useChatStore((s) => s.unreadTotal);
  useEffect(() => {
    applyUnreadTitle(unreadTotal);
  }, [unreadTotal]);
  /**
   * ★离开 IM 页面时把标题还原。★两条 effect 刻意分开写（而不是让上面那条返回 cleanup）：
   * 合在一起的话，{@code unreadTotal} 每变一次都会先跑一遍 cleanup，
   * 于是每次变化都要先写回底板再写新值 —— 中间那一瞬虽然同帧内就被覆盖、
   * 用户看不见，但"卸载才还原"这件事会变得看不出来是在哪一句发生的。
   */
  useEffect(() => () => { applyUnreadTitle(0); }, []);

  const [tab, setTab] = useState<PaneTab>('messages');
  const [groupOpen, setGroupOpen] = useState(false);
  // ★DEV-226 需求⑪：「加入群组」从「智联录」搬到这里（用户原话：
  //   「会话列表上面的"+"：创建群组、加入群组、添加伙伴，加入群组为新增」）。
  //   搬家在用户眼里是"新建了一个入口"，在代码里其实是**同一个弹窗换了个挂载点**：
  //   JoinGroupModal 组件本身一行没改。
  const [joinOpen, setJoinOpen] = useState(false);
  /**
   * ★★DEV-356：地址栏带来的**邀请预填**（{@code ?invite=<群号>}）。
   *
   * <p>★与 {@link joinOpen} <b>分开</b>而不是共用一个 state：两者回答的是不同的问题 ——
   * {@code joinOpen} 是"这个弹窗要不要显示"（用户点「+ → 加入群组」也会把它置真），
   * 而这里是"显示时框里填什么、上面那句话怎么说"。合成一个的话，
   * 用户点开「加入群组」时会看到<b>上一次邀请的群号还留在框里</b>。
   *
   * <p>★非 null = 邀请弹窗打开中；关掉与进群（{@code onJoined}）时都必须<b>一起清掉</b>
   * —— 只清 {@code joinOpen} 的话弹窗关不掉（{@code open} 是两者取或）。
   */
  const [inviteGroupNo, setInviteGroupNo] = useState<string | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  // ★★DEV-254 需求③：这里原有 `const [membersOpen, setMembersOpen] = useState(false);`，
  //   随右栏顶栏那个「群成员」图标按钮一起删除（连同下面 MemberDrawer 的挂载点）。
  const [partnerOpen, setPartnerOpen] = useState(false);
  /**
   * ★切 Tab。
   *
   * <p>★切到「智联录」时**顺手重拉一次**：通讯录是纯拉取型数据，
   * 不重拉的话，用户在「消息」Tab 待着的这段时间里收到的申请，
   * 要等到下一次登录才看得见。
   *
   * <p>★★DEV-260 修订：上面括号里原来写着
   * 「（后端没有对应的下行帧 —— 别人加你时不会有任何推送）」—— **这句本批起不再成立**。
   * 现在有 {@code CONTACT_UPDATE(8000)} 帧（见 {@code store/chat.ts} 的
   * {@code onContactUpdate}），别人加你时<b>会</b>推送。
   * ★留着这句过期注释的害处很具体：下一个改动者会据此认为
   * "广播那条路已经有人在做了，这里可以删"，而<b>不能删</b> ——
   * 这一句兜的是另一件事：<b>帧丢了的场景</b>（断线期间、或用户在别的设备上处理过），
   * 切进来重拉一次才是最终对齐。
   *
   * <p>★失败只吞掉不报错：重拉是"顺带刷新"，失败时列表里还是上一次的数据，
   * 比弹一个红条更不打扰（真正的失败会在用户主动操作时暴露出来）。
   *
   * <p>★DEV-165：「我的群聊」与联系人同一性质，一起重拉。
   * ★两次调用各自 catch：它们互不依赖，一个失败不该把另一个跳过。
   */
  const switchTab = (next: PaneTab) => {
    setTab(next);
    if (next === 'contacts') {
      loadContacts().catch(() => undefined);
      loadMyGroups().catch(() => undefined);
    }
  };

  /**
   * ★★会议邀请链接（`…/instant-message/?meeting=063575412`）⇒ 直接切到「会议」栏。
   *
   * <p>★为什么这件事必须在 ChatPage 做：会议栏是**按需挂载**的（切到那个 Tab 才渲染），
   * 用户在「消息」页点开邀请链接时 {@code MeetingPane} 根本还没挂载 —— 没人去读参数，
   * 他看到的就只是首页，"点了邀请链接没反应"。
   * 这里先切 Tab，会议栏挂载后自己把会议号填进「加入」弹窗（见 MeetingPane 的同名 effect）。
   *
   * <p>★只跑一次：参数由 MeetingPane 消费后从地址栏抹掉，
   * 这里若跟着重跑，用户手动切回「消息」会被立刻弹回会议栏。
   */
  useEffect(() => {
    if (readInviteNo(window.location.search)) switchTab('meetings');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ------------------------------------------------------------------ DEV-260
  // ★★两条"来自 store 的请求"，都靠 effect 消费 —— store 是普通模块，
  //   够不着本组件的 `tab` state，也够不着 antd 的 App context（见 store 里
  //   `contactApplyNotice` 的长注释）。信号发过来，动作在这里执行。
  // ------------------------------------------------------------------
  const contactApplyNotice = useChatStore((s) => s.contactApplyNotice);
  const consumeContactApplyNotice = useChatStore((s) => s.consumeContactApplyNotice);
  /**
   * ★收到联系人申请 ⇒ 弹一次应用内浮层（口径「desktop」里的中间那一档）。
   *
   * <p>★与桌面通知<b>互补不重复</b>：通知那条路要求页面失焦/不可见
   * （{@code lib/notify.ts} 的 {@code shouldNotify}），页面在前台时它<b>不弹</b>
   * —— 此时正是这条浮层在起作用。
   *
   * <p>★点一下就切到「智联录」：用户看到"某某申请加你"之后，
   * 下一步动作必然是去同意，让他自己再找一次入口是白费一步
   * （通知那条路的 {@code onOpen} 做的是同一件事，两条路必须一致）。
   */
  useEffect(() => {
    if (!contactApplyNotice) return;
    const close = toast.open({
      type: 'info',
      content: contactApplyNotice.body,
      // ★默认 3 秒对"有人加你"这种要用户做决定的事偏短：他很可能正低头打字，
      //   抬头时浮层已经没了，于是又回到"要自己点一次智联录才知道"。
      duration: 8,
      onClick: () => {
        close();
        switchTab('contacts');
      },
    });
    // ★弹完【立刻】清槽位，而不是等浮层自己关：组件重挂载（切走 Tab 再切回来
    //   不会卸载本组件，但热更新/路由变动会）时槽位还在就会再弹一遍，
    //   用户会以为对方申请了两次。
    consumeContactApplyNotice();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contactApplyNotice]);

  /**
   * ★★DEV-354：「带参数直达会话」的结果提示 —— 同款机制、同款理由（见上面
   * {@code contactApplyNotice} 那段）。
   *
   * <p>★<b>不是每一次直达都会弹</b>：绝大多数是成功且安静的（直接打开就是最好的反馈），
   * 只有三类会落槽位 —— 参数格式错、目标不存在/无权限、入群申请的回执。
   *
   * <p>★时长按 {@code level} 分档（错误留久一点）：一句"该会话不存在或无权限"
   * 默认 3 秒就消失的话，用户正好在这一刻低头看别处，回头就只剩一个默认会话，
   * 完全不知道发生了什么 —— 而"参数错了好排查"正是拍板⑤选这条路的理由。
   */
  const directOpenNotice = useChatStore((s) => s.directOpenNotice);
  const consumeDirectOpenNotice = useChatStore((s) => s.consumeDirectOpenNotice);
  useEffect(() => {
    if (!directOpenNotice) return;
    toast.open({
      type: directOpenNotice.level,
      content: directOpenNotice.text,
      duration: directOpenNotice.level === 'error' ? 6 : 4,
    });
    // ★弹完【立刻】清槽位（与 contactApplyNotice 同一条纪律）：组件重挂载时
    //   槽位还在就会再弹一遍，用户会以为那个错误发生了两次。
    consumeDirectOpenNotice();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [directOpenNotice]);

  /**
   * ★★DEV-356：邀请链接 ⇒ 弹「申请加入」确认框（**群号已预填**）。
   *
   * <p>★与上面两条同款机制、同款理由（store 够不着 antd 的 App context，
   * 只能"记下这件事"由本组件用 effect 消费）。
   *
   * <p>★★这里<b>只开弹窗、不发任何请求</b> —— 拍板选的是 {@code confirm}：
   * 用户点「申请加入」才会真的提交。他直接把弹窗关掉就是零请求、零写入
   * （这也是为什么本组件不需要"取消"这个动作 —— 关掉本身就是取消）。
   *
   * <p>★弹完【立刻】清槽位（与上面两条同一条纪律）：本组件重挂载时槽位还在
   * 就会再弹一遍，用户会以为"这个弹窗关不掉"。
   */
  const groupInviteRequest = useChatStore((s) => s.groupInviteRequest);
  const consumeGroupInviteRequest = useChatStore((s) => s.consumeGroupInviteRequest);
  useEffect(() => {
    if (!groupInviteRequest) return;
    setInviteGroupNo(groupInviteRequest.groupNo);
    consumeGroupInviteRequest();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [groupInviteRequest]);

  /**
   * ★桌面通知被点击 ⇒ 切到「智联录」（通知在 {@code store/chat.ts} 里发，
   * 那边没有 `tab` 这个东西，所以只递增一个序号过来）。
   *
   * <p>★判据是 {@code > 0} 而不是"变了就切"：初值就是 0，
   * 挂载时 effect 必然跑一次，不挡的话用户一进页面就被切到智联录。
   */
  const contactsOpenRequest = useChatStore((s) => s.contactsOpenRequest);
  useEffect(() => {
    if (contactsOpenRequest > 0) switchTab('contacts');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contactsOpenRequest]);

  /**
   * ★从「智联录」里点开某个人 ⇒ 切回「消息」Tab 并进入那条会话。
   *
   * <p>★必须切回去：不切的话用户停在智联录，看着"什么都没发生"，
   * 而会话其实已经在右栏打开了（右栏一直是可见的，只是他的注意力在左栏）。
   *
   * <p>★★DEV-278：尾巴上原来是 {@code .catch(() => undefined)}，与
   * {@code ConvList} 里那个是同一处缺陷 —— 切了 Tab、切了会话，而
   * {@code GET /conversations/{id}/messages} 一失败就<b>什么都没说</b>，
   * 用户看到的是右栏一段空白聊天记录。用户报的现象 2 就是这么来的（见 docs/05 DEV-278）。
   * ★本函数返回 {@code void}（三个调用方都是 {@code onOpenChat} 这类同步回调），
   * 所以只能在这里就地报告，不能像 {@code SearchPanel} 那样把 Promise 交出去。
   */
  const openConv = (convId: Id) => {
    setTab('messages');
    selectConv(convId).catch((e: unknown) => {
      toast.error(e instanceof Error && e.message ? e.message : '打开会话失败');
    });
  };

  /**
   * ★★DEV-177（用户口令「去掉已连接状态以及"断开 IM 连接"」）：本组件里的
   * <b>退出 / 断开</b>逻辑（{@code onLogout}）与<b>长连接状态点</b>（{@code dot}）已随
   * 「更多」按钮一起删除，两者的处置分开记在这里，因为它们<b>并不相同</b>：
   *
   * <ul>
   *   <li><b>长连接状态点</b>：UI 上不再显示，但连接态本身（{@code store.connState}）
   *       与重连逻辑<b>一行没动</b> —— 换句话说这是<b>纯展示层的移除</b>，
   *       断线重连、握手、背压全照旧。{@code components/connState.ts} 的映射表也保留着
   *       （现在没有消费点），要恢复展示直接 import 它即可，不必重新推导文案与配色。</li>
   *   <li><b>退出 / 断开</b>：{@code store.logout()} 这个 action 本身还在（登出流程、
   *       purge 缓存那套逻辑都没动），只是<b>界面上不再有入口</b>。
   *       ★这一条的后果必须说清楚：{@code mock} 模式下用户从此无法在页面里退出登录
   *       （清 localStorage 那条路只能靠清浏览器数据）；{@code platform} 模式下本来就
   *       "IM 没有退出登录这回事"（凭据是平台签发的同源 Cookie，IM 读不到也删不掉），
   *       所以平台侧<b>没有实际损失</b>。这是用户明确要求的结果，不是遗漏。</li>
   * </ul>
   *
   * <p>★删掉「更多」还有一个附带好处：顶栏右侧从 3 个按钮（70px）变成 2 个（46px），
   * 250px 下的余量从 1.23px 涨到约 25px（双 99+ 时）—— 但<b>这不构成删除的理由</b>，
   * 删除的理由只有用户那句话。宽度余量只是顺带变宽裕了。
   *
   * <p>★<b>DEV-231 需求② 之后的余量</b>：「消息」Tab 的总未读徽标已删 ⇒ 最坏情况
   * 从"双 99+"变成"单 99+"（只剩智联录那一颗），250px 下又多出约 25px。
   * ★上面那个 1.23px 是**历史读数**（DEV-177 当时的实测），保留原文不改写 ——
   * 它记录的是"当时为什么必须删「更多」"，不是当前状态。当前的余量已由
   * {@code scripts/verify-chat-tabs.mjs} 场景 3 盯住（`.conv-tab` 盒高恒为 24）。
   */

  return (
    <div className="chat-layout" ref={layoutRef} style={{ flex: 1, minHeight: 0 }}>
      <div className="conv-pane" ref={convPaneRef}>
        {/* ★DEV-159：#3 深色导航边栏（NavRail）已按用户要求去掉 —— IM 将来要嵌进
            别的页面，边栏该由宿主页面提供，不是我们自带一条。
            ★当时边栏里的功能全部收进这一行，其中**搜索**与**新建**留到现在。
            ★ DEV-177 起这一行只剩两个控件：搜索（原来那个汉堡图标本来只是个没有任何
              点击行为的装饰，换成真的搜索入口）与「+」新建下拉。
              **长连接状态点**与**断开/退出**已被用户要求移除 —— 见下方
              `.conv-header-actions` 之后那段说明，以及组件顶部 DEV-177 的利弊记录。
            ★DEV-160（「智联录」）：标题位置换成两个 Tab（消息 / 智联录），
            右侧「发起单聊 / 创建群聊」两个图标收进一个「+」下拉 ——
            这样右上角与原型图一致，且入口数量没有减少（多了一个 Tab 的容量）。 */}
        <div className="conv-header">
          <div className="conv-tabs" role="tablist">
            <button
              className={`conv-tab${tab === 'messages' ? ' active' : ''}`}
              role="tab"
              aria-selected={tab === 'messages'}
              onClick={() => switchTab('messages')}
            >
              {/* ★★DEV-231 需求②：这里原来有一个总未读徽标
                  （`{unreadTotal > 0 && <span className="conv-total-badge">…}`），**已删**。
                  ★「智联录」那一个（**最后一颗**按钮里的 `pendingIncoming`）**保留** ——
                    用户原话是"智联录**左边**的消息上"，指的是紧挨智联录的那一颗；
                    2026-11-08 次序调整后它仍在智联录按钮里（只是位置变成最后）。
                  ★`badgeText` / `BADGE_MAX` 仍然被智联录那一颗用着，所以留着；
                    删掉它俩会连带把智联录的徽标也弄坏（99+ 会退化成裸数字）。 */}
              消息
            </button>
            {/* ★第二个 Tab：会议（发起 / 加入 / 预约 + 历史记录）。
                ★★2026-11-08 用户要求把次序改成「消息 / 会议 / 智联录」⇒ 它从第三位
                  提前到这里；智联录垫底。**只动这两个按钮的顺序，宽度相关样式一个字没改。**
                ★宽度：三个 Tab 在 250px 下是**紧的**，`.conv-tab` 的字号与
                  `.conv-tabs` 的 gap 已按"三颗都放得下"重新算过（见 styles.css）。
                  ★判据仍是 `.conv-tab` 盒高恒为 24、`.conv-tabs` 横向溢出 0 ——
                  被挤扁时盒高会变成 72（flex 交叉轴拉伸的表征），
                  `scripts/verify-chat-tabs.mjs` 场景 3 盯的就是这个。 */}
            <button
              className={`conv-tab${tab === 'meetings' ? ' active' : ''}`}
              role="tab"
              aria-selected={tab === 'meetings'}
              onClick={() => switchTab('meetings')}
            >
              会议
            </button>
            {/* ★第三个 Tab：智联录（2026-11-08 起排在最后）。
                ★那颗未读申请徽标（`pendingIncoming`）跟着这一颗走，位置不因顺序调整而变。 */}
            <button
              className={`conv-tab${tab === 'contacts' ? ' active' : ''}`}
              role="tab"
              aria-selected={tab === 'contacts'}
              onClick={() => switchTab('contacts')}
            >
              智联录
              {pendingIncoming > 0 && <span className="conv-total-badge">{badgeText(pendingIncoming)}</span>}
            </button>
          </div>
          {/* ★DEV-176：这里原来是一个 `<span className="conv-title-space" />`（flex:1 的空占位）。
              删掉它换成 `.conv-header-actions { margin-left: auto }` —— **省下 10px**。
              为什么删掉一个"宽度为 0 的占位"能省 10px：那是 flex 的 gap。
              `.conv-header` 有 `gap: 10px`，只要有三个子项就是**两处** gap；
              占位被压到 0 宽时，**它两侧的 gap 不会跟着消失**，白白吃掉 20px。
              换成 `margin-left: auto` 之后同样是"把右侧按钮推到最右边"，
              但只剩**一处** gap（tabs ↔ actions）。在 250px 下这 10px 是决定性的。 */}
          <div className="conv-header-actions">
            <Tooltip title="搜索消息">
              <button className="icon-btn" onClick={() => setSearchOpen(true)}>
                <IconSearch size={17} />
              </button>
            </Tooltip>
            {/* ★「+」= 右上角的"新建"入口，两项都是**新建**动作（建群 / 加人）。
                ★DEV-177：用户要求「"+"不要背景」⇒ 它不再有浅蓝底，
                  外观与左边的搜索按钮一致（都走 .icon-btn 的默认样式）。
                  类名 conv-add-btn 保留 —— 它现在**没有任何独立样式**，
                  只作为语义锚点（也仍是 4 处浏览器脚本的定位器，见 styles.css 的说明）。 */}
            <Dropdown
              trigger={['click']}
              menu={{
                items: [
                  // ★DEV-201：「创建团队群组」→「创建群组」（用户要求）。
                  //   与 ChatWindow.tsx 单聊顶栏那个「+」是**同一个动作的两个入口**，
                  //   文案必须一致 —— 改一处漏一处就会出现两套叫法。
                  //   ★注意这里是**数组字面量内部**，只能用 `//` 行注释；
                  //   写成 `{/* … */}` 会被当成"一个只有注释的对象字面量"而直接语法报错
                  //   （tsc: TS1005 ',' expected）。JSX 的注释写法只在 JSX children 位置成立。
                  { key: 'group', icon: <IconUsersPlus size={15} />, label: '创建群组' },
                  // ★★DEV-226 需求⑪：「加入群组」插在**中间**，顺序照用户原话
                  //   （创建群组 / 加入群组 / 添加伙伴）。它从「智联录」搬来 ——
                  //   连带 ContactList 那一行入口与空态文案一起改（见该文件）。
                  //   ★图标 IconGroupEnter 是**新画的线性图标**，与上下两项同粗细；
                  //   别顺手换成 IconJoinRequestSolid（实心彩色，在这个菜单里会抢视线）。
                  { key: 'join', icon: <IconGroupEnter size={15} />, label: '加入群组' },
                  { key: 'partner', icon: <IconUserPlus size={15} />, label: '添加伙伴' },
                  // ★这个菜单只剩"新建"类动作：原来那项「会议记录」已经**删掉**，
                  //   它变成了左栏第三个 Tab（「会议」，见 PaneTab 的注释）——
                  //   同一个东西留两个入口，用户只会问"哪个才是真的"。
                ],
                onClick: ({ key }) => {
                  if (key === 'group') setGroupOpen(true);
                  if (key === 'join') setJoinOpen(true);
                  if (key === 'partner') setPartnerOpen(true);
                },
              }}
            >
              <button className="icon-btn conv-add-btn" aria-label="新建">
                {/* ★光学校准：两者名义描边都是 1.7（见 icons.tsx 的 base()），但 17px 下
                    实际只有 1.2px；搜索的圆弧会跨两个像素抗锯齿，而加号的横竖线常常
                    正好落在像素边界上，只剩 1px 实色 ⇒ 看起来明显更细（用户反馈
                    「加号比搜索框太细了点」）。这里单独把加号描边提到 2，让它与搜索
                    图标的视觉重量一致；不要改 icons.tsx 的全局默认值，其它场景的加号
                    没有这个并排参照。 */}
                <IconPlus size={17} strokeWidth={2} />
              </button>
            </Dropdown>
            {/* ★★DEV-177：这里原来是一个「更多」下拉（内含「长连接：{状态}」与
                「断开 IM 连接」/「退出登录」两项），用户要求一并去掉，已删。
                它的全部内容就是那两项 ⇒ 菜单空了，按钮留着只会点开一个空白面板，
                所以**按钮本身也一起删**（这一步是我的判断，不是用户逐字要求的）。
                ★连带影响与「恢复起来麻不麻烦」写在组件顶部那段注释里。 */}
          </div>
        </div>
        {tab === 'messages' && <ConvList />}
        {tab === 'contacts' && <ContactList onOpenChat={openConv} />}
        {tab === 'meetings' && <MeetingPane />}
      </div>

      {/* ★左栏宽度拖拽手柄：**绝对定位**，不占 flex 宽度 ——
          否则真界面会比启动骨架多出几 px，摘骨架时整块聊天区会横移一下。
          ★只在容器够宽时渲染；容器的 min 宽度判据见 lib/convWidth.ts。
          ★双击恢复默认 250；键盘左右箭头（Shift 加 32）也能调。 */}
      {resizeEnabled && (
        <div
          className={`conv-resizer${resizing ? ' dragging' : ''}${hoverArmed && !resizing ? ' hover-armed' : ''}`}
          role="separator"
          aria-orientation="vertical"
          aria-label="调整会话列表宽度"
          aria-valuemin={CONV_WIDTH_MIN}
          aria-valuemax={widthMax}
          aria-valuenow={convWidth}
          tabIndex={0}
          title="左右拖动调整会话列表宽度，双击恢复默认"
          onPointerEnter={onResizerEnter}
          onPointerLeave={onResizerLeave}
          onPointerDown={startResize}
          onPointerMove={moveResize}
          onPointerUp={endResize}
          onPointerCancel={endResize}
          onKeyDown={resizeByKeyboard}
          onDoubleClick={resetConvWidth}
        />
      )}

      {/* ★★DEV-258：右栏顶部那个「+」菜单里原有的建群/加人两项已删除
          （用户原话：「聊天页面上不需要创建群组和添加伙伴」）⇒ {@code ChatWindow}
          不再需要这两个回调，本文件对它的接线到此为止。
          ★左栏 .conv-header 那三个入口（创建群组 / 加入群组 / 添加伙伴）与下面
            CreateGroupModal / AddPartnerModal 的挂载点**逐字未变** ——
            用户 2026-09-16 那条"不许动左栏"的要求仍然有效，
            ★而且现在左栏是这些功能的**唯一**入口（删的是重复入口，不是功能）。 */}
      <ChatWindow />

      {/* ★★会议详情是<b>页面内弹框</b>（用户 2026-11-07 最终口径：「不是新浏览器窗口弹框，
          页面内弹框」）。宿主只在这里挂一次，两个入口（会议栏历史 / 系统消息
          「查看会议记录」）都通过 lib/meetingDetailDialog.tsx 的 openMeetingDetail 打开。 */}
      <MeetingDetailHost />

      {/* ★★DEV-254 需求③（用户原话「见附件红色圈起来的不需要」）：
          这里原有 {@code <MemberDrawer>} 的挂载点 —— 它是右栏顶栏那个「群成员」图标按钮
          （本批已删）唯一能打开的东西，入口没了它就成了**点不开的浮层**，所以一并摘掉。
          ★配套删掉的还有 `membersOpen` state 与上面对 `ChatWindow` 的 `onShowMembers` 传参。
          ★★功能一件没少：成员名单、用户卡片、卡片的「发消息」全在
            {@code MemberPanelBody} 里，而**页内版** {@code ChatMembersPanel}
            与浮层版 {@code MemberDrawer} 共用同一个内容体（见 ChatMembersPanel 的类注释）——
            现在走的是「成员」标签那条路（DEV-250 起的侧栏形态）。
          ★`MemberDrawer.tsx` 文件保留（含它那段"发消息要先关抽屉再切会话"的纪律注释）：
            它与页内版共用内容体，将来要恢复浮层入口只需在这里再接一根线。 */}
      <CreateGroupModal open={groupOpen} onClose={() => setGroupOpen(false)} />
      {/* ★DEV-226 需求⑪：「加入群组」的这个弹窗原本只挂在「搜索」弹框的群组 Tab 与
          智联录的「我的群组」里，现在**多了一个入口**（会话列表「+」菜单）。
          ★组件本体一行未改 —— 校验、四种结果的处置、"申请被拒时显示理由"
            仍走同一个实现（见 JoinGroupModal 的类注释）。
          ★onJoined 走 openConv（它会先切回「消息」Tab 再进会话），与「添加伙伴」的
            onDone 是同一条路（否则用户会停在一个没有变化的界面上）。
          ★★但**必须**照 SearchPanel 那样先 `setJoinOpen(false)` —— 这是搬家时踩到的真坑：
            `onJoined` 里只有 openConv（**没有** onClose），JoinGroupModal 自己也不关自己
            （它对"进会话"那两种结果只调 `reset()` + `onJoined`）。在原来那两处挂载点上，
            关掉是**副作用**：弹窗挂在搜索弹框 / 智联录里，`openConv` 切 Tab 把父组件卸载了，
            弹窗跟着消失。挂到 ChatPage 这一层之后父组件不会卸载 ⇒ 弹窗一直盖在
            **用户刚刚进去的那个会话**上面（2026-09-19 由 verify-join-group.mjs 的
            「★★status=member ⇒ 直接进会话（弹窗关闭）」抓到）。
            ★顺序也有意义：先关再进，否则弹窗会在新会话上闪一下。 */}
      <JoinGroupModal
        open={joinOpen || inviteGroupNo != null}
        // ★★DEV-356：邀请链接来的预填 + 说明（两个 prop 都不传时 = 既有行为逐字未变）。
        initialGroupNo={inviteGroupNo ?? undefined}
        hint={inviteGroupNo != null ? INVITE_CONFIRM_HINT : undefined}
        onClose={() => {
          setJoinOpen(false);
          // ★两个都要清：`open` 是"两者取或"，只清一个的话弹窗关不掉
          //   （见上面 inviteGroupNo 的注释）。
          setInviteGroupNo(null);
        }}
        onJoined={(convId) => {
          setJoinOpen(false);
          // ★同上：进群那条路也要一起清，否则弹窗会盖在用户刚进去的会话上。
          setInviteGroupNo(null);
          // ★本组件的 openConv 返回 void（SearchPanel 里那个是 Promise 版，
          //   所以那边写的是 `openConv(cid).catch(...)`）—— 这里不要照抄那个 `.catch`。
          openConv(convId);
        }}
      />
      <SearchPanel open={searchOpen} onClose={() => setSearchOpen(false)} />
      {/* ★「添加伙伴」取代了原来的「发起单聊」弹窗：那个弹窗只做"建会话"，
          而用户点这个入口的真实意图是"加个人"，通讯录落地是它的必要一半。 */}
      <AddPartnerModal open={partnerOpen} onClose={() => setPartnerOpen(false)} onDone={openConv} />
      {/* ★★「会议记录」浮层已随详情改弹框一并摘掉：它原本只剩一个"详情宿主"的职责，
          而详情现在由上面的 {@code MeetingDetailHost} 渲染（见 {@code lib/meetingDetailDialog}）；
          列表本身一直在 {@code MeetingPane} 的历史记录里常驻。 */}
    </div>
  );
}
