/**
 * ★NW-155：输入框草稿的 localStorage 持久化。
 *
 * <h2>为什么 HTML 也要存</h2>
 * <p>刷新前 {@code draftRef} 只活在内存里（DEV-225 的刻意取舍），刷新即失效；
 * store 里的 {@code draftTextByConv} 只有纯文本，用来给会话列表显示 {@code [草稿]}。
 * 用户要的是"刷新后输入框里没发出去的内容还在"，格式（加粗/颜色/@提及）也得在
 * ⇒ 必须存编辑器 HTML。
 *
 * <h2>★哪些东西不能跟着草稿活下来</h2>
 * <ul>
 *   <li><b>内联图片的二进制</b>：{@code blob:} 与待发送队列在刷新后都不存在了。
 *       ★★<b>DEV-426 反转了 NW-155 的口径</b>：图片的**位置**要活下来 ——
 *       HTML 保留 {@code data-rt-media} 锚点（{@code sanitizeDraftHtml} 只摘掉
 *       锚点里的 {@code <img>}），元数据记在 {@link DraftRecord.media}，
 *       二进制存 IndexedDB（{@code lib/draftMedia}）；</li>
 *   <li><b>主动内容</b>：{@code setHtml} 刻意不过 DOMPurify（DEV-225），
 *       而 localStorage 是同源可改的存储 ⇒ 恢复前补一道窄口径消毒。</li>
 * </ul>
 *
 * <h2>容量策略（宁可少存，不可写坏）</h2>
 * <ul>
 *   <li>最多 {@link MAX_DRAFT_CONVS} 个会话，按最近编辑时间保留；</li>
 *   <li>单条 HTML / 纯文本上限，超了就退化成"纯文本 HTML"（不硬切 HTML，避免半截标签）；</li>
 *   <li>总量上限，超出时从最旧的开始丢；</li>
 *   <li>写 localStorage 抛 {@code QuotaExceededError} 时继续丢最旧的再试，
 *       最终仍失败就返回 {@code false}（调用方不弹"已保存"）。</li>
 * </ul>
 *
 * <p>★所有函数都接受可注入的 {@link DraftIo}：本仓没有 jsdom，
 * 单测用内存实现即可覆盖 TTL / 容量 / 配额三条分支。
 */

import {
  escapeHtmlText,
  isBlankDraftHtml,
  sanitizeDraftHtml,
} from './mediaClipboard';
import {
  normalizeDraftMedia,
  type DraftMediaMeta,
} from './draftMedia';

/** 每个用户一个键：多账号共用一个浏览器时不许串味。 */
export const DRAFT_STORAGE_PREFIX = 'nuwax-im:drafts:v1:';
/** 30 天没动过的草稿视为过期（用户回来看见的应该是最近的上下文）。 */
export const DRAFT_TTL_MS = 30 * 24 * 60 * 60 * 1000;
/** 最多保留多少个会话的草稿。 */
export const MAX_DRAFT_CONVS = 80;
/** 单条草稿的 HTML 上限（字符数，不是字节）。 */
export const MAX_DRAFT_HTML_CHARS = 120_000;
/** 单条草稿的纯文本上限（只用于会话列表摘要 / 纯文本兜底）。 */
export const MAX_DRAFT_TEXT_CHARS = 20_000;
/** 一个用户全部草稿的字符总量上限。 */
export const MAX_TOTAL_CHARS = 500_000;

export interface DraftRecord {
  /** 编辑器 HTML（已经过 {@link sanitizeDraftHtml}）。 */
  html: string;
  /** 纯文本（用于回填 store 的 [草稿] 标记，以及 HTML 为空时的兜底）。 */
  text: string;
  /** 最近编辑时间（毫秒）。 */
  at: number;
  /**
   * ★★DEV-426：正文里内联图片的元数据（二进制在 IndexedDB）。
   *
   * <p>★`html` 里的锚点与这张表**必须成对**：锚点没有元数据 ⇒ 恢复时不知道该取
   * 哪份 blob（按元数据 id 取）；元数据没有锚点 ⇒ 那份图没有位置，发不出去。
   * 空表时**不写这个字段**（老版本的记录形状逐字不变）。
   */
  media?: DraftMediaMeta[];
}

export type DraftsByConv = Record<string, DraftRecord>;

/** 可注入的存储出口（单测用内存实现；业务用 {@link browserDraftIo}）。 */
export interface DraftIo {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/** 浏览器 localStorage。★任何访问异常（隐私模式、被禁用）都退化成"没有存储"。 */
export const browserDraftIo: DraftIo = {
  getItem(key) {
    try {
      return typeof localStorage === 'undefined' ? null : localStorage.getItem(key);
    } catch {
      return null;
    }
  },
  setItem(key, value) {
    if (typeof localStorage === 'undefined') throw new Error('localStorage unavailable');
    localStorage.setItem(key, value);
  },
  removeItem(key) {
    try {
      if (typeof localStorage !== 'undefined') localStorage.removeItem(key);
    } catch {
      // ★删不掉不是业务错误：下次读会照常按 TTL/容量淘汰。
    }
  },
};

/** 用户键（userId 为 0 / 空 ⇒ null，调用方据此跳过读写）。 */
export function draftStorageKey(userId: number | string | null | undefined): string | null {
  if (userId == null) return null;
  const s = String(userId);
  return s && s !== '0' ? `${DRAFT_STORAGE_PREFIX}${s}` : null;
}

/** 把一份 HTML/文本归一成可存盘的草稿；两者都为空 ⇒ null（调用方删除该条）。 */
export function normalizeDraft(
  html: string | null | undefined,
  text: string | null | undefined,
  now: number,
  media?: readonly DraftMediaMeta[],
): DraftRecord | null {
  const rawText = String(text ?? '').slice(0, MAX_DRAFT_TEXT_CHARS);
  let safeHtml = sanitizeDraftHtml(String(html ?? ''));
  let mediaList = normalizeDraftMedia(media);
  // ★超长时**不硬切** HTML（会留下半截标签）——退化成纯文本 HTML。
  //   ★DEV-426：纯文本里没有锚点 ⇒ 媒体表必须一起清空，否则 IndexedDB 里
  //   会留下"有二进制、没有位置"的孤儿（下次启动的 prune 才收得掉）。
  if (safeHtml.length > MAX_DRAFT_HTML_CHARS) {
    safeHtml = rawText ? escapeHtmlText(rawText).replace(/\n/g, '<br>') : '';
    mediaList = [];
  }
  // ★有文字、但 HTML 清洗后是空的（例如只有图/零宽字符）：用转义后的纯文本兜底。
  if (isBlankDraftHtml(safeHtml) && rawText.trim()) {
    safeHtml = escapeHtmlText(rawText).replace(/\n/g, '<br>');
    mediaList = [];
  }
  // ★★DEV-426：**只有图片、一个字没打**的草稿也算草稿（用户报的正是这条被整条丢掉）。
  if (isBlankDraftHtml(safeHtml) && !rawText.trim() && !mediaList.length) return null;
  return {
    html: safeHtml,
    text: rawText,
    at: now,
    ...(mediaList.length ? { media: mediaList } : {}),
  };
}

/** 按 TTL / 条数 / 总量裁剪。★返回值是新对象，不修改入参。 */
export function pruneDrafts(
  drafts: DraftsByConv,
  now: number,
  ttlMs: number = DRAFT_TTL_MS,
): DraftsByConv {
  const rows = Object.entries(drafts)
    .filter(([convId, d]) => convId && d
      && typeof d.html === 'string' && typeof d.text === 'string'
      && Number.isFinite(d.at)
      // ★允许一分钟的时钟偏差；远超"未来"的时间戳视为脏数据。
      && d.at <= now + 60_000
      && now - d.at <= ttlMs)
    .sort((a, b) => b[1].at - a[1].at)
    .slice(0, MAX_DRAFT_CONVS);

  const out: DraftsByConv = {};
  let total = 0;
  for (const [convId, d] of rows) {
    const len = d.html.length + d.text.length;
    // ★至少保留一条：即使单条超总量上限，也不能把用户的草稿全清空。
    if (total + len > MAX_TOTAL_CHARS && Object.keys(out).length > 0) continue;
    total += len;
    out[convId] = d;
  }
  return out;
}

function parseDrafts(raw: string | null): DraftsByConv {
  if (!raw) return {};
  try {
    const obj = JSON.parse(raw) as { v?: unknown; items?: unknown } | null;
    if (!obj || obj.v !== 1 || !obj.items || typeof obj.items !== 'object') return {};
    const out: DraftsByConv = {};
    for (const [convId, value] of Object.entries(obj.items as Record<string, unknown>)) {
      if (!convId || !value || typeof value !== 'object') continue;
      const d = value as Partial<DraftRecord>;
      if (typeof d.html !== 'string' || typeof d.text !== 'string' || !Number.isFinite(d.at)) continue;
      const media = normalizeDraftMedia(d.media);
      out[convId] = {
        html: d.html,
        text: d.text,
        at: Number(d.at),
        ...(media.length ? { media } : {}),
      };
    }
    return out;
  } catch {
    return {};
  }
}

/** 读出该用户的全部草稿（已过 TTL/容量裁剪）。读不到 ⇒ 空表，绝不抛。 */
export function loadDrafts(
  io: DraftIo,
  userId: number | string | null | undefined,
  now: number = Date.now(),
): DraftsByConv {
  const key = draftStorageKey(userId);
  if (!key) return {};
  return pruneDrafts(parseDrafts(io.getItem(key)), now);
}

/**
 * 写入该用户的全部草稿。
 *
 * @returns 是否真的写进去了。★配额溢出时会**从最旧的开始丢**再试，
 *          只有连一条都写不进去才返回 false。
 */
export function saveDrafts(
  io: DraftIo,
  userId: number | string | null | undefined,
  drafts: DraftsByConv,
  now: number = Date.now(),
): boolean {
  const key = draftStorageKey(userId);
  if (!key) return false;
  let current = pruneDrafts(drafts, now);
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const entries = Object.entries(current);
    if (!entries.length) {
      io.removeItem(key);
      return true;
    }
    try {
      io.setItem(key, JSON.stringify({ v: 1, items: current }));
      return true;
    } catch {
      // ★按 at 升序丢最旧的一条再试（配额一般是差一点点，通常一两次就过）。
      const oldest = entries.sort((a, b) => a[1].at - b[1].at)[0];
      const next = { ...current };
      delete next[oldest[0]];
      current = next;
    }
  }
  try {
    io.removeItem(key);
  } catch {
    // 忽略
  }
  return false;
}

/**
 * 写/更新一条草稿。
 *
 * <p>★空白内容等价于删除（用户把输入框清空了，列表上的 {@code [草稿]} 必须消失）。
 * 返回 {@code true} 表示"内容为空、已删除"，{@code false} 表示"已写入"。
 */
export function putDraft(
  io: DraftIo,
  userId: number | string | null | undefined,
  convId: string,
  html: string,
  text: string,
  now: number = Date.now(),
  media?: readonly DraftMediaMeta[],
): boolean {
  if (!convId) return false;
  const drafts = loadDrafts(io, userId, now);
  const record = normalizeDraft(html, text, now, media);
  if (!record) {
    delete drafts[convId];
    saveDrafts(io, userId, drafts, now);
    return true;
  }
  drafts[convId] = record;
  saveDrafts(io, userId, drafts, now);
  return false;
}

/** 删除一条草稿（发送成功、用户清空输入框）。 */
export function removeDraft(
  io: DraftIo,
  userId: number | string | null | undefined,
  convId: string,
  now: number = Date.now(),
): void {
  const key = draftStorageKey(userId);
  if (!key || !convId) return;
  const drafts = loadDrafts(io, userId, now);
  if (!(convId in drafts)) return;
  delete drafts[convId];
  saveDrafts(io, userId, drafts, now);
}

/** 清空该用户的全部草稿（登出/换账号）。 */
export function clearDrafts(
  io: DraftIo,
  userId: number | string | null | undefined,
): void {
  const key = draftStorageKey(userId);
  if (!key) return;
  io.removeItem(key);
}
