/**
 * ★★会议邀请消息在气泡里的样子。
 *
 * <h2>★它是"补点入口"，不是"来电页"</h2>
 *
 * <p>来电页（{@code MeetingInviteOverlay}）只在<b>实时到达</b>且用户空闲时弹一次；
 * 用户当时在开会、关掉了页面、或者干脆错过了铃声，这条消息必须还能在会话里点进去。
 * 所以卡片上直接给「加入会议」，不显示"回拨"之类会让人误解的措辞。
 *
 * <h2>★为什么不显示"已加入/已结束"</h2>
 *
 * <p>服务端的会议邀请消息只记录邀请本身，<b>不持久化</b>"这场会还在不在"。卡片去查一次
 * 会议详情既慢又可能查到别人的会（邀请人不一定是主持人）。按 DEV-251 的纪律：
 * 不知道的状态就不编 —— 点进去若会议已结束，会议侧会明确提示"会议不存在或已结束"。
 */
import { useState } from 'react';

import type { MessageDto } from '../api/types';
import { meetingInviteTitle, parseMeetingInvite } from '../lib/meetingInvite';
import { useCallStore } from '../store/call';
import { useMeetingInviteStore } from '../store/meetingInvite';
import { IconPhone, IconUsers, IconVideo } from './icons';

interface Props {
  message: MessageDto;
}

export default function MeetingInviteCard({ message }: Props) {
  const invite = parseMeetingInvite(message.body);
  const phase = useCallStore((s) => s.phase);
  const [hint, setHint] = useState<string | null>(null);

  const busy = phase !== 'idle';
  const title = invite ? meetingInviteTitle(invite) : '会议邀请';

  /**
   * ★★群通话卡片（{@code groupCall:true}，只会出现在群里那条静默卡片上）。
   *
   * <p>为什么不是"会议"口径：用户发起的是语音/视频通话，卡片说「会议」会让人以为
   * 点进去是一个会要开很久。图标也跟着媒体类型走 —— 语音卡片画话筒、视频卡片画摄像机，
   * 扫一眼就知道点进去要不要开摄像头。
   *
   * <p>★普通会议邀请（{@code groupCall} 缺省）保持原样：`IconUsers` + 会议号。
   */
  const isGroupCall = invite?.groupCall === true;
  const mediaLabel = invite?.mediaType === 'video' ? '视频通话' : '语音通话';

  const join = () => {
    if (!invite) return;
    // ★带上消息坐标：加入后要让同账号的其它端停掉这条邀请的铃声（3007 同步）
    const r = useMeetingInviteStore.getState().joinInvite(invite, {
      convId: String(message.convId),
      msgId: message.msgId == null ? undefined : String(message.msgId),
    });
    if (r === 'busy') setHint('你正在通话或会议中，请先结束后再加入');
    else setHint(r === 'none' ? '暂时无法加入，请稍后重试' : null);
  };

  return (
    <button
      type="button"
      className={`meet-invite-card${busy ? ' is-busy' : ''}`}
      title={
        busy
          ? '你正在通话或会议中'
          : isGroupCall
            ? `加入${mediaLabel} ${invite?.roomName ?? ''}`
            : `加入会议 ${invite?.roomName ?? ''}`
      }
      disabled={!invite}
      onClick={invite ? join : undefined}
    >
      <span className="meet-invite-card-icon">
        {isGroupCall ? (
          invite?.mediaType === 'video' ? (
            <IconVideo size={18} />
          ) : (
            <IconPhone size={18} />
          )
        ) : (
          <IconUsers size={18} />
        )}
      </span>
      <span className="meet-invite-card-text">
        <span className="meet-invite-card-title">{title}</span>
        <span className="meet-invite-card-sub">
          {invite
            ? isGroupCall
              ? `${mediaLabel} · ${busy ? '结束后可加入' : '点击加入'}`
              : `会议号 ${invite.roomName} · ${busy ? '结束后可加入' : '点击加入'}`
            : '邀请信息不完整'}
        </span>
        {hint && <span className="meet-invite-card-hint">{hint}</span>}
      </span>
    </button>
  );
}
