/**
 * ★★会中「会议信息」面板 —— 对齐飞书左上角那个「会议信息」入口。
 *
 * <h2>放什么</h2>
 *
 * <ul>
 *   <li>会议主题、会议号（3-3-3 分组展示，复制时用未分组的原值）；</li>
 *   <li>统一入会链接（登录/未登录都能用同一条，见 {@code lib/meetingLink}）；</li>
 *   <li>开始时间与会中时长、当前参会人数；</li>
 *   <li>底部两个入口：「邀请参会人」（从我的联系人里拉人，见 {@code MeetingInvitePanel}）
 *       与「复制邀请信息」（整段飞书式邀请文案）。</li>
 * </ul>
 *
 * <h2>★★为什么是自绘面板</h2>
 *
 * <p>与会中界面一样，它可能渲染在<b>独立窗口</b>（{@code MeetingPopout}）里 ——
 * 那是另一个 document，antd v5 的 cssinjs 样式只在主文档，Modal 在那边会变成裸控件。
 * 所以这里只用项目自己的类（独立窗口整份克隆 {@code styles.css}）。
 *
 * <p>★也正因为渲染在另一个 document，复制必须显式把<b>面板所属的 document</b>
 * 传给 {@code copyText}：{@code execCommand('copy')} 落在主文档上会直接失败，
 * 用户看到的是"点了复制没反应"（见 {@code lib/clipboard} 的文件头）。
 */
import { useEffect, useRef, useState } from 'react';

import { copyText } from '../lib/clipboard';
import { formatMeetingId } from '../lib/meetingLink';
import { IconExternal, IconUsersPlus } from './icons';

export interface MeetingInfoPanelProps {
  /** 会议主题。 */
  title: string;
  /** 会议号（= LiveKit 房间名），原值。 */
  roomNo: string;
  /** 统一入会链接；空则不显示这一行。 */
  inviteUrl?: string;
  /** 整段邀请文案（复制用）；空则退回复制链接。 */
  inviteText?: string;
  /** 会议开始时刻（毫秒）。 */
  startedAt?: number;
  /** 会中时长文本（`00:11`）。 */
  elapsedText?: string;
  /** 时长上限的人话描述：`2 小时`；空 ⇒ 这场会没有上限信息，不显示这一行。 */
  durationLimitText?: string;
  /** 剩余时长文本（`1:32:10`）；到点后是 `已到时长上限`。 */
  remainingText?: string;
  /** 剩余不足 10 分钟时高亮，提示快结束了。 */
  remainingWarn?: boolean;
  /** 当前参会人数。 */
  people: number;
  /** 从我的联系人邀请（只有登录用户有；游客不传 ⇒ 只保留复制入口）。 */
  onInvite?: () => void;
  onClose: () => void;
}

/** 开始时间：今天只显示时分，跨天补上日期 —— 一眼能判断"这会开了多久"。 */
function formatStartedAt(ms?: number): string {
  if (!ms || !Number.isFinite(ms)) return '';
  const d = new Date(ms);
  if (Number.isNaN(d.getTime())) return '';
  const hh = `${d.getHours()}`.padStart(2, '0');
  const mm = `${d.getMinutes()}`.padStart(2, '0');
  const now = new Date();
  const sameDay =
    d.getFullYear() === now.getFullYear() &&
    d.getMonth() === now.getMonth() &&
    d.getDate() === now.getDate();
  return sameDay
    ? `${hh}:${mm}`
    : `${d.getMonth() + 1}月${d.getDate()}日 ${hh}:${mm}`;
}

export default function MeetingInfoPanel(props: MeetingInfoPanelProps) {
  const {
    title,
    roomNo,
    inviteUrl,
    inviteText,
    startedAt,
    elapsedText,
    durationLimitText,
    remainingText,
    remainingWarn,
    people,
    onInvite,
    onClose,
  } = props;

  const panelRef = useRef<HTMLDivElement | null>(null);
  /** 复制反馈：`{ text, fail }`；1.8 秒后自动消失。 */
  const [flash, setFlash] = useState<{ text: string; fail: boolean } | null>(null);
  const timer = useRef<number | null>(null);

  useEffect(
    () => () => {
      if (timer.current != null) window.clearTimeout(timer.current);
    },
    [],
  );

  /** ★Esc 关闭要挂在面板所属的 document 上（独立窗口是另一个 document）。 */
  useEffect(() => {
    const doc = panelRef.current?.ownerDocument ?? document;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    doc.addEventListener('keydown', onKey);
    return () => doc.removeEventListener('keydown', onKey);
  }, [onClose]);

  const showFlash = (text: string, fail: boolean) => {
    setFlash({ text, fail });
    if (timer.current != null) window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setFlash(null), 1800);
  };

  const copy = async (text: string, okText: string) => {
    const doc = panelRef.current?.ownerDocument ?? document;
    const ok = await copyText(text, undefined, doc);
    showFlash(ok ? okText : '复制失败，请手动选中复制', !ok);
  };

  const startedLabel = formatStartedAt(startedAt);
  const displayNo = formatMeetingId(roomNo);

  return (
    <div
      className="meet-info-layer"
      // 点遮罩关闭；点面板内部不关（否则选文字都会把面板关掉）
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="meet-info-panel" role="dialog" aria-modal="true" aria-label="会议信息" ref={panelRef}>
        <div className="meet-info-head">
          <span className="meet-info-title">会议信息</span>
          <button type="button" className="meet-info-x" title="关闭" onClick={onClose}>
            ×
          </button>
        </div>

        <div className="meet-info-body">
          <div className="meet-info-topic" title={title}>
            {title || '未命名会议'}
          </div>

          <div className="meet-info-row">
            <span className="meet-info-label">会议号</span>
            <span className="meet-info-value is-no">{displayNo || '—'}</span>
            {roomNo && (
              <button
                type="button"
                className="meet-info-copy"
                onClick={() => void copy(roomNo, '已复制会议号')}
              >
                复制
              </button>
            )}
          </div>

          {inviteUrl && (
            <div className="meet-info-row">
              <span className="meet-info-label">入会链接</span>
              <span className="meet-info-value is-link" title={inviteUrl}>
                {inviteUrl}
              </span>
              <button
                type="button"
                className="meet-info-copy"
                onClick={() => void copy(inviteUrl, '已复制链接')}
              >
                复制
              </button>
            </div>
          )}

          <div className="meet-info-row">
            <span className="meet-info-label">开始时间</span>
            <span className="meet-info-value">
              {startedLabel || '—'}
              {elapsedText ? ` · 已进行 ${elapsedText}` : ''}
            </span>
          </div>

          {durationLimitText && (
            <div className="meet-info-row">
              <span className="meet-info-label">会议时长</span>
              <span className={`meet-info-value${remainingWarn ? ' is-warn' : ''}`}>
                限时 {durationLimitText}
                {remainingText ? ` · 剩余 ${remainingText}` : ''}
              </span>
            </div>
          )}

          <div className="meet-info-row">
            <span className="meet-info-label">参会人</span>
            <span className="meet-info-value">{people} 人</span>
          </div>

          {flash && (
            <div className={`meet-info-flash${flash.fail ? ' is-fail' : ''}`}>{flash.text}</div>
          )}
        </div>

        <div className="meet-info-foot">
          <button
            type="button"
            className="meet-info-btn"
            disabled={!inviteUrl && !inviteText}
            onClick={() => void copy(inviteText || inviteUrl || '', '已复制邀请信息')}
          >
            <IconExternal size={14} />
            复制邀请信息
          </button>
          {onInvite && (
            <button type="button" className="meet-info-btn is-primary" onClick={onInvite}>
              <IconUsersPlus size={14} />
              邀请参会人
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
