/**
 * ★★DEV-437：{@link TenantBrand} 的 React 取数钩子。
 *
 * <p>★三态刻意区分开（这是本钩子的全部价值）：
 * <ul>
 *   <li>{@code undefined} = <b>还在请求</b> —— 此时不要拿 origin 先渲染一版二维码：
 *       101 的 origin 是 http，先出一张 http 的码，等请求回来再换成 https，
 *       用户若在这一瞬间点了下载，存下来的就是一张"看起来没问题、指向明文地址"的图；</li>
 *   <li>{@code TenantBrand} = 成功（其中 {@code siteUrl}/{@code siteLogo} 各自可能为 null）；</li>
 *   <li>{@code null} = 拿不到 ⇒ 调用方回退到当前页面地址。</li>
 * </ul>
 *
 * <p>★{@code enabled} 用于"弹窗没打开就别打接口"；面板那一行本来就要显示链接，恒为 true。
 */
import { useEffect, useState } from 'react';

import { getTenantBrand, type TenantBrand } from './tenantBrand';

export function useTenantBrand(enabled = true): TenantBrand | null | undefined {
  const [brand, setBrand] = useState<TenantBrand | null | undefined>(enabled ? undefined : null);

  useEffect(() => {
    if (!enabled) return undefined;
    let alive = true;
    // ★getTenantBrand 自己吞掉所有异常（折成 null），这里不需要 catch。
    getTenantBrand().then((b) => {
      if (alive) setBrand(b);
    });
    return () => {
      alive = false;
    };
  }, [enabled]);

  return brand;
}
